window.HB_TR["numbers"]["ur"]=["1۔ اور خداوند نے موسیٰ سے سینا کے بیابان میں، جماعت کے خیمے میں، دوسرے مہینے کے پہلے دن، جب وہ مصر کی سرزمین سے نکلے تھے، کہا،\n2۔ آپ بنی اسرائیل کی تمام جماعتوں کا مجموعہ، ان کے خاندانوں کے بعد، ان کے باپ اجداد کے گھر سے، ان کے ناموں کی تعداد کے ساتھ، ہر مرد کو ان کے اعداد و شمار کے مطابق لے لو؛\n3۔ بیس سال کی عمر سے لے کر اس سے اوپر، جو بھی اسرائیل میں جنگ کے لیے نکلنے کے قابل ہے: تم اور ہارون انہیں ان کی فوجوں کے حساب سے گنو۔\n4۔ اور تمہارے ساتھ ہر قبیلے کا ایک آدمی ہوگا؛ اپنے والد کے گھر کے ہر سربراہ کو۔\n5۔ اور یہ ان لوگوں کے نام ہیں جو تمہارے ساتھ کھڑے ہوں گے: روبن کے قبیلے کے؛ ایلیزور، شیڈیور کا بیٹا۔\n6۔ شمعون کی؛ شیلومیئل، زوری شادائی کا بیٹا۔\n7۔ یہوداہ کی؛ ناہشون، امیناداب کا بیٹا۔\n8۔ اساکر کی؛ نیتھنیئل، زوار کا بیٹا۔\n9۔ زبولون کی؛ ایلیاب، ہیلون کا بیٹا۔\n10۔ یوسف کے بچوں میں: افرائیم کے؛ الیشمہ، امیہود کا بیٹا: منسا کا؛ گمالیئل، پیڈاہزور کا بیٹا۔\n11۔ بینجمن کی؛ عابدان، گدعونی کا بیٹا۔\n12۔ ڈین کی؛ احیزر امیشادائی کا بیٹا۔\n13۔ آشر کی؛ پاگیل، اوکران کا بیٹا۔\n14۔ گاد کی؛ ایلیاساف، ڈیوئل کا بیٹا۔ {ڈیوئل: جسے ریویل بھی کہا جاتا ہے}\n15۔ نفتالی کی؛ اہیرا، اینان کا بیٹا۔\n16۔ یہ جماعت کے مشہور لوگ تھے، اپنے آباؤ اجداد کے قبائل کے شہزادے، اسرائیل میں ہزاروں کے سربراہ۔\n17۔ اور موسیٰ اور ہارون نے ان لوگوں کو لیا جو {ان} کے ناموں سے ظاہر ہوتے ہیں:\n18۔ اور انہوں نے دوسرے مہینے کے پہلے دن تمام جماعت کو اکٹھا کیا، اور اپنے خاندانوں کے نام پر، ان کے والد کے گھرانے کے مطابق، بیس سال سے زائد عمر کے ناموں کی تعداد کے مطابق، اپنے پول کے مطابق اپنی نسل کا اعلان کیا۔\n19۔ جیسا کہ خداوند نے موسیٰ کو حکم دیا، ویسے ہی اس نے انہیں سینا کے بیابان میں گنوایا۔\n20۔ اور روبن کے بیٹے، اسرائیل کے سب سے بڑے بیٹے، اپنی نسلوں سے، اپنے خاندانوں کے بعد، اپنے باپ کے گھرانے کے مطابق، ناموں کی تعداد کے مطابق، ان کے خاندانوں کے مطابق، بیس سال کی عمر سے اس سے اوپر کے ہر مرد کے مطابق، جو جنگ کے لیے جانے کے قابل تھا؛\n21۔ جو لوگ ان میں شمار کیے گئے، {حتی} روبن قبیلے سے، {تھا} چالیس چھ ہزار پانچ سو۔\n22۔ شمعون کے بچوں سے، اپنی نسلوں کے مطابق، ان کے خاندانوں کے بعد، ان کے باپ کے گھرانے کے مطابق، جو ان میں سے گنے گئے، ناموں کی تعداد کے مطابق، ان کے پولز کے مطابق، بیس سال کی عمر سے اور اس سے اوپر کے ہر مرد، جو جنگ میں جانے کے قابل تھے؛\n23۔ جو لوگ ان میں شمار کیے گئے، {حتیٰ کہ} قبیلہ شمعون سے، {پچاس نو ہزار تین سو} تھے۔\n24۔ گاد کے بچوں میں، اپنی نسلوں کے لحاظ سے، ان کے خاندانوں کے بعد، ان کے باپ کے گھرانے سے، ان کے ناموں کی تعداد کے مطابق، بیس سال اور اس سے اوپر، جو بھی جنگ کے لیے جانے کے قابل تھے؛\n25۔ جو لوگ ان میں شمار ہوئے، {حتیٰ کہ} قبیلہ گاد کے تھے، {تھا} چالیس پانچ ہزار چھ سو پچاس۔\n26۔ یہوداہ کے بچوں سے، اپنی نسلوں کے مطابق، اپنے خاندانوں کے بعد، اپنے باپ کے گھرانے کے مطابق، ناموں کی تعداد کے مطابق، بیس سال اور اس سے اوپر، جو بھی جنگ میں جانے کے قابل تھا؛\n27۔ جو لوگ ان میں شمار کیے گئے، {حتی} یہوداہ قبیلے کے، {تھے} تیس اور چودہ ہزار چھ سو۔\n28۔ اساکار کے بچوں سے، اپنی نسلوں کے مطابق، ان کے خاندانوں کے بعد، ان کے باپ کے گھرانے کے مطابق، ناموں کی تعداد کے مطابق، بیس سال کی عمر سے اوپر، جو بھی جنگ کے لیے نکلنے کے قابل تھا؛\n29۔ جو لوگ ان میں شمار کیے گئے، {حتیٰ کہ} یساکر قبیلے کے تھے، {تھے} پچاس چار ہزار چار سو۔\n30۔ زبولون کے بچوں سے، اپنی نسلوں کے مطابق، ان کے خاندانوں کے بعد، ان کے باپ و اجداد کے گھرانے سے، بیس سال کی عمر اور اس سے اوپر کے ناموں کی تعداد کے مطابق، جو بھی جنگ میں جانے کے قابل تھے؛\n31۔ ان میں سے {حتیٰ کہ} زبولون قبیلے کے افراد کی تعداد پچاس سات ہزار چار سو تھی۔\n32۔ یوسف کے بچوں کی، {یعنی}، افرائیم کے بچوں سے، اپنی نسلوں کے مطابق، ان کے خاندانوں کے بعد، ان کے باپ و اجداد کے گھرانے سے، ان سب کے ناموں کی تعداد کے مطابق، جو بیس سال کی عمر سے اور اس سے زیادہ تھے، جو جنگ میں جانے کے قابل تھے؛\n33۔ جو لوگ ان میں شمار کیے گئے، {حتیٰ کہ} افریم قبیلے سے، {تھے} چالیس ہزار پانچ سو۔\n34۔ مناسی کے بچوں سے، اپنی نسلوں کے مطابق، اپنے خاندانوں کے بعد، ان کے باپ کے گھرانے کے مطابق، بیس سال کی عمر سے اور اس سے اوپر، جو بھی جنگ کے لیے نکلنے کے قابل تھے؛\n35۔ جو لوگ ان میں شمار کیے گئے، {حتیٰ کہ} مناسیہ قبیلے کے، {تھے} تیس دو ہزار دو سو۔\n36۔ بنیامین کے بچوں سے، اپنی نسلوں کے مطابق، اپنے خاندانوں کے بعد، اپنے باپ کے گھرانے کے مطابق، بیس سال کی عمر سے اس سے اوپر، جو سب جنگ کے لیے جانے کے قابل تھے؛\n37۔ جو لوگ ان میں شمار کیے گئے، {حتی} بنیامین قبیلے سے، {تھے} تیس پانچ ہزار چار سو۔\n38۔ دان کے بچوں سے، اپنی نسلوں کے مطابق، اپنے خاندانوں کے بعد، اپنے باپ کے گھرانے کے مطابق، بیس سال اور اس سے اوپر کے ناموں کی تعداد کے مطابق، جو بھی جنگ کے لیے جانے کے قابل تھے؛\n39۔ جو لوگ ان میں شمار کیے گئے، {حتی} دان قبیلے سے، {300} اور دو ہزار سات سو تھے۔\n40۔ آشر کے بچوں سے، اپنی نسلوں کے مطابق، اپنے خاندانوں کے بعد، ان کے باپ کے گھرانے کے مطابق، بیس سال کی عمر اور اس سے اوپر کے ناموں کی تعداد کے مطابق، جو بھی جنگ میں جانے کے قابل تھے؛\n41۔ جو لوگ ان میں شمار کیے گئے، {حتی} آشر قبیلے سے، {تھے} چالیس ہزار پانچ سو۔\n42۔ نفتالی کے بچوں میں، اپنی نسلوں کے بعد، اپنے خاندانوں کے بعد، اپنے باپ کے گھرانے سے، ناموں کی تعداد کے مطابق، بیس سال اور اس سے اوپر، جو بھی جنگ کے لیے جانے کے قابل تھے؛\n43۔ جو لوگ ان میں شمار کیے گئے، {حتیٰ کہ} نفتالی قبیلے سے بھی، {پچاس] تین ہزار چار سو تھے۔\n44. یہ وہ لوگ ہیں جنہیں موسیٰ اور ہارون نے گنا تھا، اور اسرائیل کے شہزادے، جو بارہ آدمی تھے: ہر ایک اپنے باپ و اجداد کے گھرانے کے لیے تھا۔\n45۔ اسی طرح وہ تمام لوگ جو اسرائیل کے بچوں میں سے اپنے باپ و اجداد کے گھرانے سے بیس سال یا اس سے زیادہ عمر کے تھے، وہ سب جو اسرائیل میں جنگ کے لیے جانے کے قابل تھے؛\n46۔ یہاں تک کہ جن سب کو شمار کیا گیا وہ چھ لاکھ تین ہزار پانچ سو پچاس تھے۔\n47۔ لیکن لاوی جو اپنے آباؤ اجداد کے قبیلے کے بعد تھے، ان میں شمار نہیں تھے۔\n48۔ کیونکہ خداوند نے موسیٰ سے کہا تھا،\n49. صرف تو لاوی قبیلے کو گننا نہ دو، نہ ہی ان کی تعداد بنی اسرائیل میں شمار کرو:\n50۔ لیکن تم لاویوں کو گواہی کے خیمے پر، اس کے تمام برتنوں پر، اور اس کی تمام چیزوں پر مقرر کرو گے: وہ خیمہ اور اس کے تمام برتن اٹھائیں گے؛ اور وہ اس کی خدمت کریں گے، اور خیمہ گاہ کے ارد گرد خیمہ زن ہوں گے۔\n51۔ اور جب خیمہ آگے بڑھے گا، تو لاوی اسے گرا دیں گے: اور جب خیمہ قائم کیا جائے تو لاوی اسے قائم کریں گے: اور جو اجنبی قریب آئے گا اسے قتل کر دیا جائے گا۔\n52۔ اور بنی اسرائیل اپنے خیمے کھڑا کریں گے، ہر آدمی اپنے اپنے کیمپ سے، اور ہر آدمی اپنے جھنڈے پر، اپنے لشکروں میں۔\n53. لیکن لاوی گواہی کے خیمے کے گرد گھوم جائیں گے تاکہ بنی اسرائیل کی جماعت پر کوئی غصہ نہ ہو، اور لاوی گواہی کے خیمے کی ذمہ داری سنبھالیں گے۔\n54۔ اور بنی اسرائیل نے وہ سب کچھ کیا جو خداوند نے موسیٰ کو حکم دیا، انہوں نے بھی ایسا ہی کیا۔","1۔ اور خداوند نے موسیٰ اور ہارون سے کہا،\n2۔ بنی اسرائیل کا ہر آدمی اپنے جھنڈے پر، اپنے والد کے گھر کے جھنڈے کے ساتھ پچ کرے گا: جماعت کے خیمے کے آس پاس دور سے پچیں گے۔ {دور...: عبرانی۔ اوور اگینسٹ}\n3۔ اور مشرق کی طرف سورج کے طلوع آفتاب کی طرف یہوداہ کے جھنڈ کے جھنڈ والے اپنی فوجوں کے ساتھ کھڑے ہوں گے: اور ناہشون، امناداب کا بیٹا، یہوداہ کے بچوں کا کپتان ہوگا۔\n4۔ اور اس کا لشکر، اور ان میں سے جو گنے گئے تھے، تین سو چودہ ہزار چھ سو تھے۔\n5۔ اور جو اس کے ساتھ پھینکیں گے وہ اساکر کے قبیلے میں ہوں گے: اور نیتھانیئل زوار کا بیٹا اساکر کے بچوں کا کپتان ہوگا۔\n6۔ اور اس کا لشکر اور اس کے شمار میں شامل افراد کی تعداد پچاس چار ہزار چار سو تھی۔\n7۔ {پھر} قبیلہ زبولون: اور ایلیاب ہیلون کا بیٹا {ہوگا} زبولون کے بچوں کا کپتان۔\n8۔ اور اس کا لشکر اور اس کے شمار میں شامل افراد کی تعداد پچاس سات ہزار چار سو تھی۔\n9۔ یہوداہ کے کیمپ میں شمار ہونے والے سب اپنی فوجوں میں ایک لاکھ چولیس ہزار چھ ہزار چار سو تھے۔ یہ سب سے پہلے روانہ ہوں گے۔\n10۔ جنوبی جانب روبن کے کیمپ کا جھنڈا ان کی فوجوں کے مطابق ہوگا: اور روبن کے بچوں کا کپتان الیزور ہوگا، شیدور کا بیٹا۔\n11۔ اور اس کی لشکری اور اس میں شامل افراد کی تعداد چالیس چھ ہزار پانچ سو تھی۔\n12۔ اور جو لوگ اس کے پاس جائیں گے وہ شمعون قبیلہ ہوں گے: اور شمعون کے بچوں کا کپتان شیلومیئل ہوگا، زریشادائی کا بیٹا۔\n13۔ اور اس کی فوج، اور ان میں سے گننے والے، پچاس نو ہزار تین سو تھے۔\n14۔ پھر گاد کا قبیلہ: اور گاد کے بیٹوں کا کپتان {ہوگا} ایلیاصاف، روئیل کا بیٹا۔ {روئل: جسے دیوئل بھی کہا جاتا ہے}\n15۔ اور اس کی فوج، اور ان میں سے جو لوگ شمار ہوئے، چالیس پانچ ہزار چھ سو پچاس تھے۔\n16۔ روبن کے کیمپ میں شامل تمام لوگ اپنی فوجوں میں ایک لاکھ ڈیڑھ ہزار چار سو پچاس ہزار تھے۔ اور وہ دوسری قطار میں روانہ ہوں گے۔\n17۔ پھر جماعت کا خیمہ لاویوں کے کیمپ کے ساتھ کیمپ کے بیچ میں آگے بڑھے گا: جیسے وہ خیمہ لگائیں گے، ویسے ہی ہر شخص اپنی جگہ پر اپنے معیار کے مطابق کھڑا ہوگا۔\n18۔ مغربی جانب افرایم کے کیمپ کا جھنڈا ان کی فوجوں کے مطابق ہوگا: اور افرائیم کے بیٹوں کا کپتان الیشامہ ہوگا، جو امیہود کا بیٹا ہے۔\n19۔ اور اس کا لشکر، اور ان میں سے جو گننے والے تھے، چالیس ہزار پانچ سو تھے۔\n20۔ اور اس کے ذریعے منسی قبیلہ ہوگا: اور منسی کے بچوں کا کپتان گمالیئل، پدازور کا بیٹا ہوگا۔\n21۔ اور اس کا لشکر، اور ان میں سے جو گنے گئے تھے، تیس دو ہزار دو سو تھے۔\n22۔ پھر بنیامین کا قبیلہ: اور بنیامین کے بیٹوں کا کپتان عبیدان، گدعونی کا بیٹا ہوگا۔\n23۔ اور اس کی فوج، اور ان میں سے جو گنے گئے تھے، تیس پانچ ہزار چار سو تھے۔\n24۔ افرائیم کے کیمپ کے تمام افراد اپنی فوجوں میں ایک لاکھ آٹھ ہزار اور سو تھے۔ اور وہ تیسری قطار میں آگے بڑھیں گے۔\n25۔ دان کے کیمپ کا جھنڈا ان کی فوجوں کے ساتھ شمال کی طرف ہوگا: اور دان کے بچوں کا کپتان احیزر ہوگا، جو امیشادائی کا بیٹا ہوگا۔\n26۔ اور اس کا لشکر، اور ان میں سے جو گنے گئے تھے، تین سو دو ہزار سات سو تھے۔\n27۔ اور جو لوگ اس کے ساتھ خیمہ زن ہوں گے وہ آشر کے قبیلے میں ہوں گے: اور آشر کے بچوں کا کپتان پاگیئل، اوکران کا بیٹا ہوگا۔\nاٹھائیس۔ اور اس کی فوج، اور ان میں سے جو لوگ شمار ہوئے، چالیس ہزار پانچ سو تھے۔\n29۔ پھر نفتالی کا قبیلہ: اور نفتالی کے بچوں کا کپتان {ہوگا} احیرا، اینان کا بیٹا۔\n30۔ اور اس کی لشکری اور ان میں سے جو گنے گئے تھے، وہ پچاس تین ہزار چار سو تھے۔\n31۔ دان کے کیمپ میں شامل تمام لوگ ایک لاکھ پچاس سات ہزار چھ سو تھے۔ وہ اپنے معیار میں سب سے پیچھے رہ جائیں گے۔\n32. یہ وہ ہیں جنہیں بنی اسرائیل کے خاندان نے ان کے باپ و اجداد کے گھرانے شمار کیے: جو بھی کیمپوں میں شمار کیے گئے تھے، وہ چھ لاکھ تین ہزار پانچ سو پچاس تھے۔\n33۔ لیکن لاوی کو بنی اسرائیل میں شمار نہیں کیا گیا؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n34۔ اور بنی اسرائیل نے وہ سب کچھ کیا جو خداوند نے موسیٰ کو حکم دیا تھا: تو انہوں نے اپنے اصولوں کے مطابق قدم بڑھایا، اور سب اپنے خاندان کے پیچھے اپنے باپ دادا کے گھر کے مطابق روانہ ہوئے۔","1۔ یہ بھی وہ نسلیں ہیں جو ہارون اور موسیٰ کی وہ نسلیں ہیں جب خداوند نے کوہ سینا میں موسیٰ سے بات کی۔\n2۔ اور یہ ہارون کے بیٹوں کے نام ہیں؛ نادب، پہلا بیٹا، اور ابیہو، الیعازر، اور ایثمار۔\n3۔ یہ ہارون کے بیٹوں کے نام ہیں، وہ کاہنیں جنہیں مسح کیا گیا اور جنہیں اس نے پادری کے دفتر میں خدمت کے لیے مقرر کیا۔ {کون...: عبرانی جس کا ہاتھ اس نے بھر دیا}\n4۔ اور نداب اور ابیہو خداوند کے سامنے مر گئے، جب انہوں نے خداوند کے سامنے سینا کے بیابان میں عجیب آگ پیش کی، اور ان کے کوئی بچے نہ تھے: اور الیعازر اور ایثمار نے اپنے باپ ہارون کے سامنے کاہن کے دفتر میں خدمت کی۔\n5۔ اور خداوند نے موسیٰ سے کہا،\n6۔ لاوی قبیلے کو قریب لاؤ، اور انہیں ہارون کاہن کے سامنے پیش کرو، تاکہ وہ اس کی خدمت کریں۔\n7۔ اور وہ اس کی ذمہ داری اور پوری جماعت کی ذمہ داری عبادت گاہ کے سامنے رکھیں گے، تاکہ وہ عبادت گاہ کی خدمت انجام دے۔\n8۔ اور وہ جماعت کے خیمے کے تمام آلات اور بنی اسرائیل کی ذمہ داری کو خیمہ کی خدمت کے لیے سنبھالیں گے۔\n9۔ اور تو لاویوں کو ہارون اور اس کے بیٹوں کو دے دینا: وہ سب کچھ اسے بنی اسرائیل کی طرف سے مکمل طور پر عطا کیے گئے ہیں۔\n10۔ اور تم ہارون اور اس کے بیٹوں کو مقرر کرو گے، اور وہ اپنے پادری کے عہدے پر انتظار کریں گے: اور جو اجنبی قریب آئے گا اسے قتل کر دیا جائے گا۔\n11۔ اور خداوند نے موسیٰ سے کہا،\n12. اور میں نے دیکھو، میں نے اسرائیل کے بچوں میں سے لاویوں کو لے لیا ہے، بجائے اس کے کہ وہ سب سے پہلے جو بنی اسرائیل کے اندر سے راستہ کھولتا ہے: اس لیے لاوی میرے ہوں گے؛\n13۔ کیونکہ تمام پہلے بچے میرے ہیں؛ {کیونکہ} جس دن میں نے مصر کی سرزمین میں سب سے پہلے والے بچوں کو مارا ہے، میں نے اسرائیل کے تمام پہلے بچوں، انسان اور جانور دونوں، اپنے لیے مقدس قرار دیا: وہ میرے ہوں گے: میں {ہوں} خداوند ہوں۔\n14۔ اور خداوند نے سینا کے بیابان میں موسیٰ سے کہا،\n15۔ لاوی کے بچوں کو ان کے باپوں کے گھر کے حساب سے، ان کے خاندانوں کے حساب سے گننا: ہر مرد ایک ماہ کی عمر سے اور اس سے اوپر انہیں گننا ہوگا۔\n16۔ اور موسیٰ نے انہیں خداوند کے کلام کے مطابق گنایا، جیسا کہ اسے حکم دیا گیا تھا۔ {لفظ: عبرانی۔ منہ}\n17۔ اور یہ لاوی کے بیٹے تھے ان کے ناموں سے؛ گرشون، کوہاتھ، اور میراری۔\n18۔ اور یہ {ہیں} گرشون کے بیٹوں کے ان کے خاندانوں کے نام ہیں؛ لبنی اور شیمئی۔\n19۔ اور کوہات کے بیٹے اپنے خاندانوں سے؛ امرام، اور ایزہار، حبرون، اور عزیل۔\n20۔ اور مراری کے بیٹے اپنے خاندانوں سے؛ مہلی، اور مشی۔ یہ لاویوں کے خاندان ہیں جو ان کے باپ و اجداد کے گھر کے مطابق ہیں۔\n21۔ گرشون کا لبنائیوں کا خاندان تھا، اور شیمیوں کا خاندان: یہ گرشونیوں کے خاندان ہیں۔\n22۔ جن میں سے سب مردوں کی تعداد کے مطابق، ایک ماہ کی عمر سے اوپر، {حتیٰ کہ} ان میں شمار کیے گئے وہ سات ہزار پانچ سو تھے۔\n23۔ گرشونائیوں کے خاندان خیمہ کے پیچھے مغرب کی طرف میدان میں پیش کریں گے۔\n24۔ اور گرشونیوں کے والد کے گھرانے کا سردار {ہوگا} ایلیاساف، لائل کا بیٹا۔\n25۔ اور گرشون کے بیٹوں کی جماعت کے خیمے میں ذمہ داری خیمہ خانہ، خیمے، اس کا ڈھانپ، اور جماعت کے خیمے کے دروازے کے لیے لٹکانے کی ذمہ داری ہوگی،\n26۔ اور صحن کے لٹکنے والے، اور صحن کے دروازے کے لیے پردہ، جو خیمہ گاہ کے پاس ہے، اور اس کے ارد گرد محراب کے پاس، اور اس کی رسیاں اس کی تمام خدمات کے لیے۔\n27۔ اور کوہات کا {تھا} امرمیوں کا خاندان، ایزہاریوں کا خاندان، اور ہبرونیوں کا خاندان، اور اوزیلائیوں کا خاندان: یہ {ہیں} کوہاتیوں کے خاندان۔\n28۔ تمام مردوں کی تعداد میں، ایک ماہ کی عمر سے لے کر اس سے اوپر، آٹھ ہزار چھ سو تھے، جو مقدس مقام کی ذمہ داری رکھتے تھے۔\n29۔ کوہات کے بیٹوں کے خاندان تابوت کے جنوب کی طرف پچ کریں گے۔\n30۔ اور کوہاتی خاندانوں کے والد کے گھر کا سردار عزیل کا بیٹا الیزفان ہوگا۔\n31۔ اور ان کی ذمہ داری صندوق، میز، شمعدان، قربان گاہیں، اور مقدس مقام کے برتن جن سے وہ خدمت کرتے ہیں، اور پھانسی اور اس کی تمام خدمات ہوں گی۔\n32۔ اور الیعزر، جو ہارون کاهن کا بیٹا ہے، لاویوں کے سردار کا سردار ہوگا، اور ان لوگوں کی نگرانی کرے گا جو مقدس مقام کی نگرانی کرتے ہیں۔\n33۔ میراری کا {تھا} مہلیوں کا خاندان تھا، اور مشیتوں کا خاندان: یہ {ہیں} میراری کے خاندان۔\n34۔ اور جو ان میں شمار کیے گئے، تمام مردوں کی تعداد کے مطابق، ایک ماہ کی عمر سے اوپر، چھ ہزار دو سو تھے۔\n35۔ اور مراری کے خاندانوں کے والد کے گھر کا سردار {تھا} زوریئل، ابیحائل کا بیٹا: {یہ} خیمہ کے شمال کی طرف پھینکیں گے۔\n36۔ اور {زیر} مراری کے بیٹوں کی ذمہ داری اور ذمہ داری خیمہ کے تختے، اس کی سلاخیں، اس کے ستون، اس کے ستون، اس کے ساکٹ، اس کے تمام برتن، اور اس کی خدمت کرنے والی تمام چیزیں ہوں گی، {نیچے...: عبرانی۔ چارج کا دفتر}\n37۔ اور صحن کے گرد ستون، ان کے ساکٹ، پن اور رسے۔\n38۔ لیکن جو لوگ خیمہ گاہ کے سامنے مشرق کی طرف خیمہ زن ہیں، {حتیٰ کہ} جماعت کے خیمے کے سامنے مشرق کی طرف، {موسیٰ} اور ہارون اور اس کے بیٹے ہوں گے، جو بنی اسرائیل کے لیے مقدس مقام کی حفاظت کریں گے؛ اور جو اجنبی قریب آئے گا اسے مار دیا جائے گا۔\n39۔ لاویوں میں سے جو سب گنے گئے تھے، جنہیں موسیٰ اور ہارون نے خداوند کے حکم کے مطابق گنا تھا، ان کے خاندانوں میں ایک ماہ سے اس سے اوپر کے تمام مرد بیس اور دو ہزار تھے۔\n40۔ اور خداوند نے موسیٰ سے فرمایا، بنی اسرائیل کے تمام پہلے بیٹوں کو ایک ماہ کی عمر سے اور اس سے اوپر گنا، اور ان کے ناموں کی تعداد لو۔\n41. اور تو میرے لیے لاویوں کو قبول کرو (میں خداوند ہوں) بجائے اس کے کہ بنی اسرائیل کے تمام پہلوڑے ہوں؛ اور لاویوں کے مویشیوں کی بجائے بنی اسرائیل کے مویشیوں کے تمام فرسٹلنگز کے۔\n42۔ اور موسیٰ نے، جیسا کہ خداوند نے حکم دیا، بنی اسرائیل میں سب سے پہلے والے کو گنوایا۔\n43۔ اور ایک ماہ کی عمر سے اور اس سے زیادہ عمر کے تمام پہلے والے مرد بیس دو ہزار دو سو تین سو تیرہ تھے۔\n44۔ اور خداوند نے موسیٰ سے کہا،\n45۔ لاویوں کو اسرائیل کے تمام پہلے بچے کی جگہ اور لاویوں کے مویشیوں کو ان کے مویشیوں کی جگہ لے لو؛ اور لاوی میرے ہوں گے: میں خداوند ہوں۔\n46۔ اور جن لوگوں کو بنی اسرائیل کے دو سو تئیس تیرہ سب سے بڑے اولاد میں سے نجات ملنی ہے، جو لاویوں سے زیادہ ہیں؛\n47. تم ہر ایک کو پول کے حساب سے پانچ شیکل بھی لو گے، جب تم مقدس مقام کے شیکل لے لو گے: (شیکل {ہے} بیس گرہ :)\n48۔ اور تم وہ رقم جو ان کی طاق تعداد سے چھپائی جانی ہے، ہارون اور اس کے بیٹوں کو دے دینا۔\n49۔ اور موسیٰ نے ان لوگوں کی نجات کے پیسے لے لیے جو لاویوں کے ذریعے نجات پانے والوں سے اوپر تھے:\n50۔ بنی اسرائیل کے پہلے بیٹے میں سے اس نے رقم لی؛ ہزار تین سو تین سو پانچ شیکل، مقدس مقام کے شیکل کے بعد:\n51۔ اور موسیٰ نے ان لوگوں کی رقم ہارون اور اس کے بیٹوں کو دی جو خداوند کے کلام کے مطابق دی، جیسا کہ خداوند نے موسیٰ کو حکم دیا تھا۔","1۔ اور خداوند نے موسیٰ اور ہارون سے کہا،\n2۔ کوہات کے بیٹوں کی رقم لیوی کے بیٹوں میں سے ان کے خاندانوں کے مطابق ان کے باپ دادا کے گھر سے لے لو،\n3۔ تیس سال کی عمر سے لے کر پچاس سال کی عمر تک، وہ سب لوگ جو میزبان میں داخل ہوتے ہیں، جماعت کے خیمہ میں کام کرتے ہیں۔\n4. یہ {یہ} کوہات کے بیٹوں کی عبادت ہوگی جماعت کے خیمے میں، {سب سے مقدس چیزوں کے بارے میں}:\n5۔ اور جب کیمپ آگے بڑھے گا، ہارون اور اس کے بیٹے آئیں گے، اور وہ پردہ اتار کر گواہی کے صندوق کو اس سے ڈھانپیں گے:\n6۔ اور اس پر بیجرز کی کھالوں کا ڈھکن ڈالوں گا، اور اس پر مکمل نیلا کپڑا پھیلاؤں گا، اور اس کے ڈنٹھوں میں رکھوں گا۔\n7۔ اور وہ شیو بریڈ کی میز پر نیلا کپڑا بچھائیں گے، اور اس پر برتن، چمچ، پیالے اور چادر ڈالیں گے تاکہ انہیں ڈھانپ سکیں: اور اس پر مسلسل روٹی رکھی جائے گی: {ڈھانپیں...: یا، اس میں ڈالیں}\n8۔ اور وہ ان پر سرخ رنگ کا کپڑا پھیلائیں گے، اور اسے بیجر کی کھالوں سے ڈھانپیں گے، اور اس کے ڈنڈے میں ڈالیں گے۔\n9۔ اور وہ نیلے رنگ کا کپڑا اٹھائیں گے، اور روشنی کے شمعدان، اس کے چراغوں، چمٹے، اس کے سنف ڈشز، اور ان کے تمام تیل کے برتن ڈھانپیں گے جن سے وہ اس کی خدمت کرتے ہیں:\n10۔ اور وہ اسے اور اس کے تمام برتنوں کو بیجر کی کھالوں کی چادر میں ڈالیں گے، اور اسے ایک بار پر رکھیں گے۔\n11۔ اور سنہری قربان گاہ پر نیلا کپڑا بچھائیں گے، اور اسے بیجر کی کھالوں سے ڈھانپیں گے، اور اس کے ڈنٹھوں پر ڈالیں گے:\n12۔ اور وہ عبادت کے تمام آلات لے کر نیلے کپڑے میں ڈالیں گے، اور انہیں بیجر کی کھالوں سے ڈھانپیں گے، اور انہیں ایک سلاخ پر رکھیں گے:\n13۔ اور وہ قربان گاہ سے راکھ نکالیں گے، اور اس پر جامنی کپڑا پھیلائیں گے:\n14۔ اور وہ اس کے تمام برتن اس پر رکھیں گے جن سے وہ اس کی خدمت کرتے ہیں، حتیٰ کہ بخور کے برتن، گوشت کے کانٹے، بیلچے، اور بیسن، اور تمام برتن جو قربان گاہ کے ہیں؛ اور وہ اس پر بیجرز کی کھالوں کا ڈھکن بچھا دیں گے، اور اس کے ڈنٹھوں پر لگا دیں گے۔ {بیسن: اور، بولز}\n15۔ اور جب ہارون اور اس کے بیٹوں نے مقدس خانے اور مقدس مقام کے تمام برتنوں کو ڈھانپنا بند کر دیا، جیسا کہ کیمپ آگے بڑھنے والا ہے؛ اس کے بعد، کوہاتھ کے بیٹے اسے جنم دیں گے: لیکن وہ کسی مقدس چیز کو نہیں چھوئیں گے، ورنہ وہ مر جائیں گے۔ یہ {چیزیں} جماعت کے خیمہ میں کوہات کے بیٹوں کا بوجھ ہیں۔\n16۔ اور ہارون کاهن کے بیٹے الیعزر کے عہدے کے لیے روشنی کے لیے تیل، میٹھا لوبانی، روزانہ کے گوشت کی قربانی، اور مسح کا تیل، اور تمام خیمے اور اس میں موجود تمام چیزوں کی حفاظت کے لیے، مقدس مقام اور اس کے برتنوں میں۔\n17۔ اور خداوند نے موسیٰ اور ہارون سے کہا،\n18۔ لاویوں میں سے کوہاتی خاندانوں کے قبیلے کو الگ نہ کریں:\n19۔ لیکن ان کے ساتھ ایسا کرو، تاکہ وہ زندہ رہیں اور مریں نہیں، جب وہ مقدس ترین چیزوں کے قریب پہنچیں: ہارون اور اس کے بیٹے اندر جائیں گے، اور سب کو اپنی خدمت اور بوجھ کے لیے مقرر کریں گے:\n20۔ لیکن وہ یہ دیکھنے نہیں جائیں گے کہ مقدس چیزیں کب ڈھانپ دی جائیں، ورنہ وہ مر جائیں گے۔\n21۔ اور خداوند نے موسیٰ سے کہا،\n22۔ گرشون کے بیٹوں کی رقم بھی اپنے باپ اجداد کے گھروں میں، ان کے خاندانوں کے لحاظ سے لے لو؛\n23۔ تیس سال کی عمر سے لے کر پچاس سال تک تم انہیں گنتی کرو؛ وہ سب جو عبادت کے لیے آتے ہیں، جماعت کے خیمے میں کام کرتے ہیں۔ {پرفارم کرنے کے لیے...: عبرانی۔ جنگ لڑنے کے لیے}\n24. یہ {ہے} گرشونیوں کے خاندانوں کی خدمت، خدمت کے لیے، اور بوجھ کے لیے: {بوجھ: یا، سوار}\n25۔ اور وہ خیمے کے پردے، جماعت کے خیمے کی پردے، اس کا پردہ اور اس پر اوپر موجود بیجرز کی کھالوں کی تہہ اور جماعت کے خیمے کے دروازے کے لیے لٹکاؤ اٹھائیں گے،\n26۔ اور صحن کے لٹکاؤں، اور صحن کے دروازے کے دروازے کے لیے لٹکاؤ، جو خیمہ کے پاس ہے، قربان گاہ کے ارد گرد ہے، ان کی رسیاں، ان کی خدمت کے تمام آلات، اور جو کچھ ان کے لیے بنایا گیا ہے، اسی طرح وہ خدمت کریں گے۔\n27۔ ہارون اور اس کے بیٹوں کی تقرری پر گرشونیوں کے تمام بیٹوں کی خدمت ہوگی، ان کے تمام بوجھ اور خدمت میں، اور تم ان پر ان کے تمام بوجھ مقرر کرو گے۔ {تقرری: عبرانی منہ}\n28۔ یہ جماعت کے خیمے میں گرشون کے بیٹوں کے خاندانوں کی خدمت ہے: اور ان کی ذمہ داری ہارون کاهن کے بیٹے ایتھامار کے ہاتھ میں ہوگی۔\n29۔ جہاں تک مراری کے بیٹوں کا تعلق ہے، تو انہیں ان کے خاندانوں کے حساب سے، ان کے باپوں کے گھر کے حساب سے گننا گے؛\n30۔ تیس سال کی عمر سے لے کر پچاس سال تک تم انہیں گننا گے، ہر وہ شخص جو عبادت میں شامل ہو، تاکہ جماعت کے خیمے کا کام انجام دے۔ {سروس: عبرانی۔ جنگ}\n31۔ اور یہ ان کے بوجھ کی ذمہ داری ہے، ان کی جماعت کے خیمہ میں ان کی تمام خدمات کے مطابق؛ خیمہ کے تختے، اس کی سلاخیں، اس کے ستون، اور اس کے ساکٹ،\n32۔ اور دربار کے ستون، ان کے ساکٹ، ان کے پن، ان کی رسیاں، ان کے تمام آلات اور ان کی تمام خدمات کے ساتھ، اور نام کے مطابق تم ان کے بوجھ کی ذمہ داری کے آلات شمار کرو گے۔\n33. یہ مراری کے بیٹوں کے خاندانوں کی خدمت ہے، ان کی تمام خدمات کے مطابق، جماعت کے خیمہ نشین میں، ہارون کے بیٹے ایتھامار کے ہاتھ میں۔\n34۔ اور موسیٰ، ہارون اور جماعت کے سردار نے کوہاتیوں کے بیٹوں کو ان کے خاندانوں کے مطابق اور ان کے باپ و اجداد کے گھر کے مطابق گنا تھا،\n35۔ تیس سال کی عمر سے لے کر پچاس سال تک، جو بھی جماعت کے خیمہ میں کام کے لیے خدمت میں شامل ہوتا ہے:\n36۔ اور جو ان میں سے ان کے خاندانوں کے حساب سے گنے گئے وہ دو ہزار سات سو پچاس تھے۔\n37۔ یہ وہ لوگ تھے جو کوہاہیوں کے خاندانوں میں شمار کیے گئے تھے، جو جماعت کے خیمے میں خدمت کر سکتے تھے، جنہیں موسیٰ اور ہارون نے موسیٰ کے ہاتھ سے خداوند کے حکم کے مطابق گنتے تھے۔\n38۔ اور وہ جو گرشون کے بیٹوں میں شمار کیے گئے، اپنے خاندانوں میں اور ان کے باپ دادا کے گھرانے کے مطابق،\n39۔ تیس سال کی عمر سے لے کر پچاس سال تک، جو بھی جماعت کے خیمہ میں کام کے لیے خدمت میں شامل ہوتا ہے،\n40۔ حتیٰ کہ جو لوگ ان کے خاندانوں میں ان کے باپ کے گھر کے مطابق شمار کیے گئے، وہ بھی دو ہزار چھ سو تیس تھے۔\n41۔ یہ وہ لوگ ہیں جو گرشون کے بیٹوں کے خاندانوں میں شمار کیے گئے، ان سب میں سے جو جماعت کے خیمہ میں خدمت کر سکتے تھے، جنہیں موسیٰ اور ہارون نے خداوند کے حکم کے مطابق گننا تھا۔\n42۔ اور جو مراری کے بیٹوں کے خاندانوں میں شمار کیے گئے، ان کے باپ دادا کے گھرانے کے مطابق،\n43۔ تیس سال کی عمر سے لے کر پچاس سال کی عمر تک، ہر وہ شخص جو عبادت میں شامل ہوتا ہے، جماعت کے خیمے میں کام کے لیے،\n44۔ حتیٰ کہ ان میں سے جو ان کے خاندانوں کے نام پر شمار کیے گئے تھے، وہ بھی تین ہزار دو سو تھے۔\n45۔ یہ وہ ہیں جو مراری کے بیٹوں کے خاندانوں میں شمار کیے گئے، جنہیں موسیٰ اور ہارون نے خداوند کے کلام کے مطابق موسیٰ کے ہاتھ سے گنے۔\n46۔ وہ سب لوگ جو لاویوں میں شمار کیے گئے تھے، جنہیں موسیٰ، ہارون اور اسرائیل کے سردار نے ان کے خاندانوں کے مطابق اور ان کے باپ و اجداد کے گھر کے مطابق شمار کیا تھا،\n47۔ تیس سال کی عمر سے لے کر پچاس سال تک، ہر وہ شخص جو عبادت اور جماعت کے خیمے میں بوجھ کی خدمت کے لیے آتا تھا،\n48۔ یہاں تک کہ جن میں شمار کیا گیا، وہ آٹھ ہزار پانچ سو چولیس تھے۔\n49۔ خداوند کے حکم کے مطابق وہ موسیٰ کے ہاتھ سے گنے گئے، ہر ایک اپنی خدمت کے مطابق اور اس کے بوجھ کے مطابق: یوں وہ اس کی گنتی میں گئے، جیسے خداوند نے موسیٰ کو حکم دیا۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل کو حکم دو کہ وہ کیمپ سے ہر کوڑھی کے مریض، اور ہر اس شخص کو جس کی اولاد ہو، اور جو مردوں کے ہاتھوں ناپاک ہو، نکال دیں:\n3۔ مرد اور عورت دونوں کو نکال دو، بغیر کیمپ کے انہیں رکھو؛ کہ وہ ان کے کیمپوں کو بے حرمتی نہیں کرتے، جن کے بیچ میں میں رہتا ہوں۔\n4۔ اور بنی اسرائیل نے ایسا کیا اور انہیں کیمپ کے بغیر نکال دیا: جیسے خداوند نے موسیٰ سے کہا، ویسے ہی بنی اسرائیل نے بھی کیا۔\n5۔ اور خداوند نے موسیٰ سے کہا،\n6۔ بنی اسرائیل سے بات کرو، جب کوئی مرد یا عورت کوئی گناہ کرے جو لوگ کرتے ہیں، تو وہ شخص خدا کے خلاف گناہ کرے اور وہ شخص مجرم ہو؛\n7۔ پھر وہ اپنے کیے گئے گناہ کا اعتراف کریں گے: اور وہ اپنی غلطی کا اصل رقم سے بدلہ دے گا، اس میں پانچواں حصہ شامل کرے گا، اور جس کے خلاف اس نے زیادتی کی ہے اسے دے گا۔\n8۔ لیکن اگر اس آدمی کا کوئی رشتہ دار نہیں جسے وہ جرم کا بدلہ دے سکے، تو گناہ کا بدلہ خداوند کو دیا جائے، {حتیٰ کہ} پادری کو؛ کفارہ کے مینڈھے کے پاس، جس کے ذریعے اس کے لیے کفارہ بنایا جائے گا۔\n9۔ اور بنی اسرائیل کی تمام مقدس چیزوں کی ہر پیشکش، جو وہ پادری کو لاتے ہیں، اس کی ہوگی۔ {نذران: یا، نذرانہ اٹھاؤ}\n10۔ اور ہر انسان کی مقدس چیزیں اس کی ہوں گی: جو کچھ بھی کوئی پادری کو دے گا، وہ اس کی ہوگی۔\n11۔ اور خداوند نے موسیٰ سے کہا،\n12۔ بنی اسرائیل سے بات کرو اور انہیں کہو، اگر کسی مرد کی بیوی ہٹ جائے اور اس کے خلاف گناہ کرے،\n13۔ اور ایک مرد اس کے ساتھ جسمانی تعلق قائم کرے، اور اسے اس کے شوہر کی نظروں سے چھپایا جائے، اور اسے قریب رکھا جائے، اور اس کے خلاف کوئی گواہ نہ ہو، نہ ہی وہ اس طریقے سے لی جائے؛\n14۔ اور حسد کی روح اس پر آئے، اور وہ اپنی بیوی سے حسد کرے اور وہ ناپاک ہو جائے، یا اگر حسد کی روح اس پر آ جائے اور وہ اپنی بیوی سے حسد کرے اور وہ ناپاک نہ ہو:\n15۔ پھر آدمی اپنی بیوی کو پادری کے پاس لے جائے گا، اور اس کے لیے اس کی نذرانہ پیش کرے گا، جو جو کے آٹے کا دسواں حصہ ہے؛ وہ اس پر تیل نہیں ڈالے گا، نہ لوبان رکھے گا؛ کیونکہ یہ حسد کی پیشکش ہے، یادگار کی پیشکش، جو گناہوں کو یاد دلاتی ہے۔\n16۔ اور پادری اسے قریب لے آئے گا، اور اسے خداوند کے سامنے رکھے گا:\n17۔ اور پادری مٹی کے برتن میں مقدس پانی پئے گا؛ اور وہ خاک جو خیمہ کے فرش میں ہے، پادری لے کر پانی میں ڈالے گا:\n18۔ اور پادری عورت کو خداوند کے سامنے رکھے گا، عورت کا سر کھولے گا، اور اس کے ہاتھوں میں یادگاری نذرانہ رکھے گا، جو حسد کی قربانی ہے: اور پادری کے ہاتھ میں وہ کڑوا پانی ہوگا جو لعنت کا باعث بنتا ہے:\n19۔ اور پادری اسے قسم دے کر عورت سے کہے گا، اگر تم نے تمہارے ساتھ کوئی مرد نہیں سوتا، اور اگر تم اپنے شوہر کی جگہ کسی اور کے ساتھ گندگی میں نہیں گئے، تو تم اس کڑوی پانی سے آزاد ہو جاؤ جو لعنت کا باعث بنتا ہے: {کسی اور کے ساتھ...: یا اپنے شوہر کے اختیار میں ہو:  عبرانی۔ اپنے شوہر کے تحت}\n20۔ لیکن اگر تم اپنے شوہر کی جگہ کسی اور کے پاس چلی گئی ہو، اور اگر تم ناپاک ہو جاؤ، اور تمہارے شوہر کے ساتھ کوئی شخص سویا ہو:\n21۔ پھر پادری عورت کو لعنت کی قسم دے گا، اور پادری عورت سے کہے گا، خداوند تمہیں لعنت اور تمہارے لوگوں میں قسم دے جب خداوند تمہاری ران کو سڑ دے اور تمہارا پیٹ پھول دے؛ {روٹ: عبوری۔ خزاں}\n22۔ اور یہ پانی جو لعنت کا باعث بناتا ہے، تمہارے پیٹ کو پھول دے گا، اور تمہاری ران کو سڑ جائے گا: اور عورت کہے گی، آمین، آمین۔\n23۔ اور پادری یہ لعنتیں ایک کتاب میں لکھے گا، اور انہیں کڑوی پانی سے مٹا دے گا:\n24۔ اور وہ عورت کو وہ کڑوا پانی پلائے گا جو لعنت کا باعث بنتا ہے: اور وہ پانی جو لعنت کا باعث بنتا ہے، اس کے اندر داخل ہو کر کڑوا ہو جائے گا۔\n25۔ پھر پادری عورت کے ہاتھ سے حسد کی قربانی نکالے گا، اور نذرانہ خداوند کے سامنے لہرائے گا، اور اسے قربان گاہ پر پیش کرے گا:\n26۔ اور پادری نذرانہ کا ایک مٹھی بھر لے گا، {حتیٰ کہ} اس کی یادگار بھی، اور اسے قربان گاہ پر جلائے گا، اور پھر عورت کو پانی پلانے کو تیار کرے گا۔\n27۔ اور جب اس نے اسے پانی پلایا تو یہ ہو جائے گا، اگر وہ ناپاک ہو جائے اور اپنے شوہر کے خلاف گناہ کرے، تو وہ پانی جو لعنت کا سبب بنتا ہے، اس کے اندر داخل ہو جائے گا، اور کڑوا ہو جائے گا، اس کا پیٹ پھول جائے گا، اور اس کی ران سڑ جائے گی؛ اور عورت اپنے لوگوں میں لعنت بن جائے گی۔\n28۔ اور اگر عورت ناپاک نہ ہو، بلکہ پاک ہو؛ پھر وہ آزاد ہو جائے گی، اور اولاد پیدا کرے گی۔\n29۔ یہ حسد کا قانون ہے، جب بیوی اپنے شوہر کی جگہ کسی اور کے پاس چلی جاتی ہے اور اسے ناپاک کیا جاتا ہے؛\n30۔ یا جب حسد کی روح اس پر آئے، اور وہ اپنی بیوی پر حسد کرے گا، اور عورت کو خداوند کے سامنے رکھے گا، اور پادری اس پر یہ تمام قانون نافذ کرے گا۔\n31۔ پھر مرد گناہ سے بے گناہ ہوگا، اور یہ عورت اپنی گناہ برداشت کرے گی۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2. بنی اسرائیل سے بات کرو، اور ان سے کہو، جب کوئی مرد یا عورت الگ ہو کر خود کو ناصری کی قسم کھائیں، خداوند سے الگ ہو جائیں: {جدا ہو جائیں...: یا خود کو ناصری بنا لیں}\n3۔ وہ شراب اور تیز مشروب سے الگ ہو جائے گا، اور شراب کا سرکہ یا تیز مشروب کا سرکہ نہیں پیے گا، نہ انگور کی کوئی شراب پئے گا، نہ نم انگور کھائے گا، نہ خشک شدہ انگور۔\n4۔ اپنی جدائی کے تمام دنوں میں وہ انگور کے درخت سے بنی کچھ بھی نہیں کھائے گا، چاہے وہ دانے ہوں یا چھلکے تک۔ {جدائی: یا، نذری شپ} {vine...: عبرانی۔ شراب کی بیل}\n5۔ جدائی کے عہد کے تمام دنوں میں اس کے سر پر کوئی ریزر نہیں آئے گا: جب تک وہ دن پورے نہ ہوں جن میں وہ خود کو خداوند سے جدا کرتا ہے، وہ مقدس رہے گا، {اور} اپنے سر کے بالوں کو بڑھنے دے گا۔\n6. جتنے دن وہ خود کو خداوند کے پاس جدا کرے گا، وہ مردہ جسم پر نہیں آئے گا۔\n7. وہ اپنے والد، اپنی ماں، بھائی یا بہن کے لیے خود کو ناپاک نہیں بنائے گا جب وہ مر جائیں: کیونکہ اس کے خدا کی تقدیس اس کے سر پر ہے۔ {تقدیس: عبرانی۔ علیحدگی}\n8۔ اپنی جدائی کے تمام دن وہ خداوند کے لیے مقدس ہے۔\n9۔ اور اگر کوئی شخص اچانک اس کے ہاتھوں مر جائے اور اس نے اپنی تقدیس کے سر کو آلودہ کر دیا ہو؛ پھر وہ اپنی صفائی کے دن اپنا سر منڈوا دے گا، ساتویں دن اسے منڈوا دے گا۔\n10۔ اور آٹھویں دن وہ دو کچھوے، یا دو نوجوان کبوتروں کو پادری کے پاس لے جائے گا، جو جماعت کے خیمہ کے دروازے پر ہے:\n11۔ اور پادری ایک کو گناہ کی قربانی کے طور پر پیش کرے گا، اور دوسرا کو جلنے کی قربانی کے طور پر، اور اس کے لیے کفارہ کرے گا، جو اس نے مردوں کے ساتھ گناہ کیا، اور اسی دن اس کا سر مقدس کرے گا۔\n12۔ اور وہ اپنی جدائی کے دن خداوند کے لیے وقف کرے گا، اور پہلے سال کا میمنہ جرم کی قربانی کے لیے لے کر آئے گا: لیکن پہلے کے دن ضائع ہو جائیں گے، کیونکہ اس کی جدائی ناپاک ہو گئی۔ {گم ہو جاؤ: عبوری۔ خزاں}\n13۔ اور یہ ناصری کا قانون ہے، جب اس کی جدائی کے دن مکمل ہوں گے: اسے جماعت کے خیمہ کے دروازے پر لایا جائے گا:\n14۔ اور وہ اپنی قربانی خداوند کے سامنے پیش کرے گا، ایک پہلے سال کا بلا داغ برہ، اور پہلے سال کا ایک بھیڑ بغیر داغ گناہ کی قربانی کے لیے، اور ایک مینڈھا بغیر داغ صلح کی نذرانے کے لیے،\n15۔ اور بغیر خمیر کی روٹی کی ایک ٹوکری، تیل میں ملا ہوا عمدہ آٹے کے ککے، تیل سے مسح شدہ بغیر خمیر کی روٹی کے ویفرز، اور ان کے گوشت کی قربانی، اور ان کے مشروبات کی قربانی۔\n16۔ اور پادری انہیں خداوند کے سامنے لے آئے گا، اور اپنا گناہ کی قربانی اور اپنی جلتی قربانی پیش کرے گا:\n17۔ اور وہ مینڈھا {بطور} خدا کو امن کی قربانی کے طور پر پیش کرے گا، بغیر خمیر کی ٹوکری کے ساتھ: پادری اپنی گوشت کی قربانی اور اپنی شراب کی قربانی بھی پیش کرے گا۔\n18۔ اور ناصری اپنی علیحدگی کا سر جماعت کے خیمہ کے دروازے پر منڈوائے گا، اور اپنے علیحدگی کے سر کے بال لے کر اس آگ میں رکھے گا جو امن کی قربانیوں کے تحت ہے۔\n19۔ اور پادری مینڈھے کا بھیگا ہوا کندھا، ٹوکری سے ایک بغیر خمیر کے کیک اور ایک خمیر کے بغیر ویفر لے کر ناصری کے ہاتھ میں رکھے گا، جب اس کے بال منڈوا دیے جائیں گے:\n20۔ اور پادری انہیں خداوند کے سامنے لہرانے کی قربانی کے طور پر لہرائے گا: یہ پادری کے لیے مقدس ہے، لہراتا ہوا سینہ اور کندھے کے ساتھ: اور اس کے بعد ناصری شراب پی سکتے ہیں۔\n21. یہ ناصری کا قانون ہے جس نے عہد کیا ہے، اور خدا کو اپنی جدائی کے لیے پیش کرنے کا وعدہ کیا ہے، اس کے علاوہ جو اس کا ہاتھ ملے گا: اس قسم کے مطابق جو اس نے نذر کیا ہے، اسے اپنی جدائی کے قانون کے بعد کرنا ہوگا۔\n22۔ اور خداوند نے موسیٰ سے کہا،\n23۔ ہارون اور اس کے بیٹوں سے بات کرو، کہو، اسی طرح تم بنی اسرائیل کو برکت دو گے، ان سے کہو،\n24۔ خداوند تمہیں برکت دے، اور اپنی حفاظت کرے:\n25. خداوند اپنا چہرہ تم پر روشن کرے، اور تم پر مہربان ہو:\n26. خداوند اپنا چہرہ تم پر اٹھا دے، اور تمہیں امن دے۔\n27۔ اور وہ میرا نام بنی اسرائیل پر رکھیں گے؛ اور میں انہیں برکت دوں گا۔","1۔ اور یہ اس دن ہوا جب موسیٰ نے خیمہ مکمل طور پر قائم کیا، اسے مسح کیا، اور اس کے تمام آلات، قربان گاہ اور اس کے تمام برتن، اور انہیں مسح کیا اور مقدس کیا؛\n2۔ کہ اسرائیل کے شہزادے، اپنے باپ اجداد کے خاندان کے سردار، جو قبائل کے شہزادے تھے، اور جن کے نمبر والے تھے، نے پیشکش کی: {اور تھے: عبرانی۔ کون کھڑا تھا}\n3۔ اور انہوں نے خداوند کے سامنے اپنی قربانی پیش کی، چھ ڈھکی ہوئی گاڑیاں اور بارہ بیل؛ دو شہزادوں کے لیے ایک گاڑی، اور ہر ایک کے لیے ایک بیل: اور وہ انہیں خیمہ گاہ کے سامنے لے آئے۔\n4۔ اور خداوند نے موسیٰ سے کہا،\n5. ان میں سے لے لو، تاکہ وہ جماعت کے خیمے کی خدمت کر سکیں؛ اور تم انہیں لاویوں کو، ہر آدمی کو اس کی خدمت کے مطابق دے دینا۔\n6۔ اور موسیٰ نے گاڑیاں اور بیل لے کر لاویوں کو دے دیے۔\n7۔ دو گاڑیاں اور چار بیل اس نے گرشون کے بیٹوں کو ان کی خدمت کے مطابق دیے:\n8۔ اور چار گاڑیاں اور آٹھ بیل اس نے مراری کے بیٹوں کو ان کی خدمت کے مطابق دیے، جو ہارون کاهن کے بیٹے ایتھامار کے ہاتھوں تھے۔\n9۔ لیکن کوہات کے بیٹوں کو اس نے کچھ نہیں دیا: کیونکہ ان کے مقدس مقام کی خدمت کو اپنے کندھوں پر اٹھانا تھا۔\n10۔ اور شہزادوں نے اس دن قربان گاہ کو وقف کرنے کی پیشکش کی جس دن اسے مسح کیا گیا، حتیٰ کہ شہزادوں نے بھی قربان گاہ کے سامنے اپنی قربانی دی۔\n11۔ اور خداوند نے موسیٰ سے کہا، وہ اپنی قربانی پیش کریں گے، ہر شہزادہ اپنے دن قربان گاہ کی وقف کے لیے۔\n12۔ اور جس نے پہلے دن اپنی قربانی پیش کی وہ نہشون، امیناداب کا بیٹا، قبیلہ یہوداہ سے تھا:\n13۔ اور اس کی قربانی ایک چاندی کا چارجر تھی، جس کا وزن ایک سو تیس شیکل تھا، ایک چاندی کا پیالہ ستر شیکل کا، مقدس مقام کے شیکل کے بعد؛ دونوں {تھے} عمدہ آٹے سے بھرے ہوئے، تیل کے ساتھ گوشت کی پیشکش کے لیے:\n14. دس شیکل سونے کا ایک چمچ، دھوبتی سے بھرا ہوا:\n15۔ ایک نوجوان بیل، ایک مینڈھا، ایک پہلا سال کا بھیڑا، جلانے کی قربانی کے لیے:\n16۔ بکریوں کا ایک بچہ گناہ کی قربانی کے بدلے:\n17۔ اور صلح کی قربانی کے بدلے، دو بیل، پانچ مینڈے، پانچ بکری، پانچ بکری، پانچ برہ پہلے سال کے: یہ {تھا} ناہشون ابن امینادب کی نذرانہ تھی۔\n18۔ دوسرے دن، زوار کے بیٹے نیتھانیل، یساکر کے شہزادے، نے پیشکش کی:\n19۔ اس نے اپنی پیشکش کے بدلے ایک چاندی کا چارج پیش کیا، جس کا وزن ایک سو تیس شیکل تھا، ایک چاندی کا پیالہ ستر شیکل کا، مقدس مقام کے شیکل کے بعد؛ دونوں میں عمدہ آٹا اور تیل ملا کر گوشت کی پیشکش میں بھرے ہوئے تھے:\n20۔ دس شیکلوں کا ایک چمچ سونا، دھوئیں سے بھرا ہوا:\n21۔ ایک نوجوان بیل، ایک مینڈھا، ایک پہلا سال کا بکر، جلانے کی قربانی کے لیے:\n22۔ گناہ کی قربانی کے بدلے بکریوں کا ایک بچہ:\n23۔ اور صلح کی قربانی کے بدلے، دو بیل، پانچ مینڈے، پانچ بکریاں، پانچ بکریاں اور پہلے سال کے پانچ بھیڑے: یہ زوار کے بیٹے نیتھنیئل کی قربانی تھی۔\n24۔ تیسرے دن، ہیلون کے بیٹے ایلیاب، زبولون کے بچوں کے شہزادے، نے پیشکش کی:\n25۔ اس کی قربانی ایک چاندی کا چارجر تھی، جس کا وزن ایک سو تیس شیکل تھا، ایک چاندی کا پیالہ ستر شیکل کا، مقدس مقام کے شیکل کے بعد؛ دونوں میں عمدہ آٹا اور تیل ملا کر گوشت کی پیشکش میں بھرے ہوئے تھے:\n26۔ دس شیکلوں کا ایک سنہری چمچ، دھوپ سے بھرا ہوا:\n27۔ ایک نوجوان بیل، ایک مینڈھا، ایک پہلا سال کا بھیڑا، جلانے کی قربانی کے لیے:\n28. گناہ کی قربانی کے بدلے بکریوں کا ایک بچہ:\n29۔ اور صلح کی قربانی کے بدلے، دو بیل، پانچ مینڈے، پانچ بکریاں، پہلے سال کے پانچ بکرے: یہ ایلیاب ہیلون کے بیٹے کی قربانی تھی۔\n30۔ چوتھے دن الیزور، شیدیور کا بیٹا، روبن کے بچوں کا شہزادہ، {پیشکش کی}:\n31۔ اس کی قربانی ایک چاندی کا چارجر تھا جس کا وزن ایک سو تیس شیکل تھا، ایک چاندی کا پیالہ ستر شیکل کا، مقدس مقام کے شیکل کے بعد؛ دونوں میں عمدہ آٹا اور تیل ملا کر گوشت کی پیشکش میں بھرے ہوئے تھے:\n32۔ ایک سنہری چمچ دس {شیکل}، دھوبتی سے بھرا ہوا:\n33۔ ایک نوجوان بیل، ایک مینڈھا، ایک پہلا سال کا بھیڑا، جلانے کی قربانی کے لیے:\n34۔ گناہ کی قربانی کے بدلے بکریوں کا ایک بچہ:\n35۔ اور صلح کی قربانی کے بدلے، دو بیل، پانچ مینڈے، پانچ بکریاں، پہلے سال کے پانچ بکرے: یہ الیزور بیٹے شیدور کی قربانی تھی۔\n36۔ پانچویں دن شلومیئل، زریشادائی کا بیٹا، شمعون کے بچوں کا شہزادہ، {پیش کیا}:\n37۔ اس کی قربانی ایک چاندی کا چارجر تھی، جس کا وزن ایک سو تیس شیکل تھا، ایک چاندی کا پیالہ ستر شیکل کا، مقدس مقام کے شیکل کے بعد؛ دونوں میں عمدہ آٹا اور تیل ملا کر گوشت کی پیشکش میں بھرے ہوئے تھے:\n38۔ ایک سنہری چمچ دس {شیکل}، دھوئیں سے بھرا ہوا:\n39۔ ایک نوجوان بیل، ایک مینڈھا، ایک پہلا سال کا بھیڑا، جلانے کی قربانی کے لیے:\n40۔ بکریوں کا ایک بچہ گناہ کی قربانی کے بدلے:\n41۔ اور صلح کی قربانی کے بدلے، دو بیل، پانچ مینڈے، پانچ بکری، پانچ بکری، پہلے سال کے پانچ بکرے: یہ [تھا} شیلومیئل، زریشادائی کے بیٹے کی نذرانہ تھی۔\n42. چھٹے دن، الیاصاف، جو دیوئل کا بیٹا تھا، اور گاد کے بچوں کا شہزادہ تھا، {پیش کیا}:\n43۔ اس کی قربانی ایک چاندی کا چارجر تھا جس کا وزن ایک سو تیس شیکل تھا، ایک چاندی کا پیالہ ستر شیکل کا، مقدس مقام کے شیکل کے بعد؛ دونوں میں عمدہ آٹا اور تیل ملا کر گوشت کی پیشکش میں بھرے ہوئے تھے:\n44۔ دس شیکلوں کا ایک سنہری چمچ، دھوئیں سے بھرا ہوا:\n45۔ ایک نوجوان بیل، ایک مینڈھا، ایک پہلا سال کا ایک بکر، جلانے کی قربانی کے لیے:\n46۔ گناہ کی قربانی کے بدلے بکریوں کا ایک بچہ:\n47۔ اور صلح کی قربانی کے بدلے، دو بیل، پانچ مینڈے، پانچ بکری، پانچ بکری، پہلے سال کے پانچ برہ: یہ الیاصاف بیٹے دیوئل کی قربانی تھی۔\n48۔ ساتویں دن، الیشاما، امیہود کا بیٹا، افرائیم کے بچوں کا شہزادہ، {پیش کیا}:\n49۔ اس کی قربانی ایک چاندی کا چارجر تھی، جس کا وزن ایک سو تیس شیکل تھا، ایک چاندی کا پیالہ ستر شیکل کا، مقدس مقام کے شیکل کے بعد؛ دونوں میں عمدہ آٹا اور تیل ملا کر گوشت کی پیشکش میں بھرے ہوئے تھے:\n50۔ ایک سنہری چمچ دس {شیکل}، دھوبتی سے بھرا ہوا:\n51۔ ایک نوجوان بیل، ایک مینڈھا، ایک پہلا سال کا بھیڑا، جلانے کی قربانی کے لیے:\n52۔ ایک بکریوں کا بچہ گناہ کی قربانی کے بدلے:\n53۔ اور صلح کی قربانی کے بدلے، دو بیل، پانچ مینڈے، پانچ بکری، پانچ بکری، پہلے سال کے پانچ بکری: یہ الیشامہ ابن امیہود کی قربانی تھی۔\n54۔ آٹھویں دن گمالیئل، پیداہزور کے بیٹے، منسی کے بچوں کا شہزادہ {پیش کیا}:\n55۔ اس کی قربانی ایک چاندی کا چارجر تھا جس کا وزن ایک سو تیس شیکل تھا، ایک چاندی کا پیالہ ستر شیکل کا، مقدس مقام کے شیکل کے بعد؛ دونوں میں عمدہ آٹا اور تیل ملا کر گوشت کی پیشکش میں بھرے ہوئے تھے:\n56۔ ایک سنہری چمچ دس {شیکل}، دھوبتی سے بھرا ہوا:\n57۔ ایک نوجوان بیل، ایک مینڈھا، ایک برہ پہلے سال کا بھیڑا، جلانے کی قربانی کے لیے:\n58۔ گناہ کی قربانی کے بدلے بکریوں کا ایک بچہ:\n59. اور صلح کی قربانی کے بدلے، دو بیل، پانچ مینڈے، پانچ بکری، پانچ بکری، پہلے سال کے پانچ بھیڑے: یہ گمالیئل بیٹے پیڈاہزور کی قربانی تھی۔\n60۔ نویں دن ابیدان، جدعونی کا بیٹا، جو بنیامین کے بچوں کا شہزادہ تھا، {پیش کیا}:\n61. اس کی قربانی {تھی} ایک چاندی کا چارجر، جس کا وزن {تھا} ایک سو تیس شیکل}، ایک چاندی کا پیالہ ستر شیکل کا، مقدس مقام کے شیکل کے بعد؛ دونوں میں عمدہ آٹا اور تیل ملا کر گوشت کی پیشکش میں بھرے ہوئے تھے:\n62. ایک سنہری چمچ دس {شیکل}، دھوئیں سے بھرا ہوا:\n63۔ ایک نوجوان بیل، ایک مینڈھا، ایک برہ پہلے سال کا، جلانے کی قربانی کے لیے:\n64۔ گناہ کی قربانی کے بدلے بکریوں کا ایک بچہ:\n65۔ اور صلح کی قربانی کے بدلے، دو بیل، پانچ مینڈے، پانچ بکریاں، پہلے سال کے پانچ برہے: یہ عبیدان بیٹے گدعونی کی قربانی تھی۔\n66۔ دسویں دن احیزر امشادائی کے بیٹے، دان کے بچوں کے شہزادے نے {پیش کیا}:\n67۔ اس کی قربانی ایک چاندی کا چارجر تھی، جس کا وزن {ایک سو تیس شیکل} تھا، ایک چاندی کا پیالہ ستر شیکل کا، مقدس مقام کے شیکل کے بعد؛ دونوں میں عمدہ آٹا اور تیل ملا کر گوشت کی پیشکش میں بھرے ہوئے تھے:\n68۔ ایک سنہری چمچ دس {شیکل}، دھوئیں سے بھرا ہوا:\n69۔ ایک نوجوان بیل، ایک مینڈھا، ایک پہلا سال کا بھیڑا، جلانے کی قربانی کے لیے:\n70۔ گناہ کی قربانی کے بدلے بکریوں کا ایک بچہ:\n71۔ اور صلح کی قربانی کے بدلے، دو بیل، پانچ مینڈے، پانچ بکریاں، پہلے سال کے پانچ بکرے: یہ احیزر بیٹے امیشادائی کی قربانی تھی۔\n72۔ گیارہویں دن پاگیئل، اوکران کا بیٹا، آشر کے بچوں کا شہزادہ، {پیش کیا}:\n73۔ اس کی قربانی ایک چاندی کا چارجر تھی، جس کا وزن ایک سو تیس شیکل تھا، ایک چاندی کا پیالہ ستر شیکل کا، مقدس مقام کے شیکل کے بعد؛ دونوں میں عمدہ آٹا اور تیل ملا کر گوشت کی پیشکش میں بھرے ہوئے تھے:\n74۔ دس شیکلوں کا ایک سنہری چمچ، دھوبتی سے بھرا ہوا:\n75۔ ایک نوجوان بیل، ایک مینڈھا، ایک پہلا سال کا بھیڑا، جلانے کی قربانی کے لیے:\n76۔ گناہ کی قربانی کے بدلے بکریوں کا ایک بچہ:\n77۔ اور صلح کی قربانی کے بدلے، دو بیل، پانچ مینڈے، پانچ بکریاں، پانچ بکریاں، پہلے سال کے پانچ بھیڑے: یہ اوکران کے بیٹے پاگیئل کی قربانی تھی۔\n78۔ بارہویں دن احیرا، اینان کا بیٹا، نفتالی کے بچوں کا شہزادہ، {پیش کیا گیا}:\n79۔ اس کی قربانی ایک چاندی کا چارجر تھی، جس کا وزن ایک سو تیس شیکل تھا، ایک چاندی کا پیالہ ستر شیکل کا، مقدس مقام کے شیکل کے بعد؛ دونوں میں عمدہ آٹا اور تیل ملا کر گوشت کی پیشکش میں بھرے ہوئے تھے:\n80۔ ایک سنہری چمچ دس {شیکل}، دھوئیں سے بھرا ہوا:\n81۔ ایک نوجوان بیل، ایک مینڈھا، ایک پہلا سال کا میمنہ، جلانے کی قربانی کے لیے:\n82۔ گناہ کی قربانی کے بدلے بکریوں کا ایک بچہ:\n83۔ اور صلح کی قربانی کے بدلے، دو بیل، پانچ مینڈے، پانچ بکریاں، پانچ بکریاں، پہلے سال کے پانچ بھیڑے: یہ احیرا کے بیٹے عنان کی قربانی تھی۔\n84۔ یہ قربان گاہ کی وقف تھی، اس دن جب اسے مسح کیا گیا تھا، اسرائیل کے شہزادوں نے: بارہ چاندی کے چارجر، بارہ چاندی کے پیالی، بارہ چمچ سونا:\n85۔ ہر چاندی کا چارج {وزن} ایک سو تیس شیکل، ہر پیالہ ستر: تمام چاندی کے برتن {وزن} دو ہزار چار سو {شیکل}، مقدس مقام کے شیکل کے بعد:\n86۔ سنہری چمچ {تھے} بارہ، دھوئیں سے بھرے، {وزن} ہر ایک دس {شیکل}، مقدس مقام کے شیکل کے بعد: چمچوں کا سارا سونا {تھا} ایک سو بیس {شیکل}۔\n87۔ جلانے کی قربانی کے لیے تمام بیل بارہ بیل، مینڈھے بارہ، پہلے سال کے برہ بارہ، گوشت کی قربانی کے ساتھ، اور بکریوں کے بچے گناہ کی قربانی کے لیے بارہ۔\n88۔ اور صلح کی قربانیوں کی قربانی کے لیے تمام بیل بیس اور چار بیل، مینڈھے ساٹھ، بکریوں کے ساٹھ، اور پہلے سال کے بھیڑ ساٹھ۔ یہ قربان گاہ کی وقف تھی، اس کے بعد اسے مسح کیا گیا۔\n89۔ اور جب موسیٰ اس سے بات کرنے کے لیے جماعت کے خیمے میں گیا، تو اس نے اس رحمت کی نشست سے بات کرنے والی آواز سنی جو گواہی کے صندوق پر دو کروبیوں کے درمیان سے اس سے بات کر رہا تھا: اور اس نے اس سے بات کی۔ {اس کے ساتھ: یعنی، خدا کے ساتھ}","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ ہارون سے بات کرو، اور اسے کہو، جب تم چراغ جلاؤ گے، تو سات چراغ شمعدان کے ساتھ روشنی ڈالیں گے۔\n3۔ اور ہارون نے ایسا کیا؛ اس نے اس کے چراغ موم بتی کے ساتھ روشن کیے، جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n4۔ اور یہ شمعدان کا کام سونے کا تھا، اس کے دھل تک، اس کے پھولوں تک، اور یہ موسیٰ کے نقش و نگار کے مطابق تھا، تو اس نے شمعدان بنایا۔\n5۔ اور خداوند نے موسیٰ سے کہا،\n6۔ لاویوں کو بنی اسرائیل میں سے لے کر انہیں پاک کرو۔\n7۔ اور تم ان کے ساتھ ایسا ہی کرو گے، تاکہ انہیں صاف کیا جا سکے: ان پر پاکیزگی کا پانی چھڑکاؤ، اور ان کا سارا گوشت منڈوا دو، اور اپنے کپڑے دھو لیں، اور یوں خود کو صاف کریں۔ {انہیں شیو کرنے دو...: عبرانی۔ انہیں ریزر کو گزرنے دیں، وغیرہ}\n8۔ پھر وہ ایک نوجوان بیل کو اس کے گوشت کی قربانی کے ساتھ لے جائیں، {حتیٰ کہ} عمدہ آٹا تیل کے ساتھ ملا کر، اور ایک اور نوجوان بیل کو گناہ کی قربانی کے طور پر لے لو۔\n9۔ اور تم لاویوں کو جماعت کے خیمہ کے سامنے لاؤ گے: اور تم بنی اسرائیل کی پوری جماعت کو اکٹھا کرو گے:\n10۔ اور تو لاویوں کو خداوند کے سامنے لے آؤ، اور بنی اسرائیل لاویوں پر ہاتھ رکھیں گے:\n11۔ اور ہارون لاویوں کو خداوند کے سامنے پیش کرے گا {لیے} بنی اسرائیل کی قربانی کے لیے، تاکہ وہ خداوند کی خدمت انجام دیں۔ {آفر: عبرانی ہاتھ ہلاتے ہوئے} {پیشکش: عبرانی۔ ہاتھ ہلانے کی پیشکش} {وہ...: عبرانی۔ وہ عملدرآمد کے لیے بھی ہو سکتے ہیں، وغیرہ}\n12۔ اور لاوی بیلوں کے سر پر ہاتھ رکھیں گے، اور تم ایک کو گناہ کی قربانی کے طور پر، اور دوسرا {جلنے کی قربانی} کے طور پر، خداوند کے سامنے پیش کرو گے تاکہ لاویوں کے لیے کفارہ ہو۔\n13۔ اور تم لاویوں کو ہارون اور اس کے بیٹوں کے سامنے رکھو گے، اور انہیں خداوند کے لیے قربانی کے طور پر پیش کرو گے۔\n14۔ یوں تم لاویوں کو بنی اسرائیل سے جدا کرو گے: اور لاوی میرے ہوں گے۔\n15۔ اس کے بعد لاوی جماعت کے خیمے کی عبادت کے لیے جائیں گے: اور تم انہیں پاک کرو گے اور نذرانہ پیش کرو گے۔\n16۔ کیونکہ وہ مجھے مکمل طور پر بنی اسرائیل میں سے عطا کیے گئے ہیں؛ ایسی اولاد کے بجائے جو ہر رحم کو کھولے، {حتیٰ کہ} اسرائیل کی تمام اولاد کے پہلے بچے کے بجائے، میں نے انہیں اپنے پاس لے لیا ہے۔\n17۔ کیونکہ بنی اسرائیل کے تمام پہلے بچے میرے ہیں، انسان اور جانور دونوں: جس دن میں نے مصر کی سرزمین کے ہر پہلے بچے کو مارا تو میں نے انہیں اپنے لیے پاک کیا۔\n18۔ اور میں نے لاویوں کو بنی اسرائیل کے تمام پہلے بچوں کے لیے قبول کیا ہے۔\n19۔ اور میں نے لاویوں کو (جیسا کہ} ہارون اور اس کے بیٹوں کو بنی اسرائیل میں سے تحفہ دیا ہے، تاکہ وہ جماعت کے خیمے میں بنی اسرائیل کی خدمت کریں، اور بنی اسرائیل کے لیے کفارہ دیں: تاکہ بنی اسرائیل میں کوئی وبا نہ ہو،  جب بنی اسرائیل مقدس مقام کے قریب پہنچیں گے۔ {ایک تحفہ: عبرانی۔ دیا گیا}\n20۔ اور موسیٰ، ہارون اور بنی اسرائیل کی تمام جماعت نے لاویوں کے ساتھ وہ سب کیا جو خداوند نے موسیٰ کو لاویوں کے بارے میں حکم دیا تھا، ویسے ہی بنی اسرائیل نے بھی ان کے ساتھ کیا۔\n21۔ اور لاویوں کو پاک کیا گیا، اور انہوں نے اپنے کپڑے دھوئے؛ اور ہارون نے انہیں خداوند کے سامنے پیش کیا؛ اور ہارون نے ان کے لیے کفارہ بنایا تاکہ انہیں پاک کیا جا سکے۔\n22۔ اور اس کے بعد لاوی جماعت کے خیمہ میں ہارون اور اس کے بیٹوں کے سامنے اپنی عبادت کے لیے گئے: جیسے خداوند نے موسیٰ کو لاویوں کے بارے میں حکم دیا تھا، ویسے ہی انہوں نے ان کے ساتھ بھی حکم دیا۔\n23۔ اور خداوند نے موسیٰ سے کہا،\n24. یہ {ہے} جو {لاویوں کا ہے}: پچیس سال کی عمر سے لے کر اس سے اوپر کے لوگ جماعت کے خیمے کی عبادت کے لیے جائیں گے: {تک...: عبرانی۔ جنگ، جنگ، وغیرہ}\n25۔ اور پچاس سال کی عمر سے وہ خدمت کا انتظار کرنا بند کر دیں گے، اور مزید خدمت نہیں کریں گے: {رک...: عبرانی سروس کی جنگ سے واپسی}\n26۔ لیکن وہ اپنے بھائیوں کے ساتھ جماعت کے خیمہ میں خدمت کریں گے، تاکہ ذمہ داری پوری کی جا سکے، اور کوئی خدمت نہیں کریں گے۔ ایسا ہی کرو گے جب لاویوں نے ان کے ذمہ دار کو چھوا۔","1۔ اور خداوند نے موسیٰ سے سینا کے بیابان میں، دوسرے سال کے پہلے مہینے میں، جب وہ مصر کی سرزمین سے نکلے تھے، کہا،\n2۔ بنی اسرائیل بھی فسح کو اس کے مقررہ موسم پر منائیں۔\n3۔ اس مہینے کے چودہویں دن، شام کو، تم اسے اس کے مقررہ وقت میں رکھو گے: اس کے تمام رسومات اور تمام رسومات کے مطابق، تم اسے پورا کرو گے۔ {جفت پر: عبدی۔ دونوں شاموں کے درمیان}\n4۔ اور موسیٰ نے بنی اسرائیل سے کہا کہ وہ فسح منائیں۔\n5۔ اور انہوں نے پہلے مہینے کی چودہویں تاریخ کو سینائی کے ویرانے میں ہی فسح منایا: جیسا کہ خداوند نے موسیٰ کو حکم دیا، اسی طرح بنی اسرائیل نے بھی کیا۔\n6۔ اور کچھ لوگ ایسے تھے جنہیں ایک آدمی کی لاش نے ناپاک کر دیا تھا، اور وہ اس دن عید فسح منا نہ سکے، اور وہ اس دن موسیٰ اور ہارون کے سامنے آئے:\n7۔ اور ان لوگوں نے اس سے کہا، ہم ایک آدمی کے مردہ جسم سے آلودہ ہیں: ہمیں کیوں روکا گیا ہے تاکہ ہم خداوند کی قربانی اس کے مقررہ وقت میں بنی اسرائیل میں پیش نہ کر سکیں؟\n8۔ اور موسیٰ نے ان سے کہا، رک جاؤ، اور میں سنوں گا کہ خداوند تمہارے بارے میں کیا حکم دے گا۔\n9۔ اور خداوند نے موسیٰ سے کہا،\n10۔ بنی اسرائیل سے فرماو، کہو، اگر تم میں سے یا تمہاری اولاد میں سے کوئی مرد مردہ جسم کی وجہ سے ناپاک ہو یا دور سفر پر ہو، تو وہ خدا کے پاس پاس کا جشن منائے۔\n11۔ دوسرے مہینے کے چودہویں دن کو وہ اسے رکھیں گے، {اور} اسے بغیر خمیر کے روٹی اور کڑوی جڑی بوٹیوں کے ساتھ کھائیں گے۔\n12۔ وہ اس میں سے کچھ بھی صبح تک نہیں چھوڑیں گے، نہ ہی اس کی کوئی ہڈی توڑیں گے: فسح کے تمام احکامات کے مطابق وہ اسے منائیں گے۔\n13۔ لیکن جو شخص پاک ہے، سفر میں نہیں ہے، اور فسح منانے سے باز رہے، تو وہی روح بھی اپنے لوگوں میں سے کاٹ دی جائے گی: کیونکہ اس نے اپنے مقررہ وقت میں خداوند کی قربانی نہیں دی، وہ انسان اپنا گناہ اٹھائے گا۔\n14۔ اور اگر کوئی اجنبی آپ کے درمیان قیام کرے اور خداوند کے پاس پاس اوور منائے؛ فسح کے حکم کے مطابق، اور اس کے طریقہ کار کے مطابق، وہ ایسا ہی کرے گا: تمہیں ایک ہی حکم ملے گا، اجنبی کے لیے اور اس کے لیے جو زمین میں پیدا ہوا ہو۔\n15۔ اور جس دن خیمہ اوپر اٹھایا گیا، بادل نے خیمہ گاہ کو ڈھانپ لیا، یعنی گواہی کا خیمہ بھی: اور یہاں تک کہ خیمہ پر بھی آگ کا ظہور تھا، یہاں تک کہ صبح تک۔\n16. ہمیشہ ایسا ہی تھا: دن میں بادل نے اسے ڈھانپ لیا تھا، اور رات کو آگ کا ظہور۔\n17۔ اور جب بادل خیمہ سے اٹھایا گیا، تو اس کے بعد بنی اسرائیل روانہ ہوئے: اور جہاں بادل رہتا تھا، وہاں بنی اسرائیل نے اپنے خیمے لگائے۔\n18۔ خداوند کے حکم پر بنی اسرائیل روانہ ہوئے، اور خداوند کے حکم پر وہ کھڑے ہوئے: جب تک بادل خیمہ پر رہا، وہ اپنے خیموں میں آرام کرتے رہے۔\n19۔ اور جب بادل خیمہ گاہ پر کئی دن رہا، تو بنی اسرائیل نے خداوند کی ذمہ داری سنبھالی اور سفر نہ کیا۔ {رکا...: عبرانی۔ پرولونگڈ}\n20۔ اور {یہ} ہوا، جب بادل خیمہ گاہ پر چند دن پہلے تھا؛ خداوند کے حکم کے مطابق وہ اپنے خیموں میں ٹھہرے، اور خداوند کے حکم کے مطابق سفر کیا۔\n21۔ اور {یوں} جب بادل صبح تک رہا، اور صبح کو بادل اٹھا لیا گیا، پھر وہ سفر کرتے: چاہے دن میں یا رات میں بادل اٹھایا جاتا، وہ سفر کرتے۔ {رہائش: عبرانی۔ تھا}\n22۔ یا {چاہے دو دن، یا ایک مہینہ، یا ایک سال} بادل خیمہ گاہ پر رہا، اور وہاں رہا، بنی اسرائیل اپنے خیموں میں ٹھہرے اور سفر نہیں کیا، لیکن جب بادل اٹھایا گیا تو وہ روانہ ہو گئے۔\n23۔ خداوند کے حکم پر وہ خیموں میں آرام کر گئے، اور خداوند کے حکم پر سفر کیا: انہوں نے خداوند کی ذمہ داری سنبھالی، خداوند کے حکم پر، موسیٰ کے ہاتھ سے۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ اپنے لیے چاندی کے دو بگل بنائیں؛ تم انہیں پورے ٹکڑے سے بنا سکتے ہو: تاکہ تم انہیں اجتماع کی دعوت اور کیمپوں کے سفر کے لیے استعمال کر سکو۔\n3۔ اور جب وہ ان کے ساتھ پھونک ماریں گے، تو تمام مجمع آپ کے پاس جماعت کے خیمہ کے دروازے پر جمع ہوں گے۔\n4۔ اور اگر وہ ایک {ترمپٹ} سے {لیکن} بجائیں، تو شہزادے، {جو ہزاروں اسرائیلیوں کے سر ہیں} آپ کے پاس جمع ہوں گے۔\n5۔ جب تم الارم بجاؤ گے، تو مشرقی حصوں میں موجود کیمپ آگے بڑھیں گے۔\n6۔ جب آپ دوسری بار الارم بجائیں گے، تو جنوبی جانب موجود کیمپ اپنا سفر کریں گے: وہ اپنے سفر کے لیے الارم بجائیں گے۔\n7۔ لیکن جب جماعت جمع ہو، تو تم بجا سکتے ہو، لیکن خبردار نہ کرو۔\n8۔ اور ہارون کے بیٹے، جو کاہن، ہوں گے، بگل سے بجائیں گے؛ اور یہ تمہارے لیے ہمیشہ تمہاری نسلوں کے لیے ایک حکم رہیں گے۔\n9۔ اور اگر تم اپنے ملک میں اس دشمن کے خلاف جنگ کرو جو تم پر ظلم کرتا ہے، تو تم بگل سے خطرے کی گھنٹی بجاؤ گے؛ اور تمہیں خداوند تمہارے خدا کے سامنے یاد رکھا جائے گا، اور تم اپنے دشمنوں سے نجات پاؤ گے۔\n10۔ اپنی خوشی کے دن، اپنے سنجیدہ دنوں میں، اور اپنے مہینوں کے آغاز میں، تم اپنے جلنے والے نذروں اور اپنی صلح کی قربانیوں پر بگل بجاؤ گے؛ تاکہ وہ آپ کے خدا کے سامنے ایک یادگار کے طور پر ہوں: میں آپ کا خداوند خدا ہوں۔\n11۔ اور دوسرے مہینے کے بیسویں دن، دوسرے سال میں، بادل گواہی کے خیمے سے اٹھا لیا گیا۔\n12۔ اور بنی اسرائیل نے سینا کے صحرا سے سفر کیا؛ اور بادل پاران کے جنگل میں آرام کر رہا تھا۔\n13۔ اور انہوں نے سب سے پہلے موسیٰ کے ہاتھوں خداوند کے حکم کے مطابق اپنا سفر کیا۔\n14۔ سب سے پہلے {جگہ} یہوداہ کے بچوں کے لشکروں کے مطابق کیمپ کا جھنڈا تھا: اور اس کے لشکر پر {تھا} ناہشون بیٹا امینادب۔\n15۔ اور اساکر کے بچوں کے قبیلے کے لشکر کے اوپر، نیتھنیئل، زوآر کا بیٹا۔\n16۔ اور زبولون کے بچوں کے قبیلے کے لشکر پر ایلیاب تھا جو ہیلون کا بیٹا تھا۔\n17۔ اور خیمہ گرا دیا گیا؛ اور گرشون کے بیٹے اور مراری کے بیٹے خیمہ لے کر آگے بڑھے۔\n18۔ اور روبن کے کیمپ کا جھنڈا ان کی فوجوں کے مطابق آگے بڑھا: اور اس کے لشکر پر الیزور بیٹا شیدور تھا۔\n19۔ اور شمعون کے بچوں کے قبیلے کے لشکر کے اوپر شلومیئل تھا، زریشادائی کا بیٹا۔\n20۔ اور گاد کے بچوں کے قبیلے کے لشکر کے اوپر ایلیاصاف، دیوئل کا بیٹا تھا۔\n21۔ اور کوہہیوں نے مزار کو لے کر آگے بڑھا: اور {دوسرے} نے خیمہ قائم کیا جو اس کے خلاف آ گئے۔ {دوسرا: یعنی گرشونائٹس اور میرارائٹس}\n22۔ اور افریم کے بچوں کے کیمپ کا جھنڈا ان کی فوجوں کے مطابق پیش کیا گیا: اور اس کے لشکر کے اوپر الیشامہ بیٹا امیہود تھا۔\n23۔ اور مناسی کے بچوں کے قبیلے کے لشکر پر گمالیئل تھا، جو پیڈاہزور کا بیٹا تھا۔\n24۔ اور بنیامین کے بچوں کے قبیلے کے لشکر پر عبیدان تھا جو جدعونی کا بیٹا تھا۔\n25۔ اور دان کے بچوں کے خیمے کا جھنڈا آگے بڑھا، {جو کہ} تمام کیمپوں کا ان کے لشکروں کا انعام تھا: اور اس کے لشکر پر {تھا} احیزر بیٹا امیشادائی۔\n26۔ اور آشر کے بچوں کے قبیلے کے لشکر پر پاگیئل، اوکران کا بیٹا۔\n27۔ اور نفتالی کے بچوں کے قبیلے کے لشکر کے اوپر، احیرا جو اینان کا بیٹا تھا۔\n28. یوں بنی اسرائیل کے سفر ان کی فوجوں کے مطابق تھے جب وہ روانہ ہوئے۔ {یوں: عبرانی۔ یہ}\n29۔ اور موسیٰ نے ہوباب سے کہا، جو راگیول مدیانی کے بیٹے اور موسیٰ کے سسر تھے، ہم اس جگہ کی طرف جا رہے ہیں جس کے بارے میں خداوند نے فرمایا، میں تمہیں دوں گا: تو ہمارے ساتھ آؤ، اور ہم تمہارے لیے بھلائی کریں گے: کیونکہ خداوند نے اسرائیل کے بارے میں اچھا کہا ہے۔\n30۔ اور اس نے اس سے کہا، میں نہیں جاؤں گا؛ لیکن میں اپنی زمین اور اپنے رشتہ داروں کی طرف روانہ ہو جاؤں گا۔\n31۔ اور اس نے کہا، ہمیں مت چھوڑو، میں تم سے درخواست کرتا ہوں؛ کیونکہ تم جانتے ہو کہ ہم جنگل میں کیسے کیمپ کریں گے، اور شاید تم ہمارے لیے آنکھوں کی بجائے ہو۔\n32۔ اور اگر تم ہمارے ساتھ چلے جاؤ گے، تو ہاں، وہی ہوگا جو خداوند ہمارے ساتھ کرے گا، وہی ہم تمہارے ساتھ کریں گے۔\n33۔ اور وہ خداوند کے پہاڑ سے تین دن کے سفر پر روانہ ہوئے: اور خداوند کے عہد کا صندوق ان کے سامنے تین دن کے سفر میں آیا، تاکہ ان کے لیے آرام گاہ تلاش کرے۔\n34۔ اور جب وہ کیمپ سے باہر نکلے تو دن میں خداوند کا بادل ان پر پڑا۔\n35۔ اور جب صندوق آگے بڑھا، تو موسیٰ نے کہا: اے خداوند، اٹھو اور اپنے دشمنوں کو منتشر کر دے؛ اور جو لوگ تم سے نفرت کرتے ہیں وہ تمہارے سامنے بھاگ جائیں۔\n36۔ اور جب وہ آرام کر گیا، اس نے کہا، اے خداوند، ہزاروں اسرائیلیوں کی طرف لوٹ آؤ۔ {کئی ہزار: عبرانی۔ دس ہزار ہزار}","1۔ اور جب لوگوں نے شکایت کی، تو یہ خدا کو ناگوار گزرا: اور خداوند نے سنا؛ اور اس کا غصہ بھڑک اٹھا؛ اور خداوند کی آگ ان کے درمیان جل گئی، اور کیمپ کے سب سے کونے میں ان لوگوں کو جلا دیا۔ {شکایت: یا، جیسے شکایت کرنے والے} {یہ ناپسندیدہ ہے: عبرانی۔ یہ کانوں میں برائی تھی}\n2۔ اور لوگوں نے موسیٰ کو پکارا؛ اور جب موسیٰ نے خداوند سے دعا کی، تو آگ بجھ گئی۔ {تھا...: عبرانی۔ ڈوب گئی}\n3۔ اور اس نے اس جگہ کا نام تبرہ رکھا: کیونکہ خداوند کی آگ ان میں جل رہی تھی۔ {تبیرہ: یعنی، اے برننگ}\n4۔ اور ان میں سے جو مخلوط ہجوم تھا وہ ہوس میں مبتلا ہو گیا: اور بنی اسرائیل بھی دوبارہ رونے لگے اور کہا، ہمیں گوشت کون دے گا؟ {گرنا...: عبرانی۔ ہوس میں مبتلا تھا} {رویا...: عبرانی۔ واپس آیا اور رویا}\n5۔ ہم مچھلی کو یاد کرتے ہیں، جو ہم مصر میں آزادانہ کھاتے تھے؛ کھیرا، خربوزہ، لیک، پیاز، اور لہسن:\n6. لیکن اب ہماری روح {سوکھ چکی ہے}: {یہاں کچھ بھی نہیں} سوائے اس من، {ہماری آنکھوں کے سامنے}۔\n7۔ اور مانا دھنیا کے بیج کی طرح تھا، اور اس کا رنگ بدیلیم کے رنگ کے طور پر۔ {اس کا رنگ...: عبوری۔ آئی آف اٹ کی آنکھ کے طور پر}\n8۔ {اور} لوگ ادھر ادھر گھومتے رہے، اسے جمع کرتے، چکیوں میں پیسے، یا موٹر میں پھینٹتے، اور برتنوں میں بیک کرتے، اور اس سے کیک بناتے: اور اس کا ذائقہ تازہ تیل کے ذائقے جیسا تھا۔\n9۔ اور جب رات کو اوس کیمپ پر پڑی، تو منا اس پر گرے۔\n10۔ پھر موسیٰ نے لوگوں کو اپنے خاندانوں میں روتے سنا، ہر آدمی اپنے خیمے کے دروازے پر تھا: اور خداوند کا غصہ بہت زیادہ بھڑک اٹھا؛ موسیٰ بھی ناخوش تھا۔\n11۔ اور موسیٰ نے خداوند سے کہا، تو نے اپنے بندے کو کیوں ستایا؟ اور میں نے تمہاری نظر میں کیوں فضل نہیں پایا، کہ تم نے ان سب لوگوں کا بوجھ مجھ پر ڈال دیا؟\n12. کیا میں نے یہ سب لوگ پیدا کیے ہیں؟ کیا میں نے انہیں پیدا کیا ہے کہ تم مجھ سے کہو، انہیں اپنی گود میں لے آؤ، جیسے دودھ پلانے والا باپ دودھ پینے والے بچے کو جنم دیتا ہے، اس زمین پر جہاں تم اپنے باپ داووں کو دیتے ہو؟\n13۔ مجھے ان سب لوگوں کو دینے کے لیے گوشت کہاں سے ملے؟ کیونکہ وہ مجھ سے روتے ہیں اور کہتے ہیں، ہمیں گوشت دو، تاکہ ہم کھا سکیں۔\n14. میں ان سب لوگوں کو اکیلے برداشت نہیں کر سکتا، کیونکہ یہ میرے لیے بہت بھاری ہے۔\n15۔ اور اگر تم میرے ساتھ ایسا سلوک کرو گے تو مجھے مار دو، میں تم سے درخواست کرتا ہوں، اگر میں نے تمہاری نظر میں مہربانی پا لی ہے؛ اور مجھے اپنی بدحالی نہ دیکھنے دو۔\n16۔ اور خداوند نے موسیٰ سے کہا، میرے پاس اسرائیل کے بزرگوں میں سے ستر آدمی جمع کرو، جنہیں تم لوگوں کے بزرگ اور ان کے افسر جانتے ہو؛ اور انہیں جماعت کے خیمے میں لے آؤ، تاکہ وہ وہاں تمہارے ساتھ کھڑے ہوں۔\n17۔ اور میں نیچے آؤں گا اور وہاں تم سے بات کروں گا: اور میں اس روح سے جو تم پر ہے اسے لے کر ان پر رکھوں گا؛ اور وہ تمہارے ساتھ لوگوں کا بوجھ اٹھائیں گے، جو تم اکیلے نہیں اٹھاؤ گے۔\n18۔ اور لوگوں سے کہو، کل تک خود کو پاک کرو، اور گوشت کھاؤ گے، کیونکہ تم خداوند کے کانوں میں روتے ہوئے کہتے ہو، کون ہمیں گوشت دے گا؟ کیونکہ مصر میں ہمارے لیے اچھا تھا: اس لیے خداوند تمہیں گوشت دے گا، اور تم کھاؤ گے۔\n19۔ تم ایک دن نہیں کھاؤ گے، نہ دو دن، نہ پانچ دن، نہ دس دن، نہ بیس دن۔\n20۔ {لیکن} پورا مہینہ بھی، جب تک کہ یہ تمہاری ناک سے باہر نہ آئے، اور یہ تمہارے لیے نفرت انگیز ہو: کیونکہ تم نے اپنے درمیان موجود خداوند کو حقیر سمجھا، اور اس کے سامنے روتے ہوئے کہا، ہم مصر سے کیوں نکلے؟ {پور...: عبوری۔ دن کا مہینہ}\n21۔ اور موسیٰ نے کہا، وہ لوگ، جن میں میں {ہوں}، {ہیں} چھ لاکھ پیادہ ہیں؛ اور تم نے کہا ہے، میں انہیں گوشت دوں گا تاکہ وہ پورا مہینہ کھا سکیں۔\n22۔ کیا ان کے لیے ریوڑ اور ریوڑ ذبح کیے جائیں گے، تاکہ وہ کافی ہوں؟ یا سمندر کی تمام مچھلیاں ان کے لیے اکٹھی کی جائیں گی، تاکہ انہیں کافی بنایا جا سکے؟\n23۔ اور خداوند نے موسیٰ سے کہا، کیا خداوند کا ہاتھ چھوٹا ہو گیا ہے؟ اب دیکھو گے کہ میرا کلام تم پر پورا اترتا ہے یا نہیں۔\n24۔ اور موسیٰ باہر گیا، اور لوگوں کو خداوند کے الفاظ سنائے اور قوم کے بزرگوں کے ستر مردوں کو جمع کیا اور انہیں خیمہ گاہ کے گرد جمع کر دیا۔\n25۔ اور خداوند بادل میں نیچے آیا، اس سے بات کی، اور اس روح کو لے لیا جو اس پر تھی، اور ستر بزرگوں کو دے دی: اور یہ ہوا کہ جب روح ان پر پڑی، انہوں نے نبوت کی، اور رکا نہیں۔\n26۔ لیکن کیمپ میں دو مرد باقی تھے، ایک کا نام ایلداد تھا، اور دوسرے میداد کا نام: اور روح ان پر سکون کر گئی؛ اور وہ ان میں سے تھے جو لکھے گئے تھے، لیکن خیمہ گاہ میں نہیں گئے: اور انہوں نے کیمپ میں پیش گوئی کی۔\n27۔ اور وہاں ایک نوجوان بھاگا، اور موسیٰ کو بتایا، اور کہا، ایلداد اور میداد کیمپ میں نبوت کرتے ہیں۔\n28۔ اور یشوع، نون کا بیٹا، موسیٰ کا خادم، اس کے نوجوانوں میں سے ایک، نے جواب دیا اور کہا، میرے آقا موسیٰ، انہیں منع کر۔\n29۔ اور موسیٰ نے اس سے کہا، کیا تم میرے لیے حسد کرتے ہو؟ کاش خدا کے تمام لوگ نبی ہوتے، {اور} خدا اپنی روح ان پر ڈالتا!\n30۔ اور موسیٰ نے اسے اور اسرائیل کے بزرگوں کو کیمپ میں لے گیا۔\n31۔ اور خداوند کی طرف سے ایک ہوا آئی، اور سمندر سے بٹیر لے آئی، اور انہیں کیمپ کے پاس گرا دیا، جیسے یہ اس طرف ایک دن کا سفر ہو، اور دوسری طرف ایک دن کا سفر ہو، کیمپ کے گرد اور زمین کی سطح پر دو ہاتھ بلند ہوں۔ {جیسے یہ ایک دن کا...: عبرانی۔ جیسے یہ دن کا طریقہ ہو}\n32۔ اور لوگ اس دن، اور اس رات اور اگلے دن کھڑے ہو گئے، اور بٹیر جمع کیے: جو کم سے کم جمع ہوئے اس نے دس ہومر جمع کیے: اور انہوں نے اپنے لیے کیمپ کے ارد گرد سب کچھ پھیلا دیا۔\n33۔ اور جب گوشت ابھی ان کے دانتوں کے درمیان تھا، چبانے سے پہلے، خداوند کا غضب لوگوں پر بھڑک اٹھا، اور خداوند نے لوگوں پر ایک بہت بڑی آفت دی۔\n34۔ اور اس نے اس جگہ کا نام کیبروتھ ہٹاوا رکھا: کیونکہ وہاں وہ لوگ دفناتے تھے جو ہوس چاہتے تھے۔ {کیبروتھتاواہ: یعنی، ہوس کی قبریں}\n35۔ {اور} لوگ کیبروتھتاواہ سے ہزروت تک روانہ ہوئے؛ اور ہازیروتھ میں رہائش اختیار کی۔ {رہائش پر: عبرانی وہ اندر تھے}","1۔ اور مریم اور ہارون نے موسیٰ کے خلاف اس ایتھوپیائی عورت کی وجہ سے بات کی جس سے اس نے شادی کی تھی: کیونکہ اس نے ایک ایتھوپیائی عورت سے شادی کی تھی۔ {ایتھوپین: یا، کشیٹ} {شادی شدہ: ہیب۔ لے لیا گیا}\n2۔ اور انہوں نے کہا، کیا واقعی خداوند نے صرف موسیٰ کے ذریعے بات کی ہے؟ کیا اس نے ہم سے بھی بات نہیں کی؟ اور خداوند نے سنا۔\n3. (اب وہ شخص موسیٰ {تھا} بہت عاجز تھا، ان تمام لوگوں سے بڑھ کر جو زمین پر تھے۔)\n4۔ اور خداوند نے اچانک موسیٰ، ہارون اور مریم سے کہا، تینوں جماعت کے خیمے میں آؤ۔ اور وہ تینوں باہر آ گئے۔\n5۔ اور خداوند بادل کے ستون میں اترا، اور خیمہ گاہ کے دروازے میں کھڑا ہوا، اور ہارون اور مریم کو بلایا: اور وہ دونوں باہر آئے۔\n6۔ اور اس نے کہا، اب میری باتیں سنو: اگر تم میں سے کوئی نبی ہو، تو خداوند خود کو ایک خواب میں اس کے سامنے ظاہر کرے گا، اور خواب میں اس سے بات کرے گا۔\n7. میرا خادم موسیٰ ایسا نہیں ہے، جو میرے پورے گھر میں وفادار ہے۔\n8۔ میں اس کے ساتھ منہ بہ منہ بات کروں گا، چاہے بظاہر ہو، اور تاریک باتوں میں نہیں؛ اور وہ خداوند کی مثال دیکھے گا: تو پھر تم میرے بندے موسیٰ کے خلاف بولنے سے کیوں نہیں ڈرے؟\n9۔ اور خداوند کا غصہ ان پر بھڑک اٹھا؛ اور وہ روانہ ہو گئے۔\n10۔ اور بادل خیمہ گاہ سے روانہ ہوا؛ اور دیکھو، مریم {کوڑھی} بن گئی، {برف کی طرح سفید}: اور ہارون نے مریم کو دیکھا، اور دیکھو، {وہ} کوڑھی تھی۔\n11۔ اور ہارون نے موسیٰ سے کہا، افسوس، میرے رب، میں تم سے التجا کرتا ہوں، ہم پر وہ گناہ نہ ڈالو جو ہم نے بے وقوفی سے کیا اور جس میں ہم نے گناہ کیا۔\n12۔ وہ ایک مردہ کی طرح نہ ہو، جس کا گوشت آدھا کھا چکا ہو جب وہ اپنی ماں کے پیٹ سے نکلے۔\n13۔ اور موسیٰ نے خداوند سے پکارا، کہا، اے خدا، اب اسے شفا دے، میں تجھ سے التجا کرتا ہوں۔\n14۔ اور خداوند نے موسیٰ سے کہا، اگر اس کے والد نے صرف اس کے منہ پر تھوک دیا ہوتا، تو کیا اسے سات دن شرمندہ نہیں ہونا چاہیے؟ اسے سات دن کیمپ سے باہر رکھا جائے، اور اس کے بعد دوبارہ قبول کیا جائے۔\n15۔ اور مریم کو سات دن تک کیمپ سے باہر رکھا گیا: اور لوگ اس وقت تک نہیں گئے جب تک مریم کو دوبارہ نہ لایا گیا۔\n16۔ اور اس کے بعد لوگ ہزروت سے نکل گئے اور پاران کے ویرانے میں چلے گئے۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ تو لوگوں کو بھیجو تاکہ وہ کنعان کی زمین کی تلاش کریں، جو میں بنی اسرائیل کو دیتا ہوں: ان کے ہر قبیلے میں سے ایک آدمی بھیجو، ہر ایک ان میں سے حکمران۔\n3۔ اور موسیٰ نے خداوند کے حکم سے انہیں پران کے بیابان سے بھیجا: وہ سب لوگ بنی اسرائیل کے سر تھے۔\n4۔ اور یہ ان کے نام تھے: قبیلہ روبن کے، شموع زکر کا بیٹا۔\n5۔ شمعون قبیلے سے، شافعت، ہوری کا بیٹا۔\n6۔ یہوداہ قبیلے سے، کالب، یپھونہ کا بیٹا۔\n7۔ اساکر قبیلے سے، ایگال، یوسف کا بیٹا۔\n8۔ افرایم قبیلے سے، اوشیع، نون کا بیٹا۔ {اوشیع: جسے یشوع بھی کہا جاتا ہے}\n9۔ بنیامین قبیلے سے، پالتی رافو کا بیٹا۔\n10۔ زبولون قبیلے سے، گادیئل، سودی کا بیٹا۔\n11۔ یوسف کے قبیلے سے، {یعنی} قبیلہ مناسے، گدی جو سوسی کا بیٹا تھا۔\n12۔ دان کے قبیلے سے، عموئیل، جمالی کا بیٹا۔\n13۔ آشر قبیلے سے، سیتھر جو مائیکل کا بیٹا تھا۔\n14۔ نفتالی قبیلے سے، نہبی ووپسی کا بیٹا۔\n15۔ گاد قبیلے سے، جیول بیٹا ماچی۔\n16۔ یہ ان لوگوں کے نام ہیں جنہیں موسیٰ نے زمین کی جاسوسی کے لیے بھیجا تھا۔ اور موسیٰ نے اوشیہ کو نون یہوشع کا بیٹا کہا۔ {اوشیا: جسے جوشوا بھی کہا جاتا ہے} {یہوشوع: یا، یشوع}\n17۔ اور موسیٰ نے انہیں کنعان کی زمین کی جاسوسی کے لیے بھیجا اور کہا، تم اس طرف جنوب کی طرف چلو، اور پہاڑ کی طرف چڑھو:\n18۔ اور زمین کو دیکھو، وہ کیا ہے؛ اور وہ لوگ جو وہاں رہتے ہیں، چاہے وہ مضبوط ہوں یا کمزور، کم ہوں یا کچھ؛\n19۔ اور وہ زمین کیا ہے جس میں وہ رہتے ہیں، چاہے وہ اچھی ہو یا بری؛ اور وہ کون سے شہر ہیں جہاں وہ رہتے ہیں، چاہے خیموں میں ہوں یا قلعوں میں؛\n20۔ اور زمین کیا ہے، چاہے وہ موٹی ہو یا پتلی، چاہے اس میں لکڑی ہو یا نہ ہو۔ اور اچھے بہادر رہو اور زمین کے پھل لاؤ۔ اب وہ وقت تھا جو پہلے پکے ہوئے انگور کا وقت تھا۔\n21۔ تو وہ اوپر گئے، اور زین کے بیابان سے ریحوب تک زمین کی تلاش کی، جیسے لوگ حمات آتے ہیں۔\n22۔ اور وہ جنوب سے چڑھے اور حبرون پہنچے؛ جہاں اہیمان، شیشائی اور تلمائی، اناک کے بچے، {تھے}۔ (اب ہیبرون مصر میں زوان سے سات سال پہلے تعمیر ہوا تھا۔)\n23۔ اور وہ اشکول کے ندی پر پہنچے، اور وہاں سے ایک شاخ کاٹی جس میں ایک انگور کا گچھا تھا، اور اسے دو کے درمیان ایک لاٹھی پر رکھ دیا؛ اور {انہوں نے انار اور انجیر لائے تھے}۔ {بروک: اور، وادی}\n24۔ اس جگہ کو اشکول ندی کہا جاتا تھا، کیونکہ وہاں سے بنی اسرائیل نے انگور کے گچھے کاٹے تھے۔ {بروک: اور، وادی} {ایشکول: یعنی، انگوروں کا ایک گچھہ}\n25۔ اور وہ چالیس دن بعد زمین کی تلاش سے واپس آئے۔\n26۔ اور وہ موسیٰ کے پاس، ہارون کے پاس، اور بنی اسرائیل کی تمام جماعت کے پاس، پران کے بیابان، قادیش کے پاس گئے؛ اور انہیں اور تمام جماعت کو پیغام دیا، اور انہیں زمین کا پھل دکھایا۔\n27۔ اور انہوں نے اسے بتایا اور کہا، \"ہم اس زمین پر آئے جہاں تم نے ہمیں دیکھا، اور یقینا وہ دودھ اور شہد سے بہتی ہے؛ اور یہی اس کا نتیجہ ہے۔\n28۔ پھر بھی لوگ مضبوط ہیں جو زمین میں بستے ہیں، اور شہر دیواروں سے گھرے ہوئے ہیں، اور بہت عظیم ہیں: اور ہم نے وہاں انک کے بچوں کو بھی دیکھا۔\n29۔ عمالقی جنوب کی سرزمین میں رہتے ہیں؛ اور حتی، اور یبوسی، اور اموری پہاڑوں میں رہتے ہیں؛ اور کنعانیوں سمندر کے کنارے اور اردن کے ساحل پر رہتے ہیں۔\n30۔ اور کیلیب نے لوگوں کو موسیٰ کے سامنے روک دیا اور کہا، آؤ فورا اوپر چلیں اور اسے حاصل کریں؛ کیونکہ ہم اس پر قابو پانے کے قابل ہیں۔\n31۔ لیکن جو لوگ اس کے ساتھ گئے انہوں نے کہا، ہم لوگوں کے خلاف نہیں جا سکتے؛ کیونکہ وہ ہم سے زیادہ طاقتور ہیں۔\n32۔ اور انہوں نے اسرائیل کے بچوں کو اس زمین کی بری خبر سنائی جس کی انہوں نے تلاش کی تھی، اور کہا، 'وہ زمین جس سے ہم گئے ہیں، وہ زمین ہے جو اس کے باشندوں کو کھا جاتی ہے؛ اور جتنے لوگ ہم نے اس میں دیکھے وہ عظیم قد کے لوگ تھے۔ {مرد...: عبرانی۔ قد کے آدمی}\n33۔ اور وہاں ہم نے دیووں کو دیکھا، انک کے بیٹے، {جو دیووں کے ہیں}: اور ہم اپنی نظر میں ٹڈوں کی طرح تھے، اور ہم ان کی نظر میں تھے۔","1۔ اور تمام جماعت نے اپنی آواز بلند کی اور رونے لگے؛ اور لوگ اس رات رو پڑے۔\n2۔ اور تمام بنی اسرائیل نے موسیٰ اور ہارون کے خلاف سرگوشیاں کیں: اور پوری جماعت نے ان سے کہا، کاش ہم مصر کی زمین میں مر جاتے! یا خدا کرے ہم اس صحرا میں مر جاتے!\n3۔ اور خداوند نے ہمیں اس زمین پر کیوں لایا ہے، تلوار کے ہاتھوں مارنے کے لیے، تاکہ ہماری بیویاں اور بچے شکار بن جائیں؟ کیا ہمارے لیے بہتر نہیں تھا کہ ہم مصر واپس جائیں؟\n4۔ اور انہوں نے ایک دوسرے سے کہا، آؤ کپتان بنیں، اور مصر واپس چلے جائیں۔\n5۔ پھر موسیٰ اور ہارون بنی اسرائیل کی تمام جماعت کے سامنے چہروں کے بل گر گئے۔\n6۔ اور یشوع، نون کا بیٹا، اور کیلب یپھنہ کا بیٹا، جو زمین کی تلاش کرنے والوں میں سے تھے، نے اپنے کپڑے پھاڑ دیے:\n7۔ اور انہوں نے بنی اسرائیل کی تمام جماعت سے کہا، کہا، وہ زمین جس سے ہم اس کی تلاش کے لیے گزرے، وہ بہت اچھی زمین ہے۔\n8۔ اگر خداوند ہم میں خوش ہو، تو وہ ہمیں اس زمین میں لے آئے گا اور ہمیں دے گا؛ ایک ایسی زمین جو دودھ اور شہد سے بہتی ہے۔\n9۔ صرف خداوند کے خلاف بغاوت نہ کرو، نہ ہی زمین کے لوگوں سے ڈرو؛ کیونکہ وہ ہمارے لیے روٹی ہیں: ان کی حفاظت ان سے ہٹ چکی ہے، اور خداوند ہمارے ساتھ ہے: ان سے نہ ڈرو۔ سایہ}\n10۔ لیکن تمام جماعت نے انہیں پتھروں سے سنگسار کرنے کا حکم دیا۔ اور خداوند کی شان جماعت کے خیمہ میں بنی اسرائیل کے تمام بچوں کے سامنے ظاہر ہوئی۔\n11۔ اور خداوند نے موسیٰ سے کہا، یہ قوم مجھے کب تک اشتعال دلاتی رہے گی؟ اور کب تک وہ مجھ پر یقین کریں گے، ان تمام نشانیوں کے باوجود جو میں نے ان میں دکھائے ہیں؟\n12۔ میں انہیں وبا سے تباہ کر دوں گا، انہیں وراثت سے محروم کر دوں گا، اور تمہیں ان سے بڑا اور طاقتور بنا دوں گا۔\n13۔ اور موسیٰ نے خداوند سے کہا، پھر مصری سنیں گے، (کیونکہ تو نے ان میں سے اپنی طاقت میں اس قوم کو جنم دیا؛)\n14۔ اور وہ اس زمین کے باشندوں کو بتائیں گے: کیونکہ انہوں نے سنا ہے کہ تو خداوند ان لوگوں میں ہے، تو خداوند سامنے نظر آتا ہے، اور تمہارا بادل ان کے اوپر کھڑا ہے، اور تم دن کے وقت بادل کے ستون میں اور رات کو آگ کے ستون میں ان کے سامنے جاتے ہو۔\n15۔ اب {اگر} تم اس قوم کو ایک ہی طرح مارو گے، تو وہ قومیں جنہوں نے تمہاری شہرت سنی ہے، کہیں گی،\n16۔ کیونکہ خداوند اس قوم کو اس زمین میں نہ لا سکا جس سے اس نے ان سے قسم کھائی تھی، اس لیے اس نے انہیں بیابان میں قتل کر دیا۔\n17۔ اور اب، میں تم سے التجا کرتا ہوں، میرے رب کی طاقت عظیم ہو، جیسا کہ تم نے کہا ہے،\n18. خداوند صبر کرنے والا اور بہت مہربان ہے، گناہوں اور گناہوں کو معاف کرنے والا ہے، اور کسی بھی صورت میں [مجرم} کو صاف نہیں کرتا، بلکہ باپ کی بدکاری بچوں پر تیسری اور چوتھی نسل تک پہنچاتا ہے۔\n19۔ معاف کرنا، میں تم سے درخواست کرتا ہوں، اس قوم کی بدکاری جو تیری رحمت کی عظمت کے مطابق ہے، اور جیسا کہ تم نے اس قوم کو معاف کیا، مصر سے اب تک۔ {یہاں تک...: یا، اب تک}\n20۔ اور خداوند نے فرمایا، میں نے تیرے کلام کے مطابق معاف کر دیا ہے:\n21. لیکن {جیسا کہ میں واقعی زندہ ہوں}، ساری زمین خداوند کی جلال سے بھر جائے گی۔\n22۔ کیونکہ وہ تمام لوگ جنہوں نے میری شان و شوکت اور میرے معجزات دیکھے، جو میں نے مصر اور بیابان میں کیے، اور اب مجھے دس بار آزمایا ہے، اور میری آواز نہیں سنے؛\n23. یقینا وہ اس زمین کو نہیں دیکھیں گے جس کی میں نے ان کے باپ اجداد سے قسم کھائی ہے، اور نہ ہی ان میں سے کوئی بھی جس نے مجھے اکسایا وہ نہیں دیکھے گا: {یقینا...: عبرانی۔ اگر وہ زمین دیکھیں}\n24۔ لیکن میرے خادم کیلب، کیونکہ اس کے ساتھ ایک اور روح تھی اور وہ مکمل طور پر میرے پیچھے آیا، میں اسے اس زمین میں لے جاؤں گا جہاں وہ گیا تھا؛ اور اس کا بیج اسے حاصل کرے گا۔\n25۔ (اب امالیکی اور کنعانی وادی میں رہتے تھے۔) کل تمہیں موڑ دے گا، اور تمہیں بحیرہ احمر کے راستے جنگل میں لے جائے گا۔\n26۔ اور خداوند نے موسیٰ اور ہارون سے کہا،\n27. میں اس ظالم جماعت کے ساتھ کتنی دیر تک برداشت کروں گا، جو میرے خلاف سرگوشیاں کر رہی ہے؟ میں نے بنی اسرائیل کی سرگوشیاں سنی ہیں، جو وہ میرے خلاف سرگوشیاں کرتے ہیں۔\n28۔ ان سے کہو، {جتنا سچ میں} میں زندہ ہوں، خداوند فرماتا ہے، جیسے تم نے میرے کانوں میں کہا، میں بھی تمہارے ساتھ کروں گا:\n29۔ تمہاری لاشیں اس بیابان میں گریں گی؛ اور وہ سب جو تم میں سے گنے گئے تھے، تمہاری پوری تعداد کے مطابق، بیس سال کی عمر سے اور اس سے اوپر، جنہوں نے میرے خلاف سرگوشیاں کی ہیں،\n30۔ یقینا تم اس زمین میں نہیں آؤ گے، {جس کے بارے میں} میں تمہیں وہاں بساؤں گا، سوائے کیلب جو یپھنہ کا بیٹا ہے، اور یوشع نون کا بیٹا۔ {قسم کھانا: عبرانی۔ میرا ہاتھ اٹھایا}\n31۔ لیکن تمہارے چھوٹے بچے، جنہیں تم نے شکار سمجھا تھا، میں انہیں لے آؤں گا، اور وہ اس زمین کو جان لیں گے جسے تم نے حقیر سمجھا۔\n32. لیکن {جہاں تک} تمہاری لاشیں ہیں، وہ اس صحرا میں گر جائیں گی۔\n33۔ اور تمہارے بچے چالیس سال تک بیابان میں بھٹکیں گے، اور تمہاری بدکاری برداشت کریں گے، یہاں تک کہ تمہاری لاشیں صحرا میں ضائع ہو جائیں گی۔ {آوارہ: یا، کھلاؤ}\n34۔ ان دنوں کی تعداد کے بعد جب تم نے زمین کی تلاش کی، {حتی} چالیس دن، ہر دن ایک سال تک، تم اپنے گناہوں کو برداشت کرو گے، چالیس سال، اور تم میرے وعدے کی خلاف ورزی جان جاؤ گے۔ {بریچ...: یا، میرے مقصد میں تبدیلی}\n35۔ میں خداوند نے فرمایا ہے، میں یقینا یہ سب برے گروہ کے ساتھ کروں گا، جو میرے خلاف جمع ہیں: وہ اس ویرانے میں کھا جائیں گے، اور وہیں مر جائیں گے۔\n36۔ اور وہ لوگ جنہیں موسیٰ نے زمین کی تلاشی کے لیے بھیجا تھا، جو واپس آئے اور تمام جماعت کو اس کے خلاف سرگوشی کرنے پر مجبور کیا، زمین پر بدنامی کر کے،\n37۔ حتیٰ کہ وہ لوگ جنہوں نے زمین پر برائی کی خبر دی، وہ بھی خداوند کے سامنے وبا سے مر گئے۔\n38۔ لیکن یشوع، نون کا بیٹا، اور کالب، یپھونہ کا بیٹا، {جو تھے} ان لوگوں میں سے تھے جو زمین کی تلاش کے لیے گئے تھے، {ابھی بھی} زندہ تھے۔\n39۔ اور موسیٰ نے یہ اقوال سب بنی اسرائیل کو سنائے اور لوگوں نے بہت غم منایا۔\n40۔ اور وہ صبح سویرے اٹھے اور انہیں پہاڑ کی چوٹی پر لے گئے، کہا، دیکھو، ہم یہاں ہوں گے، اور اس جگہ جائیں گے جس کا خداوند نے وعدہ کیا ہے: کیونکہ ہم نے گناہ کیا ہے۔\n41۔ اور موسیٰ نے کہا، اب تم خداوند کے حکم کی خلاف ورزی کیوں کرتے ہو؟ لیکن یہ کامیاب نہیں ہوگا۔\n42۔ اوپر نہ جانا، کیونکہ خداوند تم میں نہیں ہے؛ تاکہ تم اپنے دشمنوں کے سامنے گرفتار نہ ہو۔\n43۔ کیونکہ عمالقی اور کنعانی تمہارے سامنے ہیں، اور تم تلوار کے ہاتھوں مارو گے: کیونکہ تم خداوند سے دور ہو گئے ہو، اس لیے خداوند تمہارے ساتھ نہیں ہوگا۔\n44۔ لیکن انہوں نے پہاڑی کی چوٹی تک جانے کا ارادہ کیا: پھر بھی خداوند کے عہد کا صندوق اور موسیٰ کیمپ سے باہر نہیں نکلے۔\n45۔ پھر امالیقی نیچے آئے، اور کنعانیوں جو اس پہاڑی میں رہتے تھے، انہیں مارا پیٹا اور انہیں پریشان کر دیا، حتیٰ کہ ہورمہ تک۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل سے بات کرو، اور ان سے کہو، جب تم اپنی رہائش گاہوں کی زمین میں آؤ، جسے میں تمہیں دیتا ہوں،\n3۔ اور خداوند کو آگ میں نذرانہ پیش کرے، نذر کی ادائیگی میں جلتی قربانی، یا عہد کی ادائیگی میں قربانی، یا آزاد مرضی کی قربانی، یا تمہاری سنجیدہ تہواروں میں، تاکہ خداوند، ریوڑ یا ریوڑ کے لیے میٹھا ذائقہ پیش کرے: {انجام دینا: عبرانی۔ علیحدگی}\n4۔ پھر جو اپنی قربانی خداوند کو پیش کرے گا، وہ تیل کے تیل کے چوتھے حصے کے ساتھ آٹے کے دسواں حصے کا گوشت پیش کرے گا۔\n5۔ اور ایک ہین شراب کا چوتھا حصہ، جو تم ایک بکری کے لیے جلانے کی قربانی یا قربانی کے ساتھ تیار کرو گے۔\n6۔ یا مینڈھے کے لیے، آپ گوشت کی پیشکش کے لیے تیار کریں گے، جس میں دو دسویں حصے آٹے کے ساتھ تیل کے تیسرے حصے کو ملا کر رکھیں۔\n7۔ اور ایک شراب کی قربانی کے بدلے تم شراب کے تین حصے کو پیش کرو گے، {کیونکہ یہ خداوند کے لیے میٹھا ذائقہ ہے۔'\n8۔ اور جب تم بیل تیار کرو {جلنے کی قربانی} کے لیے، یا {نذر کے لیے} قربانی کے لیے، یا خداوند کے لیے صلح کی نذرانے کے لیے:\n9۔ پھر وہ بیل کے ساتھ تین دسویں آٹے کے گوشت کی قربانی لے کر آئے گا جس میں آدھا ہن تیل ملا ہو۔\n10۔ اور تم آدھا ہین شراب کے لیے پیش کرو گے، جو آگ سے دی گئی نذرانہ، خداوند کے لیے میٹھا ذائقہ ہے۔\n11۔ یہ ایک بیل، یا ایک مینڈھے کے لیے، یا بکری کے لیے، یا بچے کے لیے کیا جائے گا۔\n12۔ جس تعداد کو تم تیار کرو گے، اس کے مطابق ہر ایک کے ساتھ ان کی تعداد کے مطابق ایسا ہی کرو گے۔\n13۔ جو بھی دیہات سے پیدا ہوتا ہے وہ یہ کام اسی طرح کرے گا، آگ سے پیش کی گئی نذرانہ میں، جو خداوند کو میٹھا ذائقہ ہے۔\n14۔ اور اگر کوئی اجنبی آپ کے ساتھ یا آپ کی نسلوں میں سے کوئی بھی شخص ٹھہرے اور خدا کے لیے آگ سے پیش کی گئی میٹھا ذائقہ پیش کرے؛ جیسا تم کرتے ہو، وہ بھی کرے گا۔\n15۔ ایک فرمان {ہو گا} آپ کے لیے جماعت کے لیے، اور اس اجنبی کے لیے بھی جو آپ کے ساتھ رہے گا، ایک حکم جو آپ کی نسلوں میں ہمیشہ کے لیے ہوگا: جیسے آپ {ہیں}، ویسے ہی اجنبی خداوند کے سامنے ہوگا۔\n16۔ ایک قانون اور ایک طریقہ تمہارے لیے ہوگا، اور اس اجنبی کے لیے جو تمہارے ساتھ ٹھہرے گا۔\n17۔ اور خداوند نے موسیٰ سے کہا،\n18۔ بنی اسرائیل سے بات کرو، اور ان سے کہو، جب تم اس زمین میں آؤ جہاں میں تمہیں لایا ہوں،\n19۔ پھر یہ ہوگا کہ جب تم زمین کی روٹی کھاؤ گے، تو خداوند کے لیے ایک نذرانہ پیش کرو گے۔\n20۔ تم اپنے پہلے آٹے کا کیک پیش کرو گے {ایک اوپر کی قربانی} کے لیے: جیسے تم تھریشنگ فلور کی نذرانہ کرتے ہو، ویسے ہی اسے اٹھاؤ گے۔\n21۔ اپنے پہلے پیسے میں سے تم اپنی نسلوں میں خداوند کو قربان کرو گے۔\n22۔ اور اگر تم نے غلطی کی اور ان تمام احکامات کی پابندی نہیں کی جو خداوند نے موسیٰ سے کہے ہیں،\n23. {حتیٰ} وہ سب کچھ جو خداوند نے موسیٰ کے ہاتھوں تمہیں حکم دیا، اس دن سے جب خداوند نے {موسیٰ} کا حکم دیا، اور تمہاری نسلوں کے درمیان؛\n24۔ تو اگر یہ لاعلمی سے جماعت کی اطلاع کے بغیر کیا جائے، تو تمام جماعت ایک نوجوان بیل کو جلانے کی قربانی کے طور پر پیش کرے گی، جو خداوند کے لیے میٹھا ذائقہ ہے، اس کے گوشت کی قربانی کے ساتھ، اور اس کی شراب کی قربانی، آداب کے مطابق، اور بکریوں کا ایک بچہ گناہ کی قربانی کے طور پر پیش کرے گا۔ {بغیر...: عبرانی۔ آنکھوں سے} {طریقہ: یا، آرڈیننس}\n25۔ اور پادری بنی اسرائیل کی تمام جماعت کے لیے کفارہ کرے گا، اور انہیں معاف کر دیا جائے گا؛ کیونکہ یہ جہالت ہے: اور وہ اپنی قربانی پیش کریں گے، جو آگ سے دی گئی قربانی ہے خداوند کے لیے، اور اپنی گناہ کی قربانی خداوند کے سامنے، اپنی لاعلمی کی وجہ سے:\n26۔ اور بنی اسرائیل کی تمام جماعت اور ان کے درمیان رہنے والے اجنبی کو معاف کیا جائے گا؛ دیکھنا کہ سب لوگ {لاعلم} ہیں۔\n27۔ اور اگر کوئی شخص لاعلمی میں گناہ کرے تو وہ پہلے سال کی مادہ بکری کو گناہ کی قربانی کے طور پر لائے گا۔\n28۔ اور پادری اس روح کے لیے کفارہ کرے گا جو لاعلمی میں گناہ کرتی ہے، جب وہ خداوند کے سامنے لاعلمی سے گناہ کرتی ہے، تاکہ اس کے لیے کفارہ ہو؛ اور اسے معاف کر دیا جائے گا۔\n29۔ جو لاعلمی سے گناہ کرتا ہے اس کے لیے تمہارے لیے ایک قانون ہوگا، {دونوں} اس کے لیے جو بنی اسرائیل میں پیدا ہوتا ہے، اور اس اجنبی کے لیے جو ان کے درمیان رہتا ہے۔ {sinneth: عبرانی۔ doth}\n30۔ لیکن جو روح خود اعتمادی سے کرتی ہے، چاہے وہ زمین میں پیدا ہوئی ہو یا اجنبی، وہی خداوند کو ملامت کرتی ہے؛ اور اس روح کو اس کے لوگوں میں سے کاٹ دیا جائے گا۔ {بے ساختہ انداز میں: عبرانی۔ اونچی ہاتھ سے}\n31۔ کیونکہ اس نے خداوند کے کلام کو حقیر سمجھا اور اپنا حکم توڑا، اس روح کو مکمل طور پر کاٹ دیا جائے گا؛ اس کی گناہ {اس پر ہوگی}۔\n32۔ اور جب بنی اسرائیل صحرا میں تھے، تو انہوں نے ایک آدمی کو پایا جو سبت کے دن لکڑیاں جمع کرتا تھا۔\n33۔ اور جنہوں نے اسے لاٹھیاں جمع کرتے ہوئے پایا، وہ اسے موسیٰ اور ہارون اور تمام جماعت کے پاس لے آئے۔\n34۔ اور انہوں نے اسے وارڈ میں رکھا کیونکہ یہ اعلان نہیں کیا گیا کہ اس کے ساتھ کیا ہونا چاہیے۔\n35۔ اور خداوند نے موسیٰ سے فرمایا، وہ آدمی ضرور قتل کیا جائے گا: تمام جماعت اسے بغیر کیمپ کے پتھر مارے گی۔\n36۔ اور تمام جماعت اسے کیمپ سے باہر لے آئی، اسے پتھر مارے، اور وہ مر گیا؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n37۔ اور خداوند نے موسیٰ سے کہا،\n38۔ بنی اسرائیل سے بات کرو اور انہیں حکم دو کہ وہ اپنی نسلوں تک اپنے لباس کی سرحدوں میں ان کے کنارے بنائیں، اور کناروں کے کنارے پر نیلے رنگ کی پسلی باندھ دیں:\n39۔ اور یہ تمہارے لیے ایک کنارے پر ہوگا، تاکہ تم اسے دیکھ سکو، اور خداوند کے تمام احکامات یاد رکھو، اور انہیں پورا کرو؛ اور تم اپنے دل اور آنکھوں کی تلاش نہ کرو، جس کے بعد تم طوائف میں جاتے ہو:\n40۔ تاکہ تم یاد رکھو، میرے تمام احکامات پر عمل کرو، اور اپنے خدا کے لیے پاک رہو۔\n41. میں {ہوں} خداوند تمہارا خدا، جس نے تمہیں مصر کی سرزمین سے نکالا، تاکہ وہ تمہارا خدا بن سکے: میں {ہوں} خداوند تمہارا خدا۔","1۔ اب قارح، جو ایزہر کا بیٹا تھا، کوہات کا بیٹا، لاوی کا بیٹا، اور داتھان اور ابیرام، جو ایلیاب کے بیٹے تھے، اور اون، پیلتھ کا بیٹا، روبن کے بیٹے، نے {مرد} لیے:\n2۔ اور وہ موسیٰ کے سامنے، بنی اسرائیل کے کچھ شہزادوں کے ساتھ، جماعت کے دو سو پچاس شہزادے، جو جماعت میں مشہور اور مشہور لوگ تھے، کھڑے ہوئے:\n3۔ اور وہ موسیٰ اور ہارون کے خلاف جمع ہو گئے، اور ان سے کہا، {تم اپنے اوپر بہت زیادہ بوجھ اٹھاتے ہو، کیونکہ تمام جماعت مقدس ہے، ہر ایک، اور خداوند ان میں سے ہے: تو پھر تم خود کو خداوند کی جماعت سے بلند کیوں کرتے ہو؟ {تم لیتے ہو...: عبوری۔ یہ آپ کے لیے بہت کچھ ہے}\n4۔ اور جب موسیٰ نے سنا تو وہ اپنے چہرے کے بل گر پڑا:\n5۔ اور اس نے قارح اور اس کے تمام ساتھیوں سے کہا، کل بھی خداوند دکھائے گا کہ کون اس کا ہے، اور کون مقدس ہے؛ اور {اسے} کو اپنے قریب لے آئے گا: حتیٰ کہ {جسے اس نے چنے} کو بھی اپنے قریب لے آئے گا۔\n6. یہ کرتا ہے؛ لو، اپنے بخور کرنے والے، کورہ، اور اس کے تمام ساتھیوں کو؛\n7۔ اور اس میں آگ ڈال دو، اور کل خداوند کے سامنے ان میں لوبان ڈال دو، اور وہ شخص جسے خداوند چنے گا، وہ مقدس ہوگا: اے لاوی کے بیٹو، تم اپنے اوپر بہت زیادہ بوجھ اٹھاتے ہو۔\n8۔ اور موسیٰ نے قارح سے کہا، سنو، میں تم سے دعا گو ہوں، اے لاوی کے بیٹو:\n9. {کیا یہ آپ کے لیے ایک چھوٹی بات نہیں لگتا} کہ اسرائیل کے خدا نے آپ کو اسرائیل کی جماعت سے جدا کیا ہے، تاکہ آپ کو اپنے قریب لے آئے تاکہ آپ خداوند کے خیمہ کی خدمت کریں، اور جماعت کے سامنے کھڑے ہو کر ان کی خدمت کریں؟\n10۔ اور اس نے تمہیں اپنے قریب لایا ہے، اور تمہارے تمام بھائیوں کو لاوی کے بیٹوں کو بھی اپنے ساتھ لے آیا ہے، اور کیا تم بھی پادری بننے کی کوشش کرتے ہو؟\n11۔ کس وجہ سے {دونوں} تم اور تمہاری جماعت {اکٹھ} ہو کر خداوند کے خلاف جمع ہوئے: اور ہارون کیا ہے جو تم اس کے خلاف بڑبڑاتے ہو؟\n12۔ اور موسیٰ نے داتھان اور ابیرام، ایلیاب کے بیٹوں کو بلایا، اور کہا، ہم اوپر نہیں آئیں گے:\n13. کیا یہ چھوٹی بات ہے کہ تم نے ہمیں دودھ اور شہد سے بہنے والی زمین سے نکالا ہے، تاکہ ہمیں ویرانے میں مار ڈالو، سوائے اس کے کہ تم خود کو ہم پر مکمل طور پر شہزادہ بنا لو؟\n14۔ مزید یہ کہ تم نے ہمیں ایسی زمین میں نہیں لایا جو دودھ اور شہد سے بہتی ہے، اور نہ ہی ہمیں کھیتوں اور انگور کے باغات کی میراث دی: کیا تم ان لوگوں کی آنکھیں بند کرو گے؟ ہم اوپر نہیں آئیں گے۔ {put...: عبدی۔ بور آؤٹ}\n15۔ اور موسیٰ بہت غصے میں آیا، اور خداوند سے کہا، ان کی قربانی کی عزت نہ کرو: میں نے ان سے ایک بھی گدھا نہیں لیا، نہ ہی کسی کو نقصان پہنچایا۔\n16۔ اور موسیٰ نے قارح سے کہا، تم اور اپنی ساری جماعت خداوند کے سامنے بنو، تم، اور وہ اور ہارون، کل آؤ:\n17۔ اور ہر آدمی کو اس کا بخور لے آؤ، اس میں لوبان ڈالو، اور ہر شخص کو اس کا بخور دو سو پچاس کے لیے خداوند کے سامنے لے آؤ؛ تم بھی، اور ہارون، تم میں سے ہر ایک اس کا بخور کرنے والا۔\n18۔ اور انہوں نے ہر آدمی کو اس کا بخور پہنچایا، اس میں آگ لگا دی، اس پر لوبان رکھا، اور جماعت کے خیمے کے دروازے پر موسیٰ اور ہارون کے ساتھ کھڑے ہو گئے۔\n19۔ اور قارح نے سب جماعت کو ان کے خلاف جماعت کے خیمہ کے دروازے پر جمع کر دیا: اور خداوند کی جلال سب جماعت پر ظاہر ہوئی۔\n20۔ اور خداوند نے موسیٰ اور ہارون سے کہا،\n21۔ اس جماعت سے الگ ہو جاؤ، تاکہ میں انہیں ایک لمحے میں پڑھ سکوں۔\n22۔ اور وہ اپنے چہروں کے بل گر پڑے اور کہا، اے خدا، جو تمام انسانوں کی روحوں کا خدا ہے، کیا ایک آدمی گناہ کرے گا اور کیا تم پوری جماعت پر غصہ کرو گے؟\n23۔ اور خداوند نے موسیٰ سے کہا،\n24۔ جماعت سے بات کرو، کہو، کورح، داتھان اور ابیریم کے خیمہ گاہ سے اٹھ جاؤ۔\n25۔ اور موسیٰ اٹھا اور داتھان اور ابیرام کے پاس چلا گیا؛ اور اسرائیل کے بزرگ اس کے پیچھے آئے۔\n26۔ اور اس نے جماعت سے کہا، \"میں تم سے درخواست کرتا ہوں کہ ان بدکاروں کے خیموں سے نکل جاؤ، اور ان کے خیموں کو کچھ نہ چھوؤ، ورنہ تم ان کے تمام گناہوں میں کھو جاؤ گے۔\n27۔ تو وہ کورح، داتھان اور ابیریم کے خیمے سے ہر طرف سے نکلے، اور داتھان اور ابیرام باہر آئے، اپنے خیموں کے دروازے پر کھڑے ہو گئے، ان کی بیویاں، ان کے بیٹے اور اپنے چھوٹے بچے بھی۔\n28۔ اور موسیٰ نے کہا، اس طرح تم جان لو گے کہ خداوند نے مجھے یہ سب کام کرنے کے لیے بھیجا ہے؛ کیونکہ {میں نے} اپنے ذہن میں {یہ نہیں کیے}۔\n29۔ اگر یہ مرد تمام مردوں کی مشترکہ موت کے بعد فوت ہو جائیں، یا اگر تمام مردوں کی ملاقات کے بعد ان سے ملاقات ہو؛ {تو} خداوند نے مجھے نہیں بھیجا۔ {عام...: عبرانی۔ ہر انسان کی طرح}\n30۔ لیکن اگر خداوند کوئی نئی چیز بنائے، اور زمین اپنا منہ کھولے، اور انہیں نگل لے، اور وہ جلدی سے گڑھے میں چلے جائیں؛ پھر تم سمجھو گے کہ ان لوگوں نے خداوند کو مشتعل کیا ہے۔ {make...: عبرانی۔ ایک مخلوق تخلیق کریں}\n31۔ اور ایسا ہوا، جب اس نے یہ سب باتیں ختم کر دیں، کہ زمین کا ٹکڑا جو {تھا} ان کے نیچے سے جدا ہو گیا:\n32۔ اور زمین نے اپنا منہ کھولا، انہیں نگل لیا، ان کے گھروں کو، اور وہ تمام لوگ جو قارح کے ساتھ تعلق رکھتے تھے، اور ان کے تمام مال کو نگل لیا۔\n33۔ وہ اور ان کے ساتھ جو کچھ بھی تھا، زندہ گڑھے میں گر گئے، اور زمین ان پر بند ہو گئی: اور وہ جماعت میں سے ہلاک ہو گئے۔\n34۔ اور ان کے ارد گرد موجود تمام اسرائیل ان کی آواز پر بھاگ گئے: کیونکہ انہوں نے کہا، کہیں زمین ہمیں نگل نہ جائے۔\n35۔ اور خداوند کی طرف سے آگ نکلی، اور دو سو پچاس آدمیوں کو جلا دیا جو لوبان پیش کر رہے تھے۔\n36۔ اور خداوند نے موسیٰ سے کہا،\n37۔ ہارون کاهن کے بیٹے الیعازر سے بات کرو کہ وہ جلتی ہوئی آگ سے بخور اٹھا کر آگ بکھیر دے؛ کیونکہ وہ مقدس ہیں۔\n38۔ ان گناہ گاروں کے بخور کرنے والے اپنی روحوں کے خلاف، انہیں چوڑے تختوں کے لیے قربان گاہ کی چادر بنانے دیں: کیونکہ انہوں نے انہیں خداوند کے سامنے پیش کیا، اس لیے وہ مقدس ہیں: اور یہ بنی اسرائیل کے لیے ایک نشانی ہوں گے۔\n39۔ اور الیعزر کاهن نے وہ بخور لے لیے جو جلائے گئے لوگوں نے پیش کیے تھے؛ اور انہیں قربان گاہ کی تہہ کے لیے چوڑا {پلیٹیں} بنائے گئے:\n40۔ {بنی اسرائیل کی یادگار} ہونا، تاکہ کوئی اجنبی جو {ہارون کی نسل سے نہیں} خداوند کے سامنے خوشبو پیش کرنے کے لیے قریب نہ آئے؛ تاکہ وہ قارح کی طرح نہ ہو، اور اس کی صحبت ہو: جیسا کہ خداوند نے موسیٰ کے ہاتھ سے اسے فرمایا۔\n41۔ لیکن کل بنی اسرائیل کی تمام جماعت نے موسیٰ اور ہارون کے خلاف سرگوشیاں کیں، کہنے لگا، تم نے خداوند کے لوگوں کو مار ڈالا۔\n42۔ اور جب جماعت موسیٰ اور ہارون کے خلاف جمع ہوئی، تو انہوں نے جماعت کے خیمے کی طرف دیکھا: اور دیکھتے ہی بادل نے اسے ڈھانپ لیا، اور خداوند کی شان ظاہر ہوئی۔\n43۔ اور موسیٰ اور ہارون جماعت کے خیمے کے سامنے آئے۔\n44۔ اور خداوند نے موسیٰ سے کہا،\n45۔ تمہیں اس جماعت میں سے اٹھاؤ، تاکہ میں انہیں ایک لمحے میں کھا سکوں۔ اور وہ اپنے چہروں کے بل گر گئے۔\n46۔ اور موسیٰ نے ہارون سے کہا، ایک مجارہ لے آؤ، اور اس میں قربان گاہ سے آگ لگا دو، اور لوبان لگا دو، اور جلدی سے جماعت کے پاس جا کر ان کے لیے کفارہ دو، کیونکہ خداوند کی طرف سے غصہ ختم ہو چکا ہے؛ وبا شروع ہو چکی ہے۔\n47۔ اور ہارون نے موسیٰ کے حکم کے مطابق جماعت کے درمیان دوڑ لگا دی؛ اور یوں ہی لوگوں میں وبا شروع ہو گئی: اور اس نے لوبان لگایا، اور لوگوں کے لیے کفارہ کیا۔\n48۔ اور وہ مردوں اور زندوں کے درمیان کھڑا تھا؛ اور طاعون کو روک دیا گیا۔\n49۔ اب جو لوگ طاعون میں مرے، وہ چودہ ہزار سات سو تھے، ان کے علاوہ جو قارح کے معاملے پر مرے۔\n50۔ اور ہارون موسیٰ کے پاس جماعت کے خیمہ کے دروازے پر واپس آیا: اور وبا روک دی گئی۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل سے بات کرو، اور ان میں سے ہر ایک سے ان کے آباؤ اجداد کے گھرانے کے مطابق ایک لاٹھی لے لو، اور ان کے تمام شہزادوں کا ان کے باپ کے گھر کے بارہ لاٹھیوں کے مطابق: ہر آدمی کا نام اس کی چھڑی پر لکھو۔\n3۔ اور تم لاوی کی چھڑی پر ہارون کا نام لکھو گے: کیونکہ ایک چھڑی ان کے آباؤ اجداد کے خاندان کے سربراہ کے لیے ہوگی۔\n4۔ اور تم انہیں جماعت کے خیمہ میں گواہی کے سامنے رکھو، جہاں میں تم سے ملوں گا۔\n5۔ اور یہ ہوگا کہ اس آدمی کی چھڑی، جسے میں چنوں گا، کھلے گا: اور میں اپنے آپ سے بنی اسرائیل کی سرگوشیوں کو روک دوں گا، جن سے وہ تمہارے خلاف سرگوشیاں کرتے ہیں۔\n6۔ اور موسیٰ نے بنی اسرائیل سے کہا، اور ان کے ہر شہزادے نے اسے ایک ایک لاٹھی دی، ہر شہزادے کے لیے، اپنے باپ کے گھروں کے مطابق، بارہ لاٹھیاں بھی، اور ہارون کی چھڑی ان کی چھڑیوں میں تھی۔ {ایک چھڑی...: عبرانی۔ ایک شہزادے کے لیے چھڑی، ایک شہزادے کے لیے چھڑی}\n7۔ اور موسیٰ نے گواہی کے خیمے میں خداوند کے سامنے چھڑیاں رکھ دیں۔\n8۔ اور ایسا ہوا کہ کل موسیٰ گواہی کے خیمے میں گیا؛ اور دیکھو، ہارون کی چھڑی لیوی خاندان کے لیے اگ گئی، اس نے کلیاں نکالی، پھول کھلے اور بادام پیدا کیے۔\n9۔ اور موسیٰ نے خداوند کے سامنے تمام چھڑیاں بنی اسرائیل کے تمام لوگوں کے لیے نکالیں، اور انہوں نے دیکھا اور ہر آدمی کو اس کی لاٹھی لے لی۔\n10۔ اور خداوند نے موسیٰ سے کہا، 'ہارون کی چھڑی دوبارہ گواہی کے سامنے لے آؤ، تاکہ اسے باغیوں کے خلاف نشان کے طور پر رکھا جائے؛ اور تم ان کی سرگوشیاں مجھ سے دور کر دو گے، تاکہ وہ نہ مریں۔ {باغی: عبرانی۔ بغاوت کے بچے}\n11۔ اور موسیٰ نے ایسا ہی کیا: جیسا خداوند نے حکم دیا، ویسے ہی موسیٰ نے کیا۔\n12۔ اور بنی اسرائیل نے موسیٰ سے کہا، دیکھو، ہم مرتے ہیں، ہم سب ہلاک ہوتے ہیں۔\n13۔ جو بھی خداوند کے خیمے کے قریب آئے گا، وہ مر جائے گا: کیا ہم مرنے سے محروم ہو جائیں گے؟","1۔ اور خداوند نے ہارون سے کہا، 'تو اور تمہارے بیٹے اور تمہارے باپ کا گھرانہ، جو تمہارے ساتھ ہوں گے، مقدس مقام کی بدکاری اٹھائیں گے: اور تم اور تمہارے بیٹے تمہارے ساتھ اپنی پادریت کی بدکاری برداشت کریں گے۔\n2۔ اور تمہارے بھائی بھی لاوی قبیلے سے، جو تمہارے باپ کے قبیلے سے ہیں، تمہیں اپنے ساتھ لے آؤ، تاکہ وہ تمہارے ساتھ شامل ہو جائیں اور تمہاری خدمت کریں، لیکن تم اور تمہارے بیٹے گواہی کے خیمے کے سامنے خدمت کریں گے۔\n3۔ اور وہ تمہاری ذمہ داری اور تمام خیمہ جات کی حفاظت کریں گے: صرف وہ مقدس مقام اور قربان گاہ کے برتنوں کے قریب نہیں آئیں گے، تاکہ نہ وہ اور نہ تم مر جاؤ۔\n4۔ اور وہ آپ کے ساتھ جڑے ہوں گے، اور جماعت کے خیمے کی حفاظت کریں گے، کیونکہ خیمہ کی تمام خدمات ہوں گی: اور کوئی اجنبی آپ کے قریب نہیں آئے گا۔\n5۔ اور تم مقدس مقام اور قربان گاہ کی ذمہ داری سنبھالو گے: تاکہ بنی اسرائیل پر مزید غصہ نہ ہو۔\n6۔ اور میں، دیکھو، میں نے تمہارے بھائیوں لاوی کو بنی اسرائیل میں سے لیا ہے: وہ تمہیں خداوند کے لیے تحفہ کے طور پر دیے گئے ہیں، تاکہ جماعت کے خیمے کی خدمت کرو۔\n7۔ اس لیے تم اور تمہارے بیٹے اپنے پادری کا عہدہ قربان گاہ کی ہر چیز اور پردے کے اندر رکھو گے؛ اور تم خدمت کرو گے: میں نے تمہارا پادری کا عہدہ تمہیں تحفے کے طور پر دیا ہے: اور جو اجنبی قریب آئے گا اسے مار دیا جائے گا۔\n8۔ اور خداوند نے ہارون سے کہا، دیکھو، میں نے بھی تمہیں بنی اسرائیل کی تمام مقدس چیزوں کی قربانیوں کی ذمہ داری دی ہے؛ میں نے انہیں تمہیں مسح کی وجہ سے دیا ہے، اور تمہارے بیٹوں کو ہمیشہ کے لیے ایک فرمان کے ذریعے دیا ہے۔\n9۔ یہ تمہاری سب سے مقدس چیزوں میں سے ہوگی، {آگ سے محفوظ}: ان کی ہر قربانی، ان کی ہر گوشت کی قربانی، ان کی ہر گناہ کی قربانی، اور ان کی ہر قربانی جو وہ مجھے پیش کریں گے، وہ تمہارے اور تمہارے بیٹوں کے لیے سب سے مقدس ہوگی۔\n10۔ سب سے مقدس جگہ پر تم اسے کھاؤ گے؛ ہر مرد اسے کھائے گا: یہ تمہارے لیے مقدس ہوگا۔\n11. اور یہ {ہے} تمہارا؛ ان کے تحفے کی قربانی، بنی اسرائیل کی تمام نذرانے کے ساتھ: میں نے یہ سب تمہیں اور تمہارے بیٹوں اور تمہاری بیٹیوں کو ہمیشہ کے لیے ایک مجسمے کے ذریعے دیا ہے: جو بھی تمہارے گھر میں پاک ہے وہ اس میں سے کھائے گا۔\n12۔ تیل کی بہترین، شراب اور گندم کی سب سے اچھی، ان کے پہلے پھل جو وہ خداوند کو پیش کریں گے، میں نے تمہیں دی ہیں۔ {بہترین: عبرانی۔ موٹا}\n13۔ {اور} جو زمین میں سب سے پہلے پک جائے گا، جسے وہ خداوند کے پاس لائیں گے، وہ تمہارا ہوگا؛ جو بھی تمہارے گھر میں پاک ہے، وہ اسے کھائے گا۔\n14۔ اسرائیل میں جو کچھ وقف کیا جائے گا وہ تمہارا ہوگا۔\n15۔ جو کچھ بھی جسم میں میٹرکس کھولتا ہے، جو وہ خداوند کے سامنے لایا جاتا ہے، {چاہے وہ انسانوں کی ہو یا جانوروں کی}، وہ تمہاری ہوگی: پھر بھی انسان کا پہلا بچہ ضرور نجات دوں گا، اور ناپاک جانوروں کا پہلا بچہ تو نجات دے گا۔\n16۔ اور جو ایک ماہ کی عمر سے نجات پانے والے ہیں، انہیں تم اپنے اندازے کے مطابق پانچ شیکل کے پیسے کے بدلے، مقدس مقام کے شیکل کے بعد، جو بیس گرہ کے برابر ہے، چھڑا دو گے۔\n17۔ لیکن گائے کا پہلا بیٹا، یا بھیڑ کا اولاد، یا بکری کا اولاد، تم اسے نجات نہیں دے سکتے؛ وہ مقدس ہیں: تو ان کا خون قربان گاہ پر چھڑکو گے، اور ان کی چربی جلاؤ گے، کیونکہ یہ آگ سے دی گئی قربانی ہے، خداوند کے لیے میٹھا ذائقہ کے طور پر۔\n18۔ اور ان کا جسم تمہارا ہوگا، جیسے لہراتا ہوا سینہ اور دایاں کندھا تمہارا ہے۔\n19۔ وہ تمام مقدس قربانیاں، جو بنی اسرائیل خداوند کو پیش کرتے ہیں، میں نے تمہیں اور تمہارے بیٹوں اور بیٹیوں کو ہمیشہ کے لیے ایک حکم کے ذریعے دیا ہے: یہ ہمیشہ کے لیے خداوند کے سامنے نمک کا عہد ہے، جو تمہارے اور تمہاری نسل کے لیے ہمیشہ رہے گا۔\n20۔ اور خداوند نے ہارون سے کہا، نہ تو ان کی سرزمین میں وراثت رکھو گے، نہ ہی ان میں تمہارا حصہ ہوگا: میں تمہارا حصہ ہوں اور تیرا وراثت بنی اسرائیل میں ہوں۔\n21۔ اور دیکھو، میں نے لاوی کے بچوں کو اسرائیل میں تمام دسواں حصہ وراثت کے طور پر دیا ہے، ان کی خدمت کے بدلے جس کی وہ خدمت کرتے ہیں، {حتیٰ کہ} جماعت کے خیمہ کی خدمت بھی۔\n22۔ اب سے بنی اسرائیل کو جماعت کے خیمے کے قریب بھی نہیں جانا چاہیے، ورنہ وہ گناہ اٹھائیں گے اور مر جائیں گے۔ {اور مر گئے: عبرانی۔ مرنے کے لیے}\n23۔ لیکن لاوی جماعت کے خیمے کی خدمت کریں گے، اور وہ اپنی گناہوں کو برداشت کریں گے: یہ تمہاری نسلوں کے لیے ہمیشہ کے لیے ایک قانون رہے گا کہ بنی اسرائیل میں انہیں کوئی وراثت نہیں ملے گی۔\n24۔ لیکن بنی اسرائیل کے عشر، جو وہ خداوند کے لیے قربان کے طور پر پیش کرتے ہیں، میں نے لاویوں کو وراثت میں دینے کے لیے دیا ہے: اسی لیے میں نے ان سے کہا ہے، بنی اسرائیل میں انہیں کوئی وراثت نہیں ملے گی۔\n25۔ اور خداوند نے موسیٰ سے کہا،\n26۔ یوں لاویوں سے بات کرو، اور انہیں کہو، جب تم بنی اسرائیل سے وہ عشر لے لو جو میں نے تمہیں ان سے تمہاری وراثت کے طور پر دیے ہیں، تو تم اس میں سے ایک نذرانہ خدا کے لیے پیش کرو گے، {حتیٰ کہ} عشر کا دسواں حصہ۔\n27. اور یہ آپ کی نذرانہ آپ کے سامنے شمار کی جائے گی، جیسے یہ تھریشنگ فلور کا اناج ہو، اور شراب کے منہ کی بھرپور۔\n28۔ اسی طرح تم اپنے تمام عشروں کی جو تم بنی اسرائیل سے حاصل کرتے ہو، خداوند کے سامنے ایک قربانی پیش کرو؛ اور تم اس میں سے خداوند کی نذرانہ ہارون کاہن کو پیش کرو گے۔\n29۔ اپنی تمام نعمتوں میں سے تم خداوند کی ہر نذرانہ پیش کرو گے، اس کی تمام بہترین چیزوں کا، حتیٰ کہ اس کا مقدس حصہ بھی۔ {بہترین: عبرانی۔ موٹا}\n30۔ لہٰذا تم انہیں کہو گے، جب تم اس سے بہترین چیز نکال لو، تو اسے لاویوں کے لیے تھریشنگ فلور کی بڑھوتری اور شراب کے ڈبے کی بڑھوتری کے طور پر شمار کیا جائے گا۔ {بہترین: عبرانی۔ موٹا}\n31۔ اور تم اسے ہر جگہ کھاؤ گے، تم اور تمہارے خاندان، کیونکہ یہ تمہاری عبادت گاہ میں تمہاری خدمت کا بدلہ ہے۔\n32۔ اور جب تک تم اس سے بہترین چیز نکال لو، تم اس کی وجہ سے کوئی گناہ نہیں اٹھاؤ گے: نہ تم بنی اسرائیل کی مقدس چیزوں کو آلودہ کرو گے، ورنہ تم مر جاؤ گے۔","1۔ اور خداوند نے موسیٰ اور ہارون سے کہا،\n2۔ یہ وہ قانون ہے جو خداوند نے حکم دیا ہے، کہتا ہے: بنی اسرائیل سے بات کرو کہ وہ تمہارے لیے ایک بے داغ سرخ گائے لاؤ، جس میں کوئی داغ نہ ہو، اور جس پر کبھی جڑی نہ ہو:\n3۔ اور تم اسے الیعزر کاہن کے حوالے کرو گے، تاکہ وہ اسے کیمپ کے بغیر باہر لے آئے، اور {ایک} اسے اپنے چہرے کے سامنے قتل کر دے:\n4۔ اور الیعازر کاہن اپنی انگلی سے اس کا خون لے گا، اور جماعت کے خیمے کے سامنے سات بار اس کا خون چھڑکائے گا:\n5. اور {ایک} اس کی نظر میں گائے کو جلا دے گا؛ اس کی جلد، اس کا گوشت، اور اس کا خون، اس کے گوبر کے ساتھ، وہ جلائے گا:\n6۔ اور پادری دیودار کی لکڑی، ہیسپ، اور سرخ رنگ لے کر گائے کے جلانے کے بیچ میں پھینک دے گا۔\n7۔ پھر پادری اپنے کپڑے دھوئے گا، اور اپنے گوشت کو پانی میں نہلائے گا، اور پھر وہ کیمپ میں آئے گا، اور پادری شام تک ناپاک ہوگا۔\n8۔ اور جو اسے جلائے گا وہ اپنے کپڑے پانی میں دھوئے گا، اور اپنے گوشت کو پانی میں نہلائے، اور وہ ناپاک رہے گا جب تک کہ وہ برابر نہ ہو۔\n9۔ اور ایک شخص {جو پاک ہو} گائے کی راکھ جمع کرے گا، اور اسے کیمپ کے بغیر صاف جگہ پر رکھے گا، اور اسے بنی اسرائیل کی جماعت کے لیے جدائی کا پانی کے طور پر رکھا جائے گا: یہ گناہ کی تطہیر ہے۔\n10۔ اور جو گائے کی راکھ جمع کرے گا، وہ اپنے کپڑے دھوئے گا، اور ناپاک ہو جائے گا جب تک کہ وہ عدالت نہ ہو جائے: اور یہ بنی اسرائیل اور ان کے درمیان رہنے والے اجنبی کے لیے ہمیشہ کے لیے ایک حکم ہوگا۔\n11۔ جو شخص کسی کے مردہ جسم کو چھوئے گا وہ سات دن ناپاک ہوگا۔ {آدمی: عبرانی۔ انسان کی روح}\n12۔ وہ تیسرے دن خود کو اس سے پاک کرے گا، اور ساتویں دن پاک ہوگا، لیکن اگر وہ تیسرے دن خود کو پاک نہ کرے تو ساتویں دن وہ پاک نہیں ہوگا۔\n13۔ جو بھی کسی مردہ انسان کے جسم کو چھوئے اور خود کو پاک نہ کرے، وہ خداوند کے خیمے کو ناپاک کرتا ہے؛ اور وہ روح اسرائیل سے کٹ جائے گی: کیونکہ جدائی کا پانی اس پر نہیں چھڑکا، وہ ناپاک ہو جائے گا؛ اس کی ناپاکی ابھی بھی اس پر ہے۔\n14. یہ {ہے} قانون ہے، جب کوئی آدمی خیمے میں مر جائے: جو بھی خیمے میں آئے گا، اور جو کچھ خیمے میں ہے، وہ سات دن کے لیے ناپاک ہوگا۔\n15۔ اور ہر کھلا برتن جس پر کوئی پردہ نہ ہو، وہ ناپاک ہے۔\n16۔ اور جو بھی کھلے میدانوں میں تلوار سے مارے جانے والے شخص کو، یا مردہ جسم، یا انسان کی ہڈی، یا قبر سے چھوئے، وہ سات دن ناپاک ہوگا۔\n17۔ اور ناپاک شخص کے لیے وہ گناہ کے لیے جلے ہوئے گائے کی راکھ سے نکالیں گے، اور اس میں بہتا ہوا پانی ایک برتن میں ڈالا جائے گا: {رکھ: عبرانی۔ dust} {دوڑتا ہوا...: عبرانی زندہ پانی دیا جائے گا}\n18۔ اور ایک پاک شخص ہیسپ لے کر پانی میں ڈبوئے گا، اور خیمے پر، تمام برتنوں پر، وہاں موجود لوگوں پر، اور جس نے ہڈی، یا مقتول، مردہ یا قبر کو چھوا ہے، اس پر چھڑک دے گا:\n19۔ اور صاف ستھرا شخص تیسرے دن اور ساتویں دن ناپاک پر چھڑکائے گا: اور ساتویں دن وہ خود کو پاک کرے گا، اپنے کپڑے دھوئے گا، پانی میں نہائے گا، اور صاف ہوگا۔\n20۔ لیکن جو شخص ناپاک ہوگا اور خود کو پاک نہیں کرے گا، وہ روح جماعت میں سے کاٹ دی جائے گی، کیونکہ اس نے خداوند کے مقدس مقام کو ناپاک کیا ہے: جدائی کا پانی اس پر نہیں چھڑکا؛ وہ ناپاک ہے۔\n21۔ اور یہ ان کے لیے ایک مستقل قانون ہوگا کہ جو بھی جدائی کا پانی چھڑکے، وہ اپنے کپڑے دھوئے؛ اور جو جدائی کے پانی کو چھوئے گا وہ برابر تک ناپاک ہوگا۔\n22۔ اور جو کچھ بھی ناپاک {شخص} چھوئے گا، وہ ناپاک ہوگا؛ اور جو روح اسے چھوئے گی وہ برابر تک ناپاک رہے گی۔","1۔ پھر بنی اسرائیل، حتیٰ کہ پوری جماعت بھی، پہلے مہینے میں زین کے صحرا میں آئے: اور لوگ قادیش میں بسے؛ اور مریم وہیں وفات پا گئیں اور وہیں دفن ہوئیں۔\n2۔ اور جماعت کے لیے پانی نہیں تھا: اور وہ موسیٰ اور ہارون کے خلاف جمع ہو گئے۔\n3۔ اور لوگوں نے موسیٰ کے ساتھ بات کی، اور کہا، کاش ہم مر جاتے جب ہمارے بھائی خداوند کے سامنے مرے تھے!\n4۔ اور تم نے خداوند کی جماعت کو اس صحرا میں کیوں لایا تاکہ ہم اور ہمارے مویشی وہاں مر جائیں؟\n5۔ اور تم نے ہمیں مصر سے کیوں نکالا، تاکہ ہمیں اس برے مقام پر لے آؤں؟ یہ نہ بیج، نہ انجیر، نہ بیلوں کی، نہ انار کی جگہ ہے؛ نہ ہی پینے کے لیے کوئی پانی ہے۔\n6۔ اور موسیٰ اور ہارون اجتماع کی موجودگی سے جماعت کے خیمے کے دروازے تک گئے، اور وہ اپنے چہروں پر گر گئے، اور خداوند کی شان ان پر ظاہر ہوئی۔\n7۔ اور خداوند نے موسیٰ سے کہا،\n8۔ چھڑی پکڑو، اور سب کو اکٹھا کرو، تم اور ہارون تمہارا بھائی، اور ان کی آنکھوں کے سامنے چٹان سے بات کرو؛ اور وہ اس کا پانی دے گا، اور تم ان کے لیے چٹان سے پانی نکالو گے، اور تم جماعت اور ان کے جانوروں کو پانی دو گے۔\n9۔ اور موسیٰ نے خداوند کے سامنے لاٹھی لے لی، جیسا کہ اس نے اسے حکم دیا تھا۔\n10۔ اور موسیٰ اور ہارون نے جماعت کو چٹان کے سامنے جمع کیا، اور اس نے ان سے کہا، اے باغیوں، اب سنو؛ کیا ہمیں اس پتھر سے تمہارے لیے پانی لانا ہوگا؟\n11۔ اور موسیٰ نے اپنا ہاتھ اٹھایا، اور اپنی چھڑی سے پتھر کو دو بار مارا، اور پانی بھرپور نکلا، اور جماعت نے پانی پیا، اور ان کے جانور بھی۔\n12۔ اور خداوند نے موسیٰ اور ہارون سے کہا، کیونکہ تم نے مجھ پر یقین نہیں کیا، تاکہ مجھے بنی اسرائیل کی نظر میں پاک قرار دو، اس لیے تم اس جماعت کو اس زمین میں نہیں لاؤ گے جو میں نے انہیں دی ہے۔\n13. یہ {ہے} مریبہ کا پانی ہے؛ کیونکہ بنی اسرائیل نے خداوند کے ساتھ جدوجہد کی، اور وہ ان میں پاک ہوا۔ {میریبہ: یعنی، اسٹرائف}\n14۔ اور موسیٰ نے قادیش سے ادوم کے بادشاہ کے پاس پیغامبر بھیجے، یوں تمہارا بھائی اسرائیل کہتا ہے، تم جانتے ہو کہ ہم پر کتنی مشکلات آئی ہیں: {ہو چکی ہے...: عبرانی۔ ہمیں مل گیا}\n15۔ ہمارے آباؤ اجداد مصر میں کیسے گئے، اور ہم مصر میں طویل عرصے سے مقیم ہیں؛ اور مصریوں نے ہمیں اور ہمارے آباؤ اجداد کو تنگ کیا:\n16۔ اور جب ہم نے خداوند سے پکارا، اس نے ہماری آواز سنی، اور ایک فرشتہ بھیجا، اور ہمیں مصر سے نکالا: اور دیکھو، ہم قادیش میں ہیں، تیرے سرحد کے سب سے دور ایک شہر میں:\n17۔ میں تم سے دعا کرتا ہوں کہ ہم تمہارے ملک سے گزریں: ہم کھیتوں سے نہیں گزریں گے، نہ انگور کے باغات سے، نہ ہی کنوؤں کا پانی پیئیں گے: ہم بادشاہ کے بلند راستے سے جائیں گے، نہ دائیں طرف مڑیں گے نہ بائیں طرف، جب تک کہ ہم تمہاری سرحدیں پار نہ کر لیں۔\n18۔ اور ایڈوم نے اسے کہا، تم مجھ سے نہ گزر جاؤ، ورنہ میں تلوار لے کر تمہارے خلاف آؤں گا۔\n19۔ اور بنی اسرائیل نے اس سے کہا، ہم شاہراہ سے گزریں گے: اور اگر میں اور میرے مویشی تیرے پانی سے پیئیں تو میں اس کی قیمت چکاؤں گا: میں صرف بغیر کچھ کیے اپنے پیروں پر چلوں گا۔\n20۔ اور اس نے کہا، تم اندر نہیں جا سکتی۔ اور ایڈم نے بہت سے لوگوں کے ساتھ اور مضبوط ہاتھ کے ساتھ اس کے خلاف قدم اٹھایا۔\n21. یوں ایڈم نے اسرائیل کو اپنی سرحد سے گزرنے کی اجازت دینے سے انکار کر دیا، اس لیے اسرائیل نے اس سے منہ موڑ لیا۔\n22۔ اور بنی اسرائیل، حتیٰ کہ پوری جماعت بھی، قادیش سے روانہ ہوئے اور ہور پہاڑ پر آئے۔\n23۔ اور خداوند نے موسیٰ اور ہارون سے ہور پہاڑ پر، زمین ادوم کے کنارے پر، کہا،\n24۔ ہارون کو اس کے لوگوں کے پاس جمع کیا جائے گا: کیونکہ وہ اس زمین میں داخل نہیں ہوگا جو میں نے بنی اسرائیل کو دی ہے، کیونکہ تم نے میری بات کے خلاف مریبہ کے پانی پر بغاوت کی۔ {لفظ: عبرانی۔ منہ}\n25۔ ہارون اور اس کے بیٹے الیعازر کو لے کر انہیں ہور پر لے آؤ:\n26۔ اور ہارون کو اس کے کپڑے اتار کر اپنے بیٹے الیعزر پر پہنا دو، اور ہارون کو {اپنے لوگوں کے پاس} جمع کیا جائے گا، اور وہیں مر جائے گا۔\n27۔ اور موسیٰ نے خداوند کے حکم کے مطابق عمل کیا: اور وہ سب جماعت کے سامنے کوہ ہور پر چڑھے۔\n28۔ اور موسیٰ نے ہارون کے کپڑے اتارے اور انہیں اپنے بیٹے الیعازر پر پہنا دیا؛ اور ہارون وہاں پہاڑ کی چوٹی پر مرا: اور موسیٰ اور الیعزر پہاڑ سے نیچے آئے۔\n29۔ اور جب تمام جماعت نے دیکھا کہ ہارون مر چکا ہے، تو انہوں نے آرون کے لیے تیس دن سوگ منایا، {حتیٰ کہ} پورے اسرائیل کے لیے۔","1۔ اور {جب} بادشاہ عراد کنعانی، جو جنوب میں رہتا تھا، نے سنا کہ اسرائیل جاسوسوں کے راستے سے آیا ہے؛ پھر اس نے اسرائیل کے خلاف لڑائی کی، اور ان میں سے کچھ کو قیدی بنا لیا۔\n2۔ اور اسرائیل نے خداوند سے عہد کیا اور کہا، اگر تم واقعی اس قوم کو میرے حوالے کرو گے تو میں ان کے شہروں کو مکمل طور پر تباہ کر دوں گا۔\n3۔ اور خداوند نے اسرائیل کی آواز سنی اور کنعانیوں کو حوالے کیا؛ اور انہوں نے انہیں اور ان کے شہروں کو مکمل طور پر تباہ کر دیا: اور اس نے اس جگہ کا نام ہورمہ رکھا۔ {ہورمہ: یعنی، مکمل تباہی}\n4۔ اور وہ حور پہاڑ سے بحیرہ احمر کے راستے سے ادوم کی سرزمین کے گرد گئے: اور لوگوں کی روح راستے کی وجہ سے بہت مایوس ہوئی۔ {مایوس شدہ: یا، غمگین: عبرانی۔ مختصر شدہ}\n5۔ اور لوگوں نے خدا اور موسیٰ کے خلاف بات کی، تم نے ہمیں مصر سے بیابان میں مرنے کے لیے کیوں لایا ہے؟ کیونکہ {یہاں روٹی نہیں ہے}، نہ ہی {کوئی ہے} پانی؛ اور ہماری روح اس ہلکی روٹی سے نفرت کرتی ہے۔\n6۔ اور خداوند نے لوگوں میں آگ کے سانپ بھیجے، اور انہوں نے لوگوں کو کاٹا؛ اور اسرائیل کے بہت سے لوگ مارے گئے۔\n7۔ اس لیے لوگ موسیٰ کے پاس آئے اور کہا، ہم نے گناہ کیا ہے، کیونکہ ہم نے خداوند کے خلاف اور تیرے خلاف بات کی ہے؛ خداوند سے دعا کرو کہ وہ سانپوں کو ہم سے دور کر دے۔ اور موسیٰ نے لوگوں کے لیے دعا کی۔\n8۔ اور خداوند نے موسیٰ سے کہا، اپنے آپ کو آگ کا سانپ بنا دے، اور اسے کھمبے پر رکھ دے، اور یہ ہو جائے گا کہ جو بھی کاٹا جائے گا، جب وہ اسے دیکھے گا، زندہ رہے گا۔\n9۔ اور موسیٰ نے پیتل کا سانپ بنایا، اور اسے ایک کھمبے پر رکھا، اور ایسا ہوا کہ اگر سانپ نے کسی کو کاٹا، تو جب وہ پیتل کا سانپ دیکھے تو وہ زندہ رہتا ہے۔\n10۔ اور بنی اسرائیل آگے بڑھے، اور اوبوتھ میں زمین پر چڑھائی کی۔\n11۔ اور وہ اوبوتھ سے روانہ ہوئے، اور ایجباریم میں اترے جو موآب کے سامنے واقع صحرا میں سورج نکلنے کی طرف ہے۔ {ایجاباریم: یا، اباریم کے ڈھیر}\n12۔ وہاں سے وہ چلے گئے اور زارد کی وادی میں چٹان بنایا۔\n13۔ وہاں سے وہ نکل کر آرنون کے دوسری طرف کھڑے ہوئے، جو {ہے} اس صحرا میں جو اموری کے ساحلوں سے نکلتی ہے: کیونکہ آرنون {ہے} موآب کی سرحد ہے، موآب اور اموریوں کے درمیان۔\n14. اسی لیے خداوند کی جنگوں کی کتاب میں لکھا ہے، اس نے بحیرہ احمر میں کیا کیا، اور آرنون کی ندیوں میں، {کیا...: یا، وہب ان سوفا}\n15۔ اور ان ندی کے کنارے جو آر کے گھر تک جاتی ہے، اور موآب کی سرحد پر واقع ہے۔ {lieth: عبرانی۔ leaneth}\n16۔ اور وہاں سے {وہ گئے} بیر کی طرف: وہی کنواں ہے جس کے بارے میں خداوند نے موسیٰ سے کہا، لوگوں کو جمع کرو، اور میں انہیں پانی دوں گا۔\n17۔ پھر اسرائیل نے یہ گانا گایا، 'بہار اٹھو، اے کنواں'؛ اس پر گاؤ: {بہار...: عبرانی۔ چڑھو} {گاؤ: یا، جواب دو}\n18۔ شہزادوں نے کنواں کھودا، عوام کے اشرافیہ نے قانون ساز کی ہدایت پر، اپنی لاٹھیوں سے کھودا۔ اور ویرانے سے {وہ گئے} متانہ تک:\n19۔ اور متانہ سے نہالیئل تک: اور نہالیئل سے باموت تک:\n20۔ اور باموتھ {میں} وادی میں، یعنی موآب کے علاقے میں، پسگاہ کی چوٹی تک، جو یشیمون کی طرف دیکھتا ہے۔ {ملک: عبرانی۔ میدان} {پسگاہ: یا، پہاڑ} {یشیمون: یا، بیابان}\n21۔ اور اسرائیل نے اموری بادشاہ سیہون کے پاس پیغام بھیجے اور کہا،\n22۔ مجھے تیرے ملک سے گزرنے دو: ہم کھیتوں یا انگور کے باغات میں نہیں جائیں گے؛ ہم کنویں کے پانی سے نہیں پئیں گے: {لیکن} ہم بادشاہ کے {بلند} راستے پر چلتے رہیں گے، جب تک کہ ہم تمہاری سرحدوں سے باہر نہ پہنچ جائیں۔\n23۔ اور سیحون نے اسرائیل کو اپنی سرحد سے گزرنے نہیں دیا، لیکن سیحون نے اپنی تمام قوم کو جمع کیا اور اسرائیل کے خلاف بیابان میں نکل آیا، اور وہ جہاز پہنچا اور اسرائیل کے خلاف لڑا۔\n24۔ اور اسرائیل نے اسے تلوار کی نوک سے مارا، اور اس کی زمین ارنون سے یابوک تک، حتیٰ کہ آمون کے بچوں تک بھی قبضہ کر لی: کیونکہ آمون کے بچوں کی سرحد مضبوط تھی۔\n25۔ اور اسرائیل نے یہ تمام شہر فتح کیے: اور اسرائیل اموری کے تمام شہروں، ہیشبون اور ان کے تمام دیہاتوں میں آباد ہوا۔ {گاؤں: عبرانی۔ بیٹیاں}\n26۔ کیونکہ ہیشبون سیہون کا شہر تھا، جو اموری کا بادشاہ تھا، جس نے موآب کے سابق بادشاہ کے خلاف جنگ کی تھی، اور اس کی ساری زمین اس کے ہاتھ سے چھین لی تھی، حتیٰ کہ آرنون تک۔\n27۔ اسی لیے جو امثال میں بولتے ہیں وہ کہتے ہیں: ہیشبون میں آؤ، سیہون شہر تعمیر اور تیار ہو:\n28۔ کیونکہ ہیشبون سے آگ بجھ رہی ہے، سیہون شہر کی آگ: اس نے موآب کے آر اور آرنون کے بلند مقامات کے سرداروں کو جلا دیا ہے۔\n29۔ تم پر افسوس، موآب! اے کیموش کے لوگو، تم برباد ہو چکے ہو: اس نے اپنے بچ نکلنے والے بیٹے اور اپنی بیٹیوں کو اموری کے بادشاہ سیہون کے حوالے کر دیا ہے۔\n30۔ ہم نے ان پر فائر کیا ہے؛ ہیشبون یہاں تک کہ دیبون کے لیے بھی تباہ ہو گیا، اور ہم نے انہیں نوفاہ تک بھی تباہ کر دیا، جو میدیبا تک پہنچتا ہے۔\n31. یوں اسرائیل اموری کی سرزمین میں آباد تھا۔\n32۔ اور موسیٰ نے یازر کی جاسوسی کے لیے بھیجا، انہوں نے اس کے گاؤں لے لیے، اور وہاں موجود اموریوں کو نکال دیا۔\n33۔ اور وہ مڑے اور باشان کے راستے اوپر چلے گئے: اور اوگ، باشان کا بادشاہ، ان کے خلاف نکلا، وہ اور اس کے تمام لوگ، ادری کی جنگ کے لیے۔\n34۔ اور خداوند نے موسیٰ سے کہا، اس سے مت ڈرو، کیونکہ میں نے اسے تیرے ہاتھ میں دے دیا ہے، اور اس کے تمام لوگ اور اس کی زمین کو دے دیا ہے؛ اور تم اس کے ساتھ ویسا ہی کرو گے جیسا تم نے اموریوں کے بادشاہ سیحون کے ساتھ کیا، جو ہیشبون میں آباد تھا۔\n35۔ تو انہوں نے اسے، اس کے بیٹوں کو، اور اس کے تمام لوگوں کو مارا، یہاں تک کہ کوئی زندہ نہ رہ گیا: اور انہوں نے اس کی زمین پر قبضہ کر لیا۔","1۔ اور بنی اسرائیل آگے بڑھے، اور موآب کے میدانوں میں اس طرف اردن {یریحو کے ذریعے} میں قید کیا۔\n2۔ اور زپور کا بیٹا بالک نے دیکھا کہ اسرائیل نے اموریوں کے ساتھ کیا کیا تھا۔\n3۔ اور موآب لوگوں سے بہت خوفزدہ تھا، کیونکہ وہ بہت تھے: اور موآب بنی اسرائیل کی وجہ سے پریشان تھا۔\n4۔ اور موآب نے مدیان کے بزرگوں سے کہا، اب یہ جماعت ہمارے ارد گرد موجود تمام لوگوں کو چاٹیں گے، جیسے بیل کھیت کی گھاس چاٹتا ہے۔ اور بالک، زپور کا بیٹا، اس وقت موآبیوں کا بادشاہ تھا۔\n5۔ اس لیے اس نے بلاعام، بیور کے بیٹے کے پاس پیتھور بھیجے، جو اس کی قوم کے بچوں کی سرزمین کے دریا کے کنارے ہے، اسے بلایا اور کہا، دیکھو، مصر سے ایک قوم نکلتی ہے: دیکھو، وہ زمین کے چہرے کو ڈھانپے ہوئے ہیں، اور میرے خلاف کھڑے ہیں: {چہرہ: عبرانی۔ آنکھ}\n6۔ اب آؤ، میں تم سے دعا کرتا ہوں، مجھے اس قوم پر لعنت دو؛ کیونکہ وہ میرے لیے بہت طاقتور ہیں: شاید میں کامیاب ہو جاؤں، تاکہ ہم انہیں مار سکیں، اور انہیں زمین سے نکال سکوں: کیونکہ میں چاہتا ہوں کہ جسے تم برکت دیتے ہو وہ برکت یافتہ ہو، اور جسے تم لعنت دیتے ہو وہ لعنت زدہ ہو۔\n7۔ اور موآب کے بزرگ اور مدیان کے بزرگ فال گیری کے انعامات ہاتھ میں لے کر روانہ ہوئے؛ اور وہ بلعام کے پاس آئے اور اس سے بالاک کے الفاظ سنائے۔\n8۔ اور اس نے ان سے کہا، آج رات یہاں رہو، اور میں تمہیں دوبارہ پیغام دوں گا، جیسا کہ خداوند مجھ سے فرمائے گا: اور موآب کے شہزادے بلعام کے ساتھ رہیں۔\n9۔ اور خدا بلعام کے پاس آیا اور کہا، یہ لوگ آپ کے ساتھ کون ہیں؟\n10۔ اور بلعام نے خدا سے کہا، زپور کا بیٹا، موآب کا بادشاہ، بالک نے مجھے بھیجا ہے، {کہ}\n11۔ دیکھو، {یہاں ہے} ایک قوم مصر سے نکلتی ہے، جو زمین کے چہرے کو ڈھانپتی ہے: اب آؤ، مجھے ان پر لعنت دو؛ شاید میں انہیں شکست دے سکوں، اور انہیں نکال دوں۔ {میں کروں گا...: عبرانی۔ میں اس کے خلاف لڑائی میں کامیاب ہو جاؤں گا}\n12۔ اور خدا نے بلعام سے کہا، تم ان کے ساتھ نہیں جاؤ گے؛ تم لوگوں کو لعنت نہ دو، کیونکہ وہ {بابرکت ہیں}۔\n13۔ اور بلعام صبح اٹھا اور بالاک کے شہزادوں سے کہا، اپنے ملک میں جاؤ، کیونکہ خداوند مجھے تمہارے ساتھ جانے کی اجازت نہیں دیتا۔\n14۔ اور موآب کے شہزادے اٹھ کھڑے ہوئے، اور بالاک کے پاس گئے اور کہا، بلعام ہمارے ساتھ آنے سے انکار کرتا ہے۔\n15۔ اور بالاک نے ایک بار پھر شہزادے بھیجے، جو ان سے زیادہ اور زیادہ معزز تھے۔\n16۔ اور وہ بلعام کے پاس آئے اور اس سے کہا، یوں بلاق زپور کا بیٹا کہتا ہے، میں دعا کرتا ہوں کہ کوئی چیز تمہیں میرے پاس آنے سے نہ روکے: {آؤ...: عبرانی۔ آپ کو روکا نہ جائے، وغیرہ}\n17۔ کیونکہ میں تمہیں بہت بڑی عزت دوں گا، اور جو تم مجھ سے کہو گے وہی کروں گا: آؤ، میں تم سے دعا کرتا ہوں، اس قوم پر لعنت بھیج۔\n18۔ اور بلعام نے جواب دیا اور بالک کے خادموں سے کہا، اگر بالک مجھے اپنا گھر چاندی اور سونے سے بھرا دے تو میں خداوند میرے خدا کے کلام سے آگے نہیں جا سکتا، کم یا زیادہ کرنے کے لیے۔\n19۔ لہٰذا، میں آپ سے درخواست کرتا ہوں کہ آپ بھی آج رات یہاں رہیں تاکہ میں جان سکوں کہ خداوند مجھ سے کیا کہے گا۔\n20۔ اور خدا رات کو بلعام کے پاس آیا اور اسے کہا، اگر لوگ تمہیں بلانے آئیں تو اٹھو، {اور} ان کے ساتھ چلو؛ لیکن پھر بھی جو لفظ میں تم سے کہوں گا، وہ تم کرو گے۔\n21۔ اور بلعام صبح اٹھا، زین لگا کر موآب کے شہزادوں کے ساتھ چلا گیا۔\n22۔ اور خدا کا غصہ بھڑکا کیونکہ وہ گیا: اور خداوند کا فرشتہ اس کے خلاف مخالف کے راستے میں کھڑا ہوا۔ اب وہ اس کے پیچھے سوار تھا، اور اس کے دو خادم اس کے ساتھ تھے۔\n23۔ اور گدھے نے دیکھا کہ خداوند کا فرشتہ راستے میں کھڑا ہے، اور اس کی تلوار ہاتھ میں کھینچی ہوئی ہے، اور گدھا راستے سے ہٹ گیا اور میدان میں چلا گیا، اور بلعام نے گدھے کو مارا تاکہ اسے راستہ دے۔\n24۔ لیکن خداوند کا فرشتہ انگور کے باغات کے راستے میں کھڑا تھا، اس طرف ایک دیوار {وجود} تھی، اور اس طرف ایک دیوار۔\n25۔ اور جب گدھے نے خداوند کے فرشتے کو دیکھا، تو وہ دیوار سے ٹکرا گئی اور بلعام کے پاؤں کو دیوار سے ٹکرا دیا، اور اس نے اسے دوبارہ مارا۔\n26۔ اور خداوند کا فرشتہ آگے بڑھا اور ایک تنگ جگہ پر کھڑا ہو گیا، جہاں نہ دائیں اور نہ بائیں طرف مڑنے کا کوئی راستہ تھا۔\n27۔ اور جب گدھے نے خداوند کے فرشتے کو دیکھا، تو وہ بلعام کے نیچے گر گئی: اور بلعام کا غصہ بھڑک اٹھا، اور اس نے گدھے کو چھڑی سے مارا۔\n28۔ اور خداوند نے گدھے کا منہ کھولا، اور اس نے بلعام سے کہا، میں نے تمہارے ساتھ کیا کیا ہے کہ تم نے مجھے تین بار مارا؟\n29۔ اور بلعام نے گدھے سے کہا، کیونکہ تم نے میرا مذاق اڑایا: کاش میرے ہاتھ میں تلوار ہوتی، کیونکہ اب میں تمہیں مار دیتا۔\n30۔ اور گدھے نے بلعام سے کہا، {کیا میں تمہارا گدھا نہیں ہوں، جس پر تم آج تک سواری کر رہے ہو؟ کیا میں کبھی تمہارے ساتھ ایسا کرنے کی عادت رکھتا تھا؟ اور اس نے کہا، نہیں۔ {اوپر...: عبرانی جس نے مجھ پر سوار ہو کر کیا ہے} {تب سے...: یا، جب سے تم نے بہاؤ کیا، وغیرہ}\n31۔ پھر خداوند نے بلعام کی آنکھیں کھولیں، اور اس نے دیکھا کہ خداوند کا فرشتہ راستے میں کھڑا ہے، اس کے ہاتھ میں تلوار نکلی ہوئی ہے، اور وہ سر جھکا کر چہرے کے بل گر پڑا۔ {گر گیا...: یا، جھک گیا}\n32۔ اور خداوند کے فرشتے نے اس سے کہا، تم نے اپنے گدھے کو یہ تین بار کیوں مارا؟ دیکھو، میں تمہارے سامنے نکلا، کیونکہ {تیرا}راستہ میرے سامنے بگڑا ہوا ہے: {تو...: عبرانی۔ تمہارا مخالف بننے کے لیے}\n33۔ اور گدھے نے مجھے دیکھا، اور تین بار مجھ سے منہ موڑ لیا: جب تک وہ مجھ سے منہ نہ موڑتی، یقینا اب میں نے تمہیں مار ڈالا اور اسے زندہ بچا لیا۔\n34۔ اور بلعام نے خداوند کے فرشتے سے کہا، میں نے گناہ کیا ہے؛ کیونکہ میں نہیں جانتا تھا کہ تم میرے راستے میں کھڑے ہو: اب، اگر تمہیں ناگوار گزرا، تو میں خود کو واپس لے آؤں گا۔ {ناپسندیدہ...: عبرانی اپنی آنکھوں میں برائی بنو}\n35۔ اور خداوند کے فرشتے نے بلعام سے کہا، لوگوں کے ساتھ چلو، لیکن صرف وہی کلام جو میں تم سے کہوں گا، اور تم کہو گے۔ تو بلعام بالاک کے شہزادوں کے ساتھ گیا۔\n36۔ اور جب بالک نے سنا کہ بلعام آ گیا ہے، تو وہ اس سے ملنے موآب کے ایک شہر گیا، جو ارنون کی سرحد پر ہے، جو سب سے دور ساحل پر ہے۔\n37۔ اور بالاک نے بلعام سے کہا، کیا میں نے دل سے تمہیں بلانے کے لیے نہیں بھیجا تھا؟ تم میرے پاس کیوں نہیں آئے؟ کیا میں واقعی تمہیں عزت دینے کے قابل نہیں ہوں؟\n38۔ اور بلعام نے بالک سے کہا، دیکھو، میں تمہارے پاس آیا ہوں: کیا اب میرے پاس کچھ کہنے کی کوئی طاقت ہے؟ وہ لفظ جو خدا میرے منہ میں رکھتا ہے، جو میں بولوں گا۔\n39۔ اور بلعام بالک کے ساتھ گیا، اور وہ کرجاتھوزوت پہنچے۔ {کرجاتھوزوتھ: یا، گلیوں کا شہر}\n40۔ اور بالاک نے بیل اور بھیڑیں پیش کیں، اور بلعام اور ان شہزادوں کو بھیجا جو اس کے ساتھ تھے۔\n41۔ اور کل ایسا ہوا کہ بالک نے بلعام کو لے کر بعل کے بلند مقامات پر لے جایا تاکہ وہاں سے وہ لوگوں کی پوری طرح دیکھ سکے۔","1۔ اور بلعام نے بالک سے کہا، یہاں میرے لیے سات قربان گاہ بنا، اور یہاں سات بیل اور سات مینڈھے تیار کرو۔\n2۔ اور بالک نے ویسا ہی کیا جیسا بلعام نے کہا تھا؛ اور بالک اور بلعام نے ہر قربان گاہ پر ایک بیل اور ایک مینڈھا پیش کیا۔\n3۔ اور بلعام نے بالک سے کہا، اپنی جلنے والی قربانی کے پاس کھڑے رہو، اور میں جاؤں گا: شاید خداوند میرے پاس آئے گا: اور جو کچھ بھی وہ مجھے دکھائے گا، میں تمہیں بتاؤں گا۔ اور وہ ایک اونچی جگہ پر گیا۔ {ایک...: یا، تنہا}\n4۔ اور خدا نے بلعام سے ملاقات کی: اور اس نے اسے کہا، میں نے سات قربان گاہیں تیار کی ہیں، اور ہر قربان گاہ پر ایک بیل اور ایک مینڈھا پیش کیا ہے۔\n5۔ اور خداوند نے بلعام کے منہ میں ایک لفظ رکھا اور کہا، واپس بالک جاؤ، اور یوں بولو گے۔\n6۔ اور وہ اس کے پاس واپس آیا، اور دیکھو، وہ اپنی جلی ہوئی قربانی کے ساتھ کھڑا رہا، وہ اور موآب کے تمام شہزادے۔\n7۔ اور اس نے اپنی تمثیل لی، اور کہا، موآب کے بادشاہ بالک نے مجھے آرام سے مشرق کے پہاڑوں سے لایا ہے، {کہ}، آؤ، مجھے لعنت دو یعقوب، اور آؤ، اسرائیل کی مخالفت کرو۔\n8. میں کیسے لعنت کروں، جسے خدا نے لعنت نہیں دی؟ یا میں کیسے چیلنج کروں، {جسے خداوند نے نہ چیلنج کیا؟'\n9۔ کیونکہ میں چٹانوں کی چوٹی سے اسے دیکھتا ہوں، اور پہاڑوں سے اسے دیکھتا ہوں: دیکھو، لوگ اکیلے رہیں گے، اور قوموں میں شمار نہیں ہوں گے۔\n10. یعقوب کی خاک اور اسرائیل کے چوتھے حصے کی تعداد کون گن سکتا ہے؟ مجھے نیک لوگوں کی موت مرنے دو، اور میرا آخری انجام اس کی طرح ہو! {میں: عبرانی۔ میری جان، یا، میری زندگی}\n11۔ اور بالک نے بلعام سے کہا، تم نے میرے ساتھ کیا کیا ہے؟ میں نے تمہیں اپنے دشمنوں کو لعنت دینے کے لیے لیا، اور دیکھو، تم نے انہیں مکمل طور پر برکت دی ہے۔\n12۔ اور اس نے جواب دیا اور کہا، کیا مجھے وہ بات سننے کی ضرورت نہیں جو خداوند نے میرے منہ میں ڈالی ہے؟\n13۔ اور بالک نے اس سے کہا، آؤ، میں تمہیں میرے ساتھ کسی اور جگہ پر بھیجتا ہوں، جہاں سے تم انہیں دیکھ سکتے ہو: تم صرف ان کا سب سے زیادہ حصہ دیکھو گے، اور سب کو نہیں دیکھو گے، اور وہاں سے مجھے لعنت بھیج۔\n14۔ اور اس نے اسے زوفیم کے میدان میں، پسگاہ کی چوٹی پر لے گیا، سات قربان گاہیں بنائیں، اور ہر قربان گاہ پر ایک بیل اور ایک مینڈھا پیش کیا۔ {پسگاہ: یا، پہاڑی}\n15۔ اور اس نے بالاک سے کہا، یہاں اپنی جلائی ہوئی قربانی کے پاس کھڑے رہو، جب میں {خدا} سے وہاں ملتا ہوں۔\n16۔ اور خداوند نے بلعام سے ملاقات کی، اس کے منہ میں ایک لفظ رکھا اور کہا، \"دوبارہ بالک کے پاس جاؤ، اور ایسا کہو۔\n17۔ اور جب وہ اس کے پاس آیا، دیکھو، وہ اپنی جلانے والی قربانی کے پاس کھڑا تھا، اور موآب کے شہزادے اس کے ساتھ تھے۔ اور بالک نے اس سے کہا، خداوند نے کیا کہا؟\n18۔ اور اس نے اپنی تمثیل کو اپنایا اور کہا، اٹھو، بالاک، اور سنو؛ میری بات سنو، اے زیپور کے بیٹے:\n19. خدا {ہے} انسان نہیں ہے کہ وہ جھوٹ بولے؛ نہ ہی انسان کے بیٹے کو، کہ وہ توبہ کرے: کیا اس نے کہا ہے، اور کیا وہ نہیں کرے گا؟ یا اس نے بات کی ہے، اور کیا وہ اسے اچھا نہیں بنائے گا؟\n20۔ دیکھو، مجھے برکت دینے کا حکم ملا ہے: اور اس نے برکت دی ہے؛ اور میں اسے واپس نہیں کر سکتا۔\n21. اس نے یعقوب میں بدکاری نہیں دیکھی، نہ ہی اسرائیل میں گناہ دیکھی: خداوند اس کا خدا اس کے ساتھ ہے، اور بادشاہ کی پکار ان میں ہے۔\n22۔ خدا نے انہیں مصر سے نکالا؛ اس کے پاس ایک یونیکورن کی طاقت ہے۔\n23۔ یقینا یعقوب کے خلاف کوئی جادو نہیں، نہ ہی اسرائیل کے خلاف کوئی فال ہے: اس وقت کے مطابق یعقوب اور اسرائیل کے بارے میں کہا جائے گا، خدا نے کیا کیا! {خلاف: یا، اندر}\n24۔ دیکھو، لوگ ایک بڑے شیر کی طرح اٹھیں گے، اور خود کو ایک نوجوان شیر کی طرح اٹھائیں گے: وہ تب تک نہیں لیٹے گا جب تک شکار کھا نہ لے اور شکار کا خون نہ پیے۔\n25۔ اور بالک نے بلعام سے کہا، نہ انہیں بالکل لعنت دو، نہ ہی انہیں برکت دو۔\n26۔ لیکن بلعام نے جواب دیا اور بالک سے کہا، کیا میں نے تمہیں یہ نہیں بتایا کہ خداوند جو کچھ کہتا ہے، وہ سب مجھے کرنا ہے؟\n27۔ اور بالک نے بلعام سے کہا، آؤ، میں تم سے دعا کرتا ہوں، میں تمہیں کہیں اور لے جاؤں گا؛ شاید خدا کو پسند آئے کہ تم مجھے وہاں سے ان پر لعنت بھیجو۔\n28۔ اور بلاق نے بلعام کو پیعور کی چوٹی پر لے آیا، جو یشیمون کی طرف دیکھ رہا تھا۔\n29۔ اور بلعام نے بلق سے کہا، میرے لیے یہاں سات قربان گاہیں بنا، اور یہاں سات بیل اور سات مینڈھے تیار کرو۔\n30۔ اور بالک نے وہی کیا جو بلعام نے کہا تھا، اور ہر قربان گاہ پر ایک بیل اور ایک مینڈھا پیش کیا۔","1۔ اور جب بلعام نے دیکھا کہ خداوند کو اسرائیل کو برکت دینا پسند ہے، تو وہ دیگر اوقات کی طرح جادو تلاش کرنے نہیں گیا، بلکہ اپنا رخ بیابان کی طرف کیا۔ {تلاش کرنے کے لیے...: عببرانی۔ ملاقات کے لیے}\n2۔ اور بلعام نے اپنی آنکھیں اٹھائیں، اور اس نے دیکھا کہ اسرائیل اپنے قبیلوں کے مطابق {اپنے خیموں میں} ٹھہرے ہوئے ہیں؛ اور خدا کی روح اس پر آ گئی۔\n3۔ اور اس نے اپنی تمثیل لی اور کہا، بلعام بیور کے بیٹے نے کہا ہے، اور جس کی آنکھیں کھلی ہیں اس نے کہا: {جس نے...: عبرانی۔ جس کی آنکھیں بند تھیں، لیکن اب کھلی ہوئی تھیں}\n4۔ اس نے کہا ہے، جس نے خدا کے کلام سنے، جس نے قادر مطلق کا خواب دیکھا، جو ایک غنودگی میں چلا گیا، لیکن اپنی آنکھیں کھلی ہوئی تھی:\n5. اے یعقوب، تیرے خیمے کتنے اچھے ہیں، اے اسرائیل!\n6۔ جیسے وادیاں پھیلتی ہیں، جیسے دریا کے کنارے باغات، جیسے رب نے لگائی ہوئی ایلو کے درخت، {اور} جیسے پانی کے کنارے دیودار کے درخت۔\n7۔ وہ اپنے بالٹیوں سے پانی ڈالے گا، اور اس کا بیج کئی پانیوں میں ہوگا، اور اس کا بادشاہ آگاگ سے بلند ہوگا، اور اس کی بادشاہت بلند ہوگی۔\n8۔ خدا نے اسے مصر سے باہر نکالا؛ اس کے پاس ایک یونیکورن کی طاقت ہے: وہ قوموں کو اپنے دشمنوں کو کھا جائے گا، ان کی ہڈیاں توڑ دے گا، اور اپنے تیروں سے انہیں چیر دے گا۔\n9۔ وہ شیر کی طرح لیٹ گیا، اور ایک بڑے شیر کی طرح لیٹا: کون اسے ہلائے گا؟ مبارک ہے وہ جو تمہیں برکت دیتا ہے، اور لعنت زدہ وہ ہے جو تمہیں لعنت دیتا ہے۔\n10۔ اور بالاک کا غصہ بلعام کے خلاف بھڑک اٹھا، اور اس نے اپنے ہاتھ آپس میں مارے: اور بالک نے بلعام سے کہا، میں نے تمہیں بلایا ہے کہ میرے دشمنوں کو لعنت دوں، اور دیکھو، تم نے انہیں تین بار برکت دی ہے۔\n11۔ لہٰذا اب اپنی جگہ کی طرف بھاگو: میں نے تمہیں بڑی عزت دینے کا سوچا؛ لیکن، دیکھو، خداوند نے تمہیں عزت سے دور رکھا ہے۔\n12۔ اور بلعام نے بالک سے کہا، میں نے تمہارے بھیجنے والوں سے بھی نہیں کہا جو تم نے مجھے بھیجے تھے، اور کہا،\n13۔ اگر بالک مجھے اپنا گھر چاندی اور سونے سے بھرا دے تو میں خداوند کے حکم سے آگے نہیں جا سکتا، نہ تو اپنے دل سے اچھا یا برا کر سکتا ہوں؛ {لیکن}خداوند نے کیا کہا، کیا میں بولوں گا؟\n14. اور اب، دیکھو، میں اپنے لوگوں کے پاس جا رہا ہوں: آؤ {لہٰذا} میں تمہیں بتاؤں گا کہ یہ قوم تمہارے لوگوں کے ساتھ آخری دنوں میں کیا کرے گی۔\n15۔ اور اس نے اپنی تمثیل لی اور کہا، بلعام بیور کے بیٹے نے کہا ہے، اور جس کی آنکھیں کھلی ہیں اس نے کہا:\n16۔ اس نے کہا ہے، جس نے خدا کے کلام سنے، اور سب سے بلند کا علم جانتا ہے، {جس نے} قادر مطلق کا خواب دیکھا، جو {ایک غنودگی میں} چلا گیا، لیکن اپنی آنکھیں کھلی رکھے:\n17۔ میں اسے دیکھوں گا، لیکن ابھی نہیں: میں اسے دیکھوں گا، لیکن قریب نہیں: یعقوب سے ایک ستارہ نکلے گا، اور اسرائیل سے ایک عصا نکلے گا، جو موآب کے کونوں کو تباہ کر دے گا، اور شیٹھ کے تمام بچوں کو تباہ کر دے گا۔ {مارو...: یا، شہزادوں کے ذریعے مارو}\n18۔ اور ایڈوم ایک ملکیت ہوگی، سعیر بھی اپنے دشمنوں کے لیے ملکیت ہوگا؛ اور اسرائیل بہادری سے کام کرے گا۔\n19۔ یعقوب سے وہ آئے گا جو حکمرانی کرے گا، اور شہر کے باقی بچے ہوئے کو تباہ کر دے گا۔\n20۔ اور جب اس نے عمالیق کو دیکھا، تو اس نے اپنی تمثیل لی اور کہا، عمالیق قوموں میں سب سے پہلے تھا؛ لیکن اس کا آخری انجام یہ ہوگا کہ وہ ہمیشہ کے لیے فنا ہو جائے۔ {قومیں: وہ قومیں جنہوں نے اسرائیل کے خلاف جنگ کی} {وہ...: یا حتیٰ کہ تباہی تک}\n21۔ اور اس نے کینائٹس کو دیکھا، اپنی تمثیل اپنایا اور کہا، تمہارا مسکن مضبوط ہے، اور تم اپنا گھونسلہ چٹان میں بناتے ہو۔\n22. تاہم کینائٹ ضائع ہو جائے گا، جب تک کہ آشور تمہیں قید نہ کر دے۔ {کینائٹ: عبرانی۔ کائن} {جب تک...: یا، کب تک آشور تمہیں قید میں لے جائے گا}\n23۔ اور اس نے اپنی تمثیل لی اور کہا، افسوس، جب خدا یہ کرے گا تو کون زندہ رہے گا!\n24۔ اور جہاز چتیم کے ساحل سے آئیں گے، اور اشور کو تکلیف دیں گے، اور ایبر کو بھی تکلیف دیں گے، اور وہ بھی ہمیشہ کے لیے ہلاک ہو جائے گا۔\n25۔ اور بلعام اٹھا اور اپنے گھر واپس آیا: اور بلاق بھی اپنے راستے پر گیا۔","1۔ اور اسرائیل شتیم میں آباد ہوئے، اور لوگوں نے موآب کی بیٹیوں کے ساتھ بدکاری شروع کر دی۔\n2۔ اور انہوں نے لوگوں کو اپنے دیوتاؤں کی قربانیوں کے لیے بلایا: اور لوگوں نے کھانا کھایا اور اپنے دیوتاؤں کے سامنے جھک گئے۔\n3۔ اور اسرائیل نے خود کو بعلپور کے ساتھ جوڑ دیا: اور خداوند کا غصہ اسرائیل پر بھڑک اٹھا۔\n4۔ اور خداوند نے موسیٰ سے کہا، تمام لوگوں کے سر لے کر انہیں خداوند کے سامنے سورج کے خلاف لٹکا دو، تاکہ خداوند کا شدید غصہ اسرائیل سے دور ہو جائے۔\n5۔ اور موسیٰ نے اسرائیل کے ججوں سے کہا، اس کے ہر آدمی کو مار ڈالو جو بعلپور کے ساتھ منسلک تھا۔\n6۔ اور دیکھتے ہوئے، بنی اسرائیل میں سے ایک آیا اور اپنے بھائیوں کے سامنے ایک مدیانی عورت کو موسیٰ کی نظر اور بنی اسرائیل کی تمام جماعت کے سامنے لایا، جو جماعت کے خیمہ کے دروازے کے سامنے رو رہے تھے۔\n7۔ اور جب فینحاس، الیعزر کا بیٹا، جو ہارون کاهن کا بیٹا تھا، نے اسے دیکھا، تو وہ جماعت میں سے اٹھ کھڑا ہوا اور اپنے ہاتھ میں نیزہ پکڑا؛\n8۔ اور وہ اسرائیل کے آدمی کے پیچھے خیمے میں گیا، اور دونوں کو اس کے اندر دھکیل دیا، اسرائیل کا آدمی، اور عورت کو اس کے پیٹ میں۔ لہٰذا وبا بنی اسرائیل سے روکی گئی۔\n9۔ اور جو لوگ طاعون میں مرے، ان کی عمر چوبیس ہزار تھی۔\n10۔ اور خداوند نے موسیٰ سے کہا،\n11۔ فینحاس، الیعزر کا بیٹا، جو ہارون کاهن کا بیٹا تھا، نے میرے غصے کو بنی اسرائیل سے دور کر دیا، جبکہ وہ میرے لیے ان کے درمیان جوشیلا تھا، کہ میں نے اپنی حسد میں بنی اسرائیل کو نہ کھایا۔ {for...: عبرانی۔ اپنے جوش کے ساتھ}\n12۔ لہٰذا کہو، دیکھو، میں اسے اپنا امن کا عہد دیتا ہوں:\n13۔ اور اسے یہ ملے گا، اور اس کے بعد اس کی نسل بھی، {حتیٰ کہ} دائمی پادری کا عہد بھی؛ کیونکہ وہ اپنے خدا کے لیے پرجوش تھا، اور بنی اسرائیل کے لیے کفارہ بنایا۔\n14۔ اب اس اسرائیلی کا نام جو مارا گیا، {حتی} جو مدیانی عورت کے ساتھ مارا گیا، {تھا} زمری، جو سالو کا بیٹا تھا، اور سیمیونیوں میں ایک سردار خاندان کا شہزادہ تھا۔ {چیف...: عببرانی۔ ہاؤس آف اے فادر}\n15۔ اور اس مدیانی عورت کا نام جو قتل ہوئی {تھی} کوزبی، زور کی بیٹی؛ وہ مدیان کے ایک سردار خاندان کے ایک قوم کا سربراہ تھا۔\n16۔ اور خداوند نے موسیٰ سے کہا،\n17۔ مدیانیوں کو تنگ کرو، اور انہیں مارو:\n18۔ کیونکہ وہ تمہیں اپنی چالاکیوں سے پریشان کرتے ہیں، جن سے انہوں نے تمہیں پیور کے معاملے میں بہکایا، اور کوزبی کے معاملے میں، جو مدیان کے ایک شہزادے کی بیٹی تھی، ان کی بہن، جو پیور کی خاطر طاعون کے دن قتل کر دی گئی تھی۔","1۔ اور طاعون کے بعد ایسا ہوا کہ خداوند نے موسیٰ اور ہارون کاهن کے بیٹے الیعزر سے کہا،\n2. اسرائیل کے تمام بچوں کی جماعت کا مجموعہ لے لیں، بیس سال کی عمر سے لے کر اس سے اوپر، جو اپنے باپ کے گھر میں اسرائیل میں جنگ کرنے کے قابل ہیں۔\n3۔ اور موسیٰ اور الیعازر کاهن نے اردن کے قریب موآب کے میدانوں میں ان سے بات کی، اور کہا،\n4. {لوگوں کا مجموعہ لے لیں}، بیس سال کی عمر سے اور اس سے اوپر؛ جیسا کہ خداوند نے موسیٰ اور بنی اسرائیل کو حکم دیا، جو مصر کی سرزمین سے باہر نکلے۔\n5۔ روبن، اسرائیل کا سب سے بڑا بیٹا: روبن کے بیٹے؛ حنوخ، جن میں سے ہنوچیوں کا خاندان آتا ہے: پالو، پالوائیٹس کا خاندان:\n6۔ ہیزرون، ہیزرونائٹس کا خاندان: کارمی کا، کارمائٹس کا خاندان۔\n7۔ یہ روبینیوں کے خاندان ہیں: اور ان میں سے چالیس تین ہزار سات سو تیس تھے۔\n8۔ اور پالو کے بیٹے؛ الیاب۔\n9۔ اور ایلیاب کے بیٹے؛ نیموئل، اور داتھن، اور ابیرام۔ یہ وہی داتھان اور ابیرام ہیں، جو جماعت میں مشہور تھے، جنہوں نے موسیٰ اور ہارون کے خلاف قارح کے ساتھ لڑائی کی، جب وہ خداوند کے خلاف لڑے:\n10۔ اور زمین نے اپنا منہ کھولا، اور انہیں کورح کے ساتھ نگل لیا، جب وہ جماعت مر گئی، جب آگ نے دو سو پچاس آدمیوں کو نگل لیا: اور وہ ایک نشان بن گئے۔\n11۔ اگرچہ قارح کے بچے نہیں مرے تھے۔\n12۔ شمعون کے بیٹے ان کے خاندانوں کے بعد: نیموئل کے، نیمولائٹس کا خاندان: یامین کا، یامین کا خاندان: یاچن کا، جاخنائٹس کا خاندان: {نیمویل: جسے جیموئیل بھی کہا جاتا ہے} {جاچین: جسے جریب بھی کہا جاتا ہے}\n13۔ زراح کی، زرہیوں کا خاندان: شاؤل کا، شاؤلیوں کا خاندان۔ {زرہ: جسے زوہر بھی کہا جاتا ہے}\n14۔ یہ سیمیونیوں کے خاندان ہیں، بیس دو ہزار دو سو۔\n15۔ گاد کے بچے ان کے خاندانوں کے بعد: زیفون کے، زیفونیوں کا خاندان: ہاگی کا، ہیگیوں کا خاندان: شونی کا، شونیائی خاندان: {زیفون: جسے زیفیون بھی کہا جاتا ہے}\n16۔ اوزنی، اوزنائٹس کا خاندان: ایری کا، ایریٹس کا خاندان: {اوزنی: جسے ایزبون بھی کہا جاتا ہے}\n17۔ آروڈ، آروڈائٹس کا خاندان: آریلی کا، ارلائٹس کا خاندان۔ {آروڈ: جسے آرودی بھی کہا جاتا ہے}\n18۔ یہ جاد کے بچوں کے خاندان ہیں جو ان میں سے گننے والوں کے مطابق چالیس ہزار پانچ سو تھے۔\n19۔ یہوداہ کے بیٹے ایر اور اونان تھے: اور ایر اور اونان کنعان کی سرزمین میں وفات پا گئے۔\n20۔ اور یہوداہ کے بیٹے ان کے خاندانوں کے بعد یہ تھے؛ شلہ، شیلانیوں کا خاندان: فراز کا، فارزیوں کا خاندان، زراہ کا خاندان، زرہیوں کا خاندان۔\n21۔ اور فاریز کے بیٹے تھے؛ ہیزرون کا خاندان، ہیزرونائٹس کا خاندان: ہمول کا، ہمولیوں کا خاندان۔\n22۔ یہ یہوداہ کے خاندان ہیں جو ان میں سے تین سو سولہ ہزار پانچ سو تھے۔\n23. {Of} عیساکار کے بیٹوں کے خاندانوں کے مطابق: {of} تولا، تولائٹس کا خاندان: پوا کے، پونیٹیز کا خاندان: {پوا: یا، پھوا}\n24۔ جاشوبیوں کا خاندان: شمرون کا، شمرونیوں کا خاندان۔ {یاشب: یا، ایوب}\n25۔ یہ {ہیں} اسکھار کے خاندان جو ان میں سے تین سو اور چار ہزار تین سو تھے۔\n26۔ {Of} زبولون کے بیٹوں کے خاندانوں کے بعد: سرد کے، ساردیتوں کا خاندان: ایلون کا، ایلونائٹس کا خاندان: جہلیل کا، جہلیئٹس کا خاندان۔\n27۔ یہ زبولونیوں کے خاندان ہیں جو ان میں سے تین ہزار پانچ سو کے مطابق شمار کیے گئے تھے۔\n28۔ یوسف کے بیٹے ان کے خاندانوں کے بعد منسی اور افرائیم تھے۔\n29۔ مناسی کے بیٹوں سے: ماخر کے ماخریوں کا خاندان: اور ماکیر نے گلعاد کو جنم دیا: گلعاد {آؤ} گلعادیوں کا خاندان۔\n30. یہ {ہیں} گلعاد کے بیٹے: {of} جیزر، جیزریت خاندان کے خاندان: ہیلیک کے، ہیلیکیوں کا خاندان: {جیزر: جسے ابیزر بھی کہا جاتا ہے}\n31۔ اور {of} اسریئل، اسریائیلیوں کا خاندان: اور {of} شیخم، شکیمیوں کا خاندان:\n32۔ اور {of} شیمیدا، شیمیدائیوں کا خاندان؛ اور {of} ہیفر، ہیفریٹس کا خاندان۔\n33۔ اور زیلوفحاد جو ہیفر کا بیٹا تھا، اس کے کوئی بیٹے نہیں تھے، صرف بیٹیاں تھیں: اور زیلوفہد کی بیٹیوں کے نام مہلہ، نوح، ہوگلہ، ملکہ اور تیرزہ تھے۔\n34۔ یہ منسی کے خاندان ہیں، اور ان میں سے جن کی تعداد پچاس دو ہزار سات سو تھی۔\n35۔ یہ افریم کے بیٹے ہیں، ان کے خاندانوں کے بعد: شوثلہ کے، شثالیوں کا خاندان، بیخر کا، باخرائٹس کا خاندان: تہان کا تہانیوں کا خاندان۔ {بیچر: جسے بیرڈ بھی کہا جاتا ہے}\n36۔ اور یہ شوتھیلہ کے بیٹے ہیں: ایران کے، جو ایرنائٹس کا خاندان ہے۔\n37۔ یہ {ہیں} افرائیم کے بیٹوں کے خاندان، ان میں سے تیس دو ہزار پانچ سو۔ یہ یوسف کے اپنے خاندانوں کے نام پر بیٹے ہیں۔\n38۔ بنیامین کے بیٹے، ان کے خاندانوں کے بعد: بیلا کے، بیلائیوں کا خاندان: اشبیل کے، اشبلیٹس کا خاندان: اہیریم کا، اہیرمائیوں کا خاندان: {احیرم: جسے ایہی یا آہارہ بھی کہا جاتا ہے}\n39۔ شوپھام کا، شوفامائیوں کا خاندان: ہوفام کا خاندان، ہوفامائیوں کا خاندان۔ {شفہم... ہپھام: جسے مپیم اور ہپیم بھی کہا جاتا ہے}\n40۔ اور بیلا کے بیٹے ارد اور نعمان تھے: {ارد} کے، جو اردیت خاندان کا خاندان تھا؛ {اور} نعمان کے، نامی خاندان۔ {آرد: جسے آدار بھی کہا جاتا ہے}\n41۔ یہ {ہیں} بنیامین کے بیٹے ان کے خاندانوں کے مطابق: اور جن میں سے ان کی تعداد تھی وہ چالیس پانچ ہزار چھ سو تھے۔\n42. یہ دان کے بیٹے ہیں، ان کے خاندانوں کے بعد: شوہام کے، شوہامی خاندان کے۔ یہ {ہیں} ڈین کے خاندانوں کے بعد ان کے خاندانوں کے بعد۔ {شوہم: یا، ہشیم}\n43۔ شوہامیوں کے تمام خاندان، جن میں شمار کیا گیا تھا، تین سو چار ہزار چار سو تھے۔\n44۔ {Of} آشر کے بچوں کے خاندانوں کے بعد: جمنا کے، جمنیوں کا خاندان: یسوعی کے، یسوعیوں کا خاندان: بریاہ کا، بیرائیٹس کا خاندان۔\n45۔ بریاہ کے بیٹوں میں: ہیبر کے، ہیبرائی خاندان کا: مالکیئل کا، مالکیلائٹس کا خاندان۔\n46۔ اور آشر کی بیٹی کا نام سارہ تھا۔\n47۔ یہ آشر کے بیٹوں کے خاندان ہیں جو ان میں شمار کیے گئے تھے؛ {جو تھے} پچاس تین ہزار چار سو۔\n48۔ نفتالی کے بیٹے ان کے خاندانوں کے بعد: جہزیل کے، جہزیلائٹس کے خاندان: گونی کے، گنائٹس کے خاندان:\n49۔ جیزر کے، جیزیری خاندان کا: شلیم کا، شلیمائٹس کا خاندان۔ {شلم: جسے شلم بھی کہا جاتا ہے}\n50۔ یہ نفتالی کے خاندان ہیں ان کے خاندانوں کے مطابق: اور جن میں شمار کیا گیا وہ چالیس پانچ ہزار چار سو تھے۔\n51. یہ {تھے} بنی اسرائیل کے شمار شدہ، چھ لاکھ اور ایک ہزار سات سو تیس۔\n52۔ اور خداوند نے موسیٰ سے کہا،\n53۔ ان میں زمین وراثت کے لیے ناموں کی تعداد کے مطابق تقسیم کی جائے گی۔\n54۔ تم بہت سے لوگوں کو زیادہ وراثت دو گے، اور کم وراثت کو چند کو دو گے: ہر ایک کو اس کی وراثت ان لوگوں کے مطابق دی جائے گی جو اس کے گنے گئے۔ {مزید دیں...: عبوری۔ اس کی وراثت کو ضرب دو} {کم دو...: عبرانی۔ اس کی وراثت کو کم کرنا}\n55۔ اگرچہ زمین قرعہ اندازی کے ذریعے تقسیم کی جائے گی: ان کے باپ اجداد کے قبائل کے ناموں کے مطابق جو وہ وارث ہوں گے۔\n56۔ اس پلاٹ کے مطابق اس کی ملکیت کو بہت سے اور چند میں تقسیم کیا جائے گا۔\n57۔ اور یہ وہ لوگ ہیں جنہیں لاویوں کے خاندانوں کے نام پر شمار کیا گیا: گرشون کے، گرشونیوں کا خاندان؛ کوہات کے، کوہتیوں کا خاندان: مراری کے، مراریوں کا خاندان۔\n58۔ یہ لاویوں کے خاندان ہیں: لبنائیوں کا خاندان، حبرونیوں کا خاندان، محلیوں کا خاندان، مشیوں کا خاندان، قراطیوں کا خاندان۔ اور کوہات نے امرم کو جنم دیا۔\n59۔ اور عمرم کی بیوی کا نام یوکبید تھا، جو لاوی کی بیٹی تھی، جسے [اس کی ماں} نے مصر میں لاوی کو جنم دیا؛ اور اس نے امریم ہارون اور موسیٰ اور ان کی بہن مریم کو جنم دیا۔\n60۔ اور ہارون سے ناداب، ابیہو، الیعازر اور ایثمار پیدا ہوئے۔\n61۔ اور نداب اور ابیہو مر گئے، جب انہوں نے خداوند کے سامنے عجیب آگ پیش کی۔\n62۔ اور ان میں سے جو گنے گئے وہ بیس تین ہزار تھے، سب ایک ماہ کے مرد اور اس سے اوپر، کیونکہ وہ بنی اسرائیل میں شمار نہیں ہوئے کیونکہ انہیں بنی اسرائیل میں کوئی وراثت نہیں دی گئی تھی۔\n63۔ یہ وہ لوگ ہیں جنہیں موسیٰ اور الیعزر کاہن نے گنا تھا، جنہوں نے موآب کے میدانوں میں یردن کے قریب یریحو کے قریب بنی بنی اسرائیل کو گنا تھا۔\n64۔ لیکن ان میں سے کوئی ایسا آدمی نہیں تھا جسے موسیٰ اور ہارون کاہن نے گنتی کی ہو جب وہ سینا کے بیابان میں بنی اسرائیل کو شمار کرتے تھے۔\n65۔ کیونکہ خداوند نے ان کے بارے میں کہا تھا، وہ ضرور صحرا میں مریں گے۔ اور ان میں سے کوئی بھی بچا نہیں، سوائے کیلب جو یپھنہ کا بیٹا تھا، اور یشوع نون کا بیٹا۔","1۔ پھر زیلوفحاد کی بیٹیاں آئیں، جو حفار کا بیٹا تھا، گلعاد کا بیٹا، ماکیر کا بیٹا، منشا کا بیٹا، منسہ کے بیٹے یوسف کے خاندانوں سے: اور یہ اس کی بیٹیوں کے نام ہیں؛ مہلہ، نوح، اور ہوگلہ، اور ملکاہ، اور تیرزاہ۔\n2۔ اور وہ موسیٰ کے سامنے، اور الیعازر کاہن کے سامنے، اور شہزادوں اور تمام جماعت کے سامنے، جماعت کے خیمہ کے دروازے کے پاس کھڑے ہو کر بولے،\n3۔ ہمارا باپ ویرانے میں مرا، اور وہ ان لوگوں کے ساتھ نہیں تھا جو خداوند کے خلاف کورہ کی جماعت میں جمع ہوئے؛ لیکن اپنے ہی گناہ میں فوت ہو گیا، اور اس کے کوئی بیٹے نہیں ہوئے۔\n4. ہمارے والد کا نام ان کے خاندان میں کیوں مٹا دیا جائے، کیونکہ ان کا کوئی بیٹا نہیں؟ ہمیں {لہٰذا} ہمارے باپ کے بھائیوں میں ایک ملکیت دے دے۔ {ہو گیا...: عبرانی۔ کم ہو گیا}\n5۔ اور موسیٰ نے ان کا مقصد خداوند کے سامنے پیش کیا۔\n6۔ اور خداوند نے موسیٰ سے کہا،\n7۔ زیلوفہاد کی بیٹیاں درست بولتی ہیں: تم یقینا انہیں ان کے والد کے بھائیوں میں وراثت کی ملکیت دو گے؛ اور تم ان کے والد کی وراثت انہیں منتقل کرو گے۔\n8۔ اور تم بنی اسرائیل سے کہو کہ، اگر کوئی مر جائے اور اس کا کوئی بیٹا نہ ہو، تو تم اس کی وراثت اس کی بیٹی کو منتقل کرو گے۔\n9۔ اور اگر اس کی کوئی بیٹی نہ ہو، تو تم اس کی وراثت اس کے بھائیوں کو دے دو۔\n10۔ اور اگر اس کے کوئی بھائی نہیں ہیں، تو تم اس کی وراثت اس کے والد کے بھائیوں کو دے دو۔\n11۔ اور اگر اس کے باپ کے کوئی بھائی نہ ہوں، تو تم اس کی وراثت اس کے خاندان کے اس رشتہ دار کو دے دو جو اس کے ساتھ ہے، اور وہ اسے حاصل کرے گا: اور یہ بنی اسرائیل کے لیے ایک قانون ہوگا، جیسا کہ خداوند نے موسیٰ کو حکم دیا تھا۔\n12۔ اور خداوند نے موسیٰ سے کہا، اس اباریم پہاڑ پر چڑھو اور اس زمین کو دیکھو جو میں نے بنی اسرائیل کو دی ہے۔\n13۔ اور جب تم اسے دیکھو گے، تو تم بھی اپنی قوم کے پاس جمع ہو جاؤ گے، جیسے ہارون تمہارا بھائی جمع کیا گیا تھا۔\n14۔ کیونکہ تم نے میرے حکم کے خلاف بغاوت کی جو زن کے صحرا میں، جماعت کے جھگڑے میں، مجھے ان کی آنکھوں کے سامنے پانی کے پاس مقدس کرنے کے لیے کیا: یعنی قدیش میں مریبہ کا پانی جو زین کے بیابان میں ہے۔\n15۔ اور موسیٰ نے خداوند سے کہا،\n16۔ خداوند جو تمام جسموں کی روحوں کا خدا ہے، جماعت پر ایک آدمی مقرر کرے،\n17۔ جو ان کے سامنے جا سکتا ہے، اور جو ان کے سامنے جا سکتا ہے، اور جو انہیں باہر لے جا سکتا ہے، اور جو انہیں اندر لا سکتا ہے؛ کہ خداوند کی جماعت بھیڑوں کی طرح نہ ہو جن کا چرواہا نہ ہو۔\n18۔ اور خداوند نے موسیٰ سے کہا، نون کے بیٹے یشوع کو لے لو، جو روح میں ہے، اور اپنا ہاتھ اس پر رکھو؛\n19۔ اور اسے الیعزر پادری کے سامنے اور تمام جماعت کے سامنے رکھ دو؛ اور انہیں ان کی نظر میں چارج دے دیں۔\n20۔ اور تم اپنی عزت کا کچھ حصہ اس پر رکھو، تاکہ بنی اسرائیل کی تمام جماعت فرمانبردار رہے۔\n21۔ اور وہ الیعزر کاہن کے سامنے کھڑا ہوگا، جو اوریم کے فیصلے کے بعد خداوند کے سامنے اس کے لیے مشورہ طلب کرے گا: اس کے کلام پر وہ باہر جائیں گے، اور اس کے کلام پر وہ اندر آئیں گے، دونوں، وہ اور اس کے ساتھ تمام بنی اسرائیل، حتیٰ کہ تمام جماعت بھی۔\n22۔ اور موسیٰ نے خداوند کے حکم کے مطابق عمل کیا: اور اس نے یشوع کو لے کر اسے الیعزر کاہن کے سامنے اور تمام جماعت کے سامنے رکھا:\n23۔ اور اس نے اس پر ہاتھ رکھے اور اسے حکم دیا، جیسا کہ خداوند نے موسیٰ کے ہاتھ سے حکم دیا تھا۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل کو حکم دو، اور انہیں کہے، میری قربانی، {اور} میری روٹی جو آگ میں دی گئی قربانیوں کے بدلے ہے، {کیونکہ یہ میرے لیے ایک میٹھا ذائقہ ہے} کہ تم اپنے وقت پر مجھے پیش کرو گے۔ {ایک میٹھا...: عبرانی۔ میرے آرام کا ذائقہ}\n3۔ اور تم ان سے کہو گے، یہ وہ قربانی ہے جو تم آگ سے دی گئی ہے جو تم خداوند کو پیش کرو گے؛ پہلے سال کے دو میمنے بغیر داغ کے دن بہ دن، {ایک مسلسل جلانے کی قربانی} کے لیے۔ {دن بہ دن: عبرانی۔ ایک دن میں}\n4۔ ایک بھیڑ صبح پیش کرو گے، اور دوسرا بھیڑ کو برابر وقت پر؛ {جفت پر: عبدی۔ دونوں شاموں کے درمیان}\n5۔ اور گوشت کی قربانی کے طور پر آٹے کا ایک دسواں حصہ، چوتھے حصے کے ساتھ ملا کر ایک ہین تیل کے۔\n6. {یہ} ایک مسلسل جلنے والی قربانی ہے، جو پہاڑ سینا میں میٹھے ذائقے کے لیے مقرر کی گئی تھی، ایک قربانی جو آگ سے خداوند کے لیے دی جاتی ہے۔\n7۔ اور اس کی شراب کی قربانی ایک ہی برہنے کے لیے ہین کا چوتھا حصہ ہوگی: مقدس جگہ پر تو مضبوط شراب خداوند کو ایک نذرانہ کے طور پر ڈالے گا۔\n8۔ اور دوسرا بھیڑ تم صبح کے گوشت کی قربانی کے طور پر پیش کرو گے، اور اس کی نذرانہ کے طور پر، تم اسے آگ سے دی گئی قربانی پیش کرو گے، جو خداوند کے لیے میٹھا ذائقہ ہے۔\n9۔ اور ہفتہ کے دن پہلے سال کے دو بکرے، بغیر داغ کے، اور دو دسویں حصے آٹے کے ایک گوشت کی نذرانہ کے لیے، تیل اور اس کی نذرانہ کے ساتھ:\n10۔ {یہ} ہر سبت کی جلتی ہوئی قربانی ہے، مسلسل جلنے والی قربانی اور اس کی شراب کی پیشکش۔\n11۔ اور اپنے مہینوں کے آغاز میں تم خداوند کے لیے سلائی ہوئی قربانی پیش کرو گے؛ دو نوجوان بیل، اور ایک مینڈھا، پہلے سال کے سات بھیڑ بغیر داغ کے؛\n12۔ اور ایک بیل کے لیے گوشت کی نذرانہ کے لیے تین دسویں حصے آٹے کے لیے؛ اور ایک مینڈھے کے لیے گوشت کی نذرانہ کے لیے دو دسویں حصے آٹے کے لیے؛\n13۔ اور تیل کے ساتھ ملائے ہوئے آٹے کا چند دسویں حصہ ایک گوشت کی قربانی کے لیے؛ ایک میٹھے ذائقے کی جلتی ہوئی قربانی، ایک قربانی جو آگ کے ذریعے خداوند کے لیے دی گئی۔\n14۔ اور ان کی شراب کی نذرانہ بیل کے لیے آدھی ہین شراب ہوگی، اور تیسری ہین کا حصہ مینڈھے کو، اور چوتھی ہین کا حصہ بھیڑ کے لیے: یہ ہر مہینے سال کے مہینوں میں سلائی کی قربانی ہے۔\n15۔ اور بکریوں کا ایک بچہ خداوند کے سامنے گناہ کی قربانی کے طور پر پیش کیا جائے گا، اس کے ساتھ مسلسل جلنے والی قربانی اور اس کی شراب کی قربانی کے ساتھ۔\n16۔ اور پہلے مہینے کے چودہویں دن خداوند کا پاس اوور ہے۔\n17۔ اور اس مہینے کے پندرہویں دن عید ہے: سات دن بغیر خمیر کی روٹی کھائی جائے گی۔\n18۔ پہلے دن {ہوگا} ایک مقدس اجلاس ہوگا؛ تم کسی بھی قسم کا غلامی کا کام نہیں کرو گے:\n19۔ لیکن تم آگ سے دی گئی قربانی پیش کرو گے {بطور جلانے والی قربانی} خداوند کے لیے؛ دو نوجوان بیل، ایک مینڈھا، اور پہلے سال کے سات بھیڑے: یہ تمہارے لیے بے داغ ہوں گے:\n20۔ اور ان کی گوشت کی قربانی آٹے اور تیل کے ساتھ ملائی ہوئی ہوگی: تین دسویں سودے بیل کے بدلے اور دو دسویں سودے ایک مینڈھے کے لیے؛\n21۔ ہر برہنے کے لیے سات میمنوں میں کئی دسویں سودا پیش کرو:\n22۔ اور ایک بکری گناہ کی قربانی کے بدلے، تاکہ تمہارے لیے کفارہ ہو۔\n23۔ آپ انہیں صبح کے وقت جلنے والی قربانی کے ساتھ پیش کریں گے، جو کہ مسلسل جلنے والی قربانی کے لیے ہے۔\n24۔ اس طرح تم روزانہ، سات دنوں میں، آگ میں دی گئی قربانی کا گوشت، جو خداوند کے لیے میٹھا ذائقہ ہے، پیش کرو گے: یہ مسلسل جلنے والی قربانی اور اس کی شراب کی قربانی کے ساتھ پیش کی جائے گی۔\n25۔ اور ساتویں دن آپ کو مقدس اجلاس ملے گا؛ تم کوئی غلامی کا کام نہیں کرو گے۔\n26۔ اور پہلے پھلوں کے دن، جب آپ خداوند کے لیے نئی گوشت کی قربانی لائیں گے، ہفتوں کے بعد {باہر نکلیں} تو آپ کو مقدس اجلاس ملے گا؛ تم کوئی غلامی کا کام نہیں کرو گے:\n27. لیکن تم جلنے والی قربانی کو خدا کے سامنے میٹھے ذائقے کے طور پر پیش کرو گے؛ دو نوجوان بیل، ایک مینڈھا، پہلے سال کے سات بھیڑے؛\n28۔ اور ان کے گوشت کی پیشکش آٹے کے تیل کے ساتھ ملائی ہوئی، تین دسویں حصہ ایک بیل کو دیا جاتا ہے، دو دسویں حصے ایک مینڈھے کو،\n29۔ سات بکروں میں ایک بکری کے لیے کئی دسویں تقسیم ہوتی ہے؛\n30۔ {اور} ایک بکریوں کا بچہ، تمہارے لیے کفارہ بنانے کے لیے۔\n31. تم مسلسل جلنے والی قربانی کے ساتھ اور اس کے گوشت کی قربانی (جو تمہارے لیے بے عیب ہوں گی) اور ان کے شراب کے نذرانہ پیش کرو گے۔","1۔ اور ساتویں مہینے میں، مہینے کے پہلے {دن} کو، آپ کی مقدس تقریب ہوگی؛ تم کوئی غلامی نہیں کرو گے: آج تمہیں بگل بجانے کا دن ہے۔\n2۔ اور تم خداوند کے لیے میٹھے ذائقے کے طور پر جلنے والی قربانی پیش کرو گے؛ ایک نوجوان بیل، ایک مینڈھا، {اور} پہلے سال کے سات بلا داغ بکرے:\n3۔ اور ان کی گوشت کی قربانی آٹے کے تیل کے ساتھ ملائی ہوگی، بیل کے لیے تین دسویں سودا، اور دو دسویں سودے ایک مینڈھے کے لیے،\n4۔ اور ایک بکری کے لیے ایک دسواں سودا، سات بکروں میں:\n5۔ اور ایک بکریوں کا بچہ {گناہ کی قربانی} کے لیے، تاکہ آپ کے لیے کفارہ ہو سکے:\n6۔ مہینے کی جلنے والی قربانی، اس کے گوشت کی قربانی، اور روزانہ کی جلنے والی قربانی، اور اس کی گوشت کی قربانی، اور ان کے شراب کی نذرانے کے ساتھ، ان کے انداز کے مطابق، ایک میٹھے ذائقے کے طور پر، جو آگ سے خداوند کے لیے قربان کی جاتی ہے۔\n7۔ اور آپ اس ساتویں مہینے کے دسویں دن ایک مقدس اجلاس منائیں گے؛ اور تم اپنی جانوں کو تکلیف دو گے: تم وہاں کوئی کام نہیں کرو گے:\n8۔ لیکن تم خداوند کے سامنے ایک میٹھا ذائقہ کے طور پر جلنے کی قربانی پیش کرو گے؛ ایک نوجوان بیل، ایک مینڈھا، {اور} پہلے سال کے سات بھیڑے؛ وہ تمہارے لیے بے داغ ہوں گے:\n9۔ اور ان کا گوشت کا تحفہ آٹے کا ہوگا جس میں تیل ملا ہو، بیل کو تین دسویں سودا، اور ایک مینڈھے کے لیے دو دسویں سودا،\n10۔ سات بکروں میں ایک بکری کے لیے کئی دسویں سودا:\n11۔ بکریوں کا ایک بچہ {گناہ کی قربانی} کے لیے؛ کفارے کی گناہ کی نذرانے کے علاوہ، مسلسل جلنے کی قربانی، گوشت کی قربانی، اور ان کے مشروبات کی نذرانے کے علاوہ۔\n12۔ اور ساتویں مہینے کی پندرہویں تاریخ کو آپ کو مقدس اجلاس ملے گا؛ تم کوئی غلامی نہیں کرو گے، اور سات دن خداوند کے لیے دعوت مناؤ گے:\n13۔ اور تم خداوند کے لیے آگ سے دیے گئے سجلنے والی قربانی پیش کرو گے، جو میٹھا ذائقہ ہے؛ تیرہ نوجوان بیل، دو مینڈے، {اور} پہلے سال کے چودہ بکرے؛ وہ بے داغ ہوں گے:\n14۔ اور ان کی گوشت کی قربانی آٹے کے تیل کے ساتھ ملائی ہوگی، تیرہ بیلوں کے ہر بیل کو تین دسویں تقسیم کی جائے گی، ہر مینڈھے کے لیے دو دسویں تقسیم کی جائیں گی،\n15۔ اور چودہ بکروں میں سے ہر بکری کو کئی دسویں تقسیم کریں:\n16۔ اور ایک بکریوں کا بچہ {گناہ کی قربانی} کے لیے؛ مسلسل جلتی ہوئی قربانی، گوشت کی قربانی، اور شراب کی قربانی کے علاوہ۔\n17۔ اور دوسرے دن بارہ نوجوان بیل، دو مینڈے، اور پہلے سال کے چودہ بکری بغیر داغ کے پیش کریں:\n18۔ اور ان کے گوشت کی قربانی اور ان کی شراب کی قربانیاں بیلوں، مینڈوں اور بھیڑوں کے لیے ان کی تعداد کے مطابق ہوں گی، اس طرح کہ:\n19۔ اور بکریوں کا ایک بچہ {گناہ کی قربانی} کے لیے؛ مسلسل جلانے والی قربانی، گوشت کی قربانی، اور ان کے مشروبات کی قربانیوں کے علاوہ۔\n20۔ اور تیسرے دن گیارہ بیل، دو مینڈے، چودہ برہ پہلے سال کے بے عیب بکر؛\n21۔ اور ان کے گوشت کی قربانی اور ان کے شراب کی قربانیاں بیلوں، مینڈوں اور بھیڑوں کے لیے ان کی تعداد کے مطابق، اس طرح ہوں گی:\n22۔ اور ایک بکری {ایک گناہ کی قربانی}؛ مسلسل جلتی ہوئی قربانی، گوشت کی پیشکش، اور شراب کی قربانی کے علاوہ۔\n23۔ اور چوتھے دن دس بیل، دو مینڈے، {اور} پہلے سال کے چودہ بھیڑ بغیر کسی داغ کے:\n24۔ ان کی گوشت کی قربانی اور ان کی شراب کی نذرانے بیلوں، مینڈوں اور بھیڑوں کے لیے، ان کی تعداد کے مطابق، اس طرح ہوں گے:\n25۔ اور بکریوں کا ایک بچہ {گناہ کی قربانی} کے لیے؛ مسلسل جلتی ہوئی قربانی، گوشت کی قربانی، اور شراب کی قربانی کے علاوہ۔\n26۔ اور پانچویں دن نو بیل، دو مینڈے، {اور} پہلے سال کے چودہ بچھڑے بغیر داغ کے:\n27۔ اور ان کے گوشت کی قربانی اور شراب کی نذرانے بیلوں، مینڈوں اور بھیڑوں کے لیے، ان کی تعداد کے مطابق، اس طرح کے طور پر:\n28۔ اور ایک بکری {گناہ کی قربانی} کے لیے؛ مسلسل جلتی ہوئی قربانی، گوشت کی پیشکش، اور شراب کی قربانی کے علاوہ۔\n29۔ اور چھٹے دن آٹھ بیل، دو مینڈے، {اور} پہلے سال کے چودہ بھیڑ بغیر کسی داغ کے:\n30۔ اور ان کے گوشت کی قربانی اور ان کے مشروبات بیلوں، مینڈوں اور بھیڑوں کے لیے ان کی تعداد کے مطابق ہوں گے، اس طرح کے مطابق:\n31۔ اور ایک بکری {گناہ کی قربانی} کے لیے؛ مسلسل جلتی ہوئی قربانی، گوشت کی قربانی، اور شراب کی قربانی کے علاوہ۔\n32۔ اور ساتویں دن سات بیل، دو مینڈے، {اور} پہلے سال کے چودہ بھیڑ بغیر کسی داغ کے:\n33۔ اور ان کے گوشت کی قربانی اور ان کے مشروبات بیلوں، مینڈوں اور بھیڑوں کے لیے ان کی تعداد کے مطابق ہوں گے، اس طرح کہ:\n34۔ اور ایک بکری {گناہ کی قربانی} کے لیے؛ مسلسل جلتی ہوئی قربانی، گوشت کی قربانی، اور شراب کی قربانی کے علاوہ۔\n35۔ آٹھویں دن آپ کو ایک سنجیدہ اجتماع ہوگا: آپ وہاں کوئی غلامی کا کام نہیں کریں گے:\n36۔ لیکن تم ایک جلنے والی قربانی پیش کرو گے، جو آگ سے دی گئی قربانی ہو، ایک میٹھا ذائقہ ہو: ایک بیل، ایک مینڈھا، پہلے سال کے سات بلا داغ:\n37۔ ان کے گوشت کی قربانی اور ان کے شراب کی نذرانہ بیل، مینڈھے اور بھیڑوں کے لیے ان کی تعداد کے مطابق ہوں گی، اس طرح:\n38۔ اور ایک بکری {ایک گناہ کی قربانی} کے لیے؛ مسلسل جلتی ہوئی قربانی، گوشت کی پیشکش، اور شراب کی قربانی کے علاوہ۔\n39۔ یہ وہ {چیز} جو تم خداوند کے ساتھ اپنے مقررہ تہواروں میں، اپنی قسموں کے علاوہ، اپنی آزاد مرضی کی نذرانے کے علاوہ، اپنے جلنے والے نذراں، گوشت کی قربانیوں، اور اپنے شراب کی قربانیوں کے لیے، اور تمہاری صلح کی نذرانے کے لیے کرو گے۔ {کرو: یا، پیشکش کرو}\n40۔ اور موسیٰ نے بنی اسرائیل کو وہ سب کچھ بتایا جو خداوند نے موسیٰ کو حکم دیا تھا۔","1۔ اور موسیٰ نے قبائل کے سربراہوں سے بنی اسرائیل کے بارے میں کہا، کہا، یہ وہ چیز ہے جس کا خداوند نے حکم دیا ہے۔\n2۔ اگر کوئی شخص خداوند سے عہد کرے، یا اپنی روح کو بندھن سے باندھنے کی قسم کھائے؛ وہ اپنا وعدہ نہیں توڑے گا، وہ اپنی زبان سے نکلنے والی ہر چیز کے مطابق کرے گا۔ {وقفہ: عبوری۔ گستاخ}\n3۔ اگر کوئی عورت بھی خداوند سے عہد کرے اور اپنے والد کے گھر میں جوانی میں بندھے؛\n4۔ اور اس کے والد نے اس کی قسم اور اس کی روح کے بندھن کو سنے، اور اس کا باپ اس کے خلاف خاموش رہتا: پھر اس کے تمام عہد قائم رہیں گے، اور ہر بندھن جس سے اس نے اپنی روح باندھی ہے، قائم رہے گا۔\n5۔ لیکن اگر اس کا والد اس دن اجازت نہ دے جب وہ سنتا ہے؛ اس کی کوئی قسم، یا اس کے بندھن جن سے اس نے اپنی روح باندھی ہے، قائم نہیں رہے گا: اور خداوند اسے معاف کرے گا، کیونکہ اس کے والد نے اسے اجازت نہیں دی۔\n6۔ اور اگر اس کا شوہر ہوتا، جب وہ قسم کھاتی، یا اپنے ہونٹوں سے کوئی لفظ نکالتی، جس سے اس کی روح باندھی ہوتی؛ {اس نے وعدہ کیا: عبرانی۔ اس کے وعدے اس پر آ چکے تھے}\n7۔ اور اس کے شوہر نے سنا اور اس دن اس پر خاموش رہا: تب اس کے عہد قائم رہیں گے، اور اس کے بندھن جو اس نے اپنی روح سے بندھے تھے قائم رہیں گے۔\n8۔ لیکن اگر اس کا شوہر اس دن اسے اجازت نہ دے جس دن اس نے سنا؛ پھر وہ اس کی وہ قسم کرے گا جو اس نے وعدہ کیا تھا، اور جو اس نے اپنے ہونٹوں سے کہا، جس سے اس نے اپنی روح باندھی، بے اثر ہوگا: اور خداوند اسے معاف کرے گا۔\n9۔ لیکن بیوہ اور طلاق یافتہ عورت کی ہر قسم جس سے انہوں نے اپنی روحیں باندھی ہیں، اس کے خلاف کھڑی ہوگی۔\n10۔ اور اگر اس نے اپنے شوہر کے گھر میں قسم کھائی ہو، یا اپنی روح کو قسم کے بندھن سے باندھی ہو؛\n11۔ اور اس کے شوہر نے سنا، اور اس پر خاموشی اختیار کی، {اور} اسے منع نہیں کیا: پھر اس کے تمام عہد قائم رہیں گے، اور ہر بندھن جس سے اس نے اپنی روح باندھی ہے، قائم رہے گا۔\n12۔ لیکن اگر اس کے شوہر نے انہیں اس دن مکمل طور پر منسوخ کر دیا جس دن اس نے سنا؛ تو جو کچھ اس کے منہ سے اس کے وعدوں یا اس کی روح کے بندھن کے بارے میں نکلا وہ قابل قبول نہیں ہوگا: اس کا شوہر انہیں منسوخ کر چکا ہے؛ اور خداوند اسے معاف کرے گا۔\n13۔ ہر قسم اور ہر پابند قسم جو روح کو تکلیف دے گی، اس کا شوہر اسے قائم کر سکتا ہے، یا شوہر اسے کالعدم کر سکتا ہے۔\n14۔ لیکن اگر اس کا شوہر دن بہ دن اس کے ساتھ مکمل طور پر خاموش رہے؛ پھر وہ اس کے تمام عہد یا اس کے تمام بندھن قائم کرتا ہے جو اس پر ہیں: وہ انہیں تصدیق کرتا ہے، کیونکہ اس نے اس دن اس پر خاموشی اختیار کی تھی جب اس نے انہیں سنا۔\n15۔ لیکن اگر وہ کسی طرح انہیں منسوخ کر دے جب اس نے سنا {ان}؛ پھر وہ اس کی بدکاری برداشت کرے گا۔\n16. یہ وہ قوانین ہیں جو خداوند نے موسیٰ کو حکم دیے، مرد اور اس کی بیوی کے درمیان، باپ اور بیٹی کے درمیان، جو ابھی جوانی میں اپنے باپ کے گھر میں تھی۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ مدیانیوں کے بنی اسرائیل کا بدلہ لو: بعد میں تم اپنے لوگوں کے پاس جمع ہو جاؤ گے۔\n3۔ اور موسیٰ نے لوگوں سے کہا، کہ اپنے کچھ لوگوں کو جنگ کے لیے مسلح کرو، اور انہیں مدیانی لوگوں کے خلاف جانے دو، اور مدیان کے رب کا بدلہ لو۔\n4۔ ہر قبیلے میں سے ہزار، اسرائیل کے تمام قبائل میں، تم جنگ کے لیے بھیجو گے۔ {of...: عبرانی ایک قبیلے کا ہزار، ایک قبیلے کا ایک ہزار}\n5۔ تو ہزاروں اسرائیلیوں میں سے ایک ہزار {ہر قبیلے} سے، بارہ ہزار جنگ کے لیے مسلح آزاد ہوئے۔\n6۔ اور موسیٰ نے انہیں جنگ کے لیے بھیجا، ہر قبیلے کے ہزاروں لوگ، وہ اور فینیحاس، جو الیعزر کاهن کا بیٹا تھا، جنگ کے لیے، مقدس آلات اور ہاتھ میں بجانے کے لیے بگل لے کر۔\n7۔ اور انہوں نے مدیانیوں کے خلاف جنگ کی، جیسا کہ خداوند نے موسیٰ کو حکم دیا؛ اور انہوں نے تمام مردوں کو مار ڈالا۔\n8۔ اور انہوں نے مدیان کے بادشاہوں کو قتل کر دیا، باقی مارے جانے والوں کے علاوہ؛ {یعنی}، ایوی، اور ریکم، اور زور، اور حور، اور ربا، مدیان کے پانچ بادشاہ: بلعام، جو بیور کا بیٹا بھی تھا، انہوں نے تلوار سے قتل کیا۔\n9۔ اور بنی اسرائیل نے مدیان کی تمام عورتوں اور ان کے چھوٹے بچوں کو قید کر لیا، اور ان کے تمام مویشیوں، تمام مویشی اور تمام مال کا مال لے لیا۔\n10۔ اور انہوں نے اپنے تمام شہر جہاں وہ رہتے تھے، اور اپنے تمام خوبصورت قلعے آگ سے جلا دیے۔\n11۔ اور انہوں نے سارا مال غنیمت اور تمام شکار لے لیے، {انسانوں اور جانوروں کی} دونوں۔\n12۔ اور انہوں نے قیدیوں، شکار کو، اور مال غنیمت کو موسیٰ، الیعزر کاہن، اور بنی اسرائیل کی جماعت کو موآب کے میدانوں میں کیمپ میں لے گئے، جو اردن کے قریب یریحو کے قریب ہیں۔\n13۔ اور موسیٰ، الیعازر کاہن اور جماعت کے تمام شہزادے کیمپ کے بغیر ان سے ملنے نکلے۔\n14۔ اور موسیٰ لشکر کے افسران سے ناراض ہوا، ہزاروں سے زیادہ کپتانوں سے، اور سینکڑوں کپتانوں سے، جو جنگ سے آئے تھے۔ {جنگ: عبرانی۔ ہوسٹ آف وار}\n15۔ اور موسیٰ نے ان سے کہا، کیا تم نے تمام عورتوں کو زندہ بچا لیا؟\n16۔ دیکھو، ان واقعات نے بنی اسرائیل کو، بلعام کی نصیحت سے، پیور کے معاملے میں خداوند کے خلاف گناہ کرنے پر مجبور کیا، اور خداوند کی جماعت میں وبا پھیل گئی۔\n17۔ اب چھوٹوں میں سے ہر مرد کو مار دو، اور ہر عورت کو جو مرد کو جانتی ہے، اس کے ساتھ لیٹ کر مار دو۔ {وہ: عبرانی۔ ایک مرد}\n18۔ لیکن تمام عورتیں بچے، جو مرد کو اس کے ساتھ لیٹے ہوئے نہیں جانتیں، اپنے لیے زندہ رہیں۔\n19۔ اور تم سات دن کیمپ کے بغیر رہو: جس نے کسی کو قتل کیا اور جس نے کسی کو چھوا ہو، وہ تیسرے دن اور ساتویں دن اپنے اور اپنے قیدیوں کو پاک کرے۔\n20۔ اور اپنے تمام لباس، چمڑوں سے بنی ہر چیز، بکریوں کے بالوں کے تمام کام اور لکڑی کی تمام چیزوں کو پاک کرو۔ {وہ...: عببرانی۔ آلہ، یا، کھالوں کا برتن}\n21۔ اور الیعزر کاهن نے جنگ کے سپاہیوں سے کہا جو جنگ میں گئے، یہ وہ قانون ہے جس کا حکم خداوند نے موسیٰ کو دیا تھا؛\n22۔ صرف سونا، چاندی، پیتل، لوہا، ٹن اور سیسہ،\n23۔ جو بھی چیز آگ میں رہ سکتی ہے، تم اسے آگ میں گزارو گے، اور وہ صاف ہو جائے گی، لیکن وہ جدائی کے پانی سے پاک ہو جائے گی؛ اور جو کچھ بھی باقی نہیں رہتا، اسے تم پانی میں گزارو گے۔\n24۔ اور تم ساتویں دن اپنے کپڑے دھوؤ گے، پاک ہو جاؤ گے، اور پھر کیمپ میں آؤ گے۔\n25۔ اور خداوند نے موسیٰ سے کہا،\n26۔ شکار کی مقدار لے لو، {انسانوں اور جانوروں کے} دونوں، تو، اور الیعازر کاہن، اور جماعت کے بڑے بزرگ: {وہ...: عبرانی۔ قید کے بارے میں}\n27. اور شکار کو دو حصوں میں تقسیم کریں؛ ان کے درمیان جنہوں نے جنگ شروع کی، جو جنگ کے لیے نکلے، اور تمام جماعت کے درمیان:\n28۔ اور جنگ کے مردوں کے رب کو خراج وصول کرو: پانچ سو میں سے ایک جان، {دونوں} میں سے، بھی، بھیڑوں، بویشوں، گدھوں کی، اور بھیڑوں کی:\n29۔ ان کے آدھے حصے سے لے کر اسے الیعزر کاہن کو دے دو، {خدا کی طرف سے ایک نذرانہ کے طور پر۔\n30۔ اور بنی اسرائیل کی آدھی میں سے، تم پچاس میں سے ایک حصہ لے لو، جو انسانوں، بویشوں، گدھوں اور ریوڑوں کا حصہ ہے، اور انہیں لاویوں کو دے دو، جو خداوند کے خیمے کی حفاظت کرتے ہیں۔ {ریوڑ: یا، بکریاں}\n31۔ اور موسیٰ اور الیعزر کاهن نے خداوند کے حکم کے مطابق موسیٰ کو کیا۔\n32۔ اور وہ مال غنیمت، جو باقی شکار تھا جو جنگی مردوں نے پکڑا تھا، چھ لاکھ ستر ہزار پانچ ہزار بھیڑیں تھیں،\n33۔ اور 300 اور بارہ ہزار بویش،\n34۔ اور تین سو ہزار گدھے،\n35۔ اور کل تیس دو ہزار عورتیں تھیں جنہوں نے اس کے ساتھ لیٹ کر مرد کو نہیں جانا تھا۔\n36۔ اور آدھا حصہ، جو ان میں سے جنگ کے لیے نکلے، تین لاکھ سات تیس ہزار پانچ سو بھیڑیں تھے:\n37۔ اور خداوند کی طرف سے بھیڑوں کی خراج چھ سو تینٹھ پندرہ تھی۔\n38۔ اور گائے کے گوشت تیس چھ ہزار تھے؛ جن میں سے خداوند کا خراج {تھا} تین سو اور بارہ۔\n39۔ اور گدھے تیس ہزار پانچ سو تھے؛ جس میں خداوند کا خراج {تھا} تین سو اور ایک۔\n40۔ اور افراد کی تعداد سولہ ہزار تھی؛ جن میں خداوند کا خراج تیس اور دو افراد تھے۔\n41۔ اور موسیٰ نے وہ خراج دیا، جو خداوند کی قربانی تھی، الیعزر کاہن کو جیسا کہ خداوند نے موسیٰ کو حکم دیا تھا۔\n42۔ اور بنی اسرائیل کے نصف کے بارے میں، جنہیں موسیٰ نے ان لوگوں سے جدا کیا جو جنگ کر رہے تھے،\n43۔ (اب جماعت کا آدھا حصہ تین لاکھ تیس ہزار اور سات ہزار پانچ سو بھیڑیں تھے،\n44۔ اور چھتیس ہزار بوی،\nپینتالیس۔ اور تیس ہزار گدھے اور پانچ سو،\n46۔ اور سولہ ہزار افراد؛)\n47۔ حتیٰ کہ بنی اسرائیل کے نصف میں سے، موسیٰ نے پچاس میں سے ایک حصہ لیا، {انسانوں کا} اور جانور کا، اور لاویوں کو دے دیا، جو خداوند کے خیمہ کی ذمہ داری سنبھالتے تھے؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n48۔ اور وہ افسران جو لشکر کے ہزاروں سے زیادہ تھے، ہزاروں کے کپتان، اور سینکڑوں کے کپتان، موسیٰ کے قریب آئے:\n49۔ اور انہوں نے موسیٰ سے کہا، تیرے بندوں نے ہمارے زیر نگرانی جنگی سپاہیوں کی رقم لے لی ہے، اور ہم میں سے ایک بھی آدمی کی کمی نہیں ہے۔ {چارج: عبوری۔ ہاتھ}\n50۔ لہٰذا ہم نے خداوند کے لیے ایک قربانی پیش کی ہے، جو ہر انسان نے حاصل کیا ہے، سونے کے جواہرات، زنجیروں، کنگنوں، انگوٹھیوں، بالیاں، اور تختیوں سے، تاکہ خداوند کے سامنے ہماری روحوں کا کفارہ بنایا جا سکے۔ {حاصل ہوا: عبوری۔ مل گیا}\n51۔ اور موسیٰ اور الیعازر کاہن نے ان کا سونا لے لیا، {حتیٰ کہ} کہ سب جواہرات سے بنے ہوئے تھے۔\n52۔ اور خداوند کو پیش کیے گئے نذرانہ کا سارا سونا، ہزاروں کے کپتانوں اور سینکڑوں کے کپتانوں کا سولہ ہزار سات سو پچاس شیکل تھا۔ {پیشکش: عبدی۔ ہیو آفرز}\n53۔ ({کیونکہ} جنگ کے مردوں نے مال غنیمت حاصل کیا تھا، ہر آدمی اپنے لیے۔)\n54۔ اور موسیٰ اور الیعازر کاہن نے ہزاروں اور سینکڑوں کے کپتانوں کا سونا لے کر جماعت کے خیمے میں لے آیا، {لار} بنی اسرائیل کے لیے خداوند کے سامنے ایک یادگار کے طور پر۔","1۔ اب روبن کے بچوں اور گاد کے بچوں کے پاس بہت بڑی تعداد میں مویشی تھے: اور جب انہوں نے یازر کی زمین اور گلعاد کی زمین دیکھی، تو وہ جگہ مویشیوں کے لیے جگہ تھی؛\n2۔ گاد کے بچے اور روبن کے بچے آئے اور موسیٰ، الیعزر کاہن سے، اور جماعت کے شہزادوں سے کہا،\n3. عطاروت، اور دیبون، اور یعزر، اور نمرا، اور ہشبون، اور ایلیالہ، اور شیبام، اور نیبو، اور بیون، {نمرا: جسے بیت نیمرہ بھی کہا جاتا ہے} {شیبام: جسے شبمہ بھی کہا جاتا ہے} {بیون: جسے بعلمیون بھی کہا جاتا ہے}\n4. {حتی} وہ ملک جسے خداوند نے اسرائیل کی جماعت کے سامنے تباہ کیا، {ہے} مویشیوں کے لیے زمین ہے، اور تیرے بندوں کے پاس مویشی ہیں:\n5۔ چنانچہ، انہوں نے کہا، اگر ہم نے تمہاری نظر میں فضل پایا ہے تو یہ زمین تمہارے بندوں کو ملکیت کے طور پر دے دی جائے، {اور} ہمیں اردن کے پار نہ لے آؤ۔\n6۔ اور موسیٰ نے گاد کے بچوں اور روبن کے بچوں سے کہا، کیا تمہارے بھائی جنگ میں جائیں گے، اور کیا تم یہاں بیٹھو گے؟\n7۔ اور تم بنی اسرائیل کے دل کو اس زمین میں جانے سے کیوں روکتے ہو جو خداوند نے انہیں دی ہے؟ {حوصلہ شکن: عبرانی۔ بریک}\n8۔ تمہارے باپ نے بھی ایسا ہی کیا، جب میں نے انہیں کادیشبرنیا سے زمین دیکھنے بھیجا۔\n9۔ کیونکہ جب وہ اشکول کی وادی میں گئے اور زمین دیکھی، تو انہوں نے بنی اسرائیل کے دل کو مایوس کیا کہ وہ اس زمین میں نہ جائیں جو خداوند نے انہیں دی تھی۔\n10۔ اور خداوند کا غصہ اسی وقت بھڑکا، اور اس نے قسم کھائی، کہا،\n11۔ یقینا وہ لوگ جو مصر سے بیس سال کی عمر سے اور اس سے اوپر نکلے، وہ زمین نہیں دیکھیں گے جس کی میں نے ابراہیم، اسحاق اور یعقوب سے قسم کھائی ہے؛ کیونکہ انہوں نے مکمل طور پر میری پیروی نہیں کی: {مکمل طور پر...: عبرانی۔ میرے بعد مکمل ہوئی}\n12۔ کیلب کو بچا لو، جو یپھونہ کنزی کا بیٹا ہے، اور یشوع، نون کا بیٹا، کیونکہ وہ مکمل طور پر خداوند کی پیروی کر چکے ہیں۔\n13۔ اور خداوند کا غصہ اسرائیل کے خلاف بھڑک اٹھا، اور اس نے انہیں چالیس سال تک بیابان میں بھٹکنے پر مجبور کیا، یہاں تک کہ وہ تمام نسل جو خدا کے سامنے برے کام کر چکی تھی، ختم ہو گئی۔\n14۔ اور دیکھو، تم اپنے باپ دادا کی جگہ اٹھے ہو، گناہ گار لوگوں کی تعداد میں اضافہ، تاکہ خداوند کے اسرائیل کے خلاف شدید غصے کو مزید بڑھایا جا سکے۔\n15۔ کیونکہ اگر تم اس کے پیچھے منہ موڑ لو، تو وہ پھر انہیں بیابان میں چھوڑ دے گا؛ اور تم اس سب لوگوں کو تباہ کر دو گے۔\n16۔ اور وہ اس کے قریب آئے اور کہا، ہم یہاں اپنے مویشیوں کے لیے بھیڑوں کے باغ اور اپنے چھوٹے بچوں کے لیے شہر بنائیں گے:\n17۔ لیکن ہم خود اسرائیل کے بچوں کے سامنے مسلح ہو کر تیار ہوں گے، جب تک کہ ہم انہیں ان کی جگہ نہ لے آئیں: اور ہمارے بچے زمین کے باشندوں کی وجہ سے باڑ والے شہروں میں رہیں گے۔\n18۔ ہم اپنے گھروں کو واپس نہیں جائیں گے، جب تک کہ بنی اسرائیل ہر انسان کو اس کی میراث نہ دے دیں۔\n19۔ کیونکہ ہم ان کے ساتھ اردن کے کنارے یا آگے نہیں وراثت پائیں گے؛ کیونکہ ہماری میراث اس طرف اردن مشرق کی طرف ہمارے پاس آ گئی ہے۔\n20۔ اور موسیٰ نے ان سے کہا، اگر تم یہ کام کرو گے، اگر تم خداوند کے سامنے مسلح ہو کر جنگ میں جاؤ گے،\n21۔ اور تم سب اردن پر مسلح ہو کر خداوند کے سامنے جاؤں گا، جب تک کہ وہ اپنے دشمنوں کو اپنے سامنے سے نکال نہ دے،\n22۔ اور زمین خداوند کے سامنے مغلوب ہو جائے: پھر تم واپس آؤ گے، اور خداوند اور اسرائیل کے سامنے بے قصور رہو گے؛ اور یہ زمین خدا کے سامنے تمہاری ملکیت ہوگی۔\n23. لیکن اگر تم ایسا نہیں کرو گے، تو دیکھو، تم نے خداوند کے خلاف گناہ کیا ہے: اور یقین رکھو کہ تمہارا گناہ تمہیں پکڑ لے گا۔\n24۔ اپنے چھوٹے بچوں کے لیے شہر بناؤ، اور بھیڑوں کے لیے تہہ بناؤ؛ اور جو تمہارے منہ سے نکلا وہ کرو۔\n25۔ اور گاد کے بچے اور روبن کے بچے موسیٰ سے کہا، کہ تیرے بندے میرے رب کے حکم کے مطابق عمل کریں گے۔\n26۔ ہمارے ننھے بچے، ہماری بیویاں، ہمارے ریوڑ اور ہمارے تمام مویشی گلعاد کے شہروں میں ہوں گے:\n27. لیکن تمہارے بندے جنگ کے لیے مسلح ہر آدمی خداوند کے سامنے جنگ کے لیے گزریں گے، جیسا کہ میرے رب نے فرمایا۔\n28۔ تو ان کے بارے میں موسیٰ نے الیعزر کاہن، یشوع نون کے بیٹے، اور بنی اسرائیل کے قبائل کے بڑے بزرگوں کو حکم دیا:\n29۔ اور موسیٰ نے ان سے کہا، اگر گاد کے بچے اور روبن کے بچے تمہارے ساتھ اردن کے پار سے گزریں گے، تو ہر وہ آدمی جو جنگ کے لیے مسلح ہو کر، خداوند کے سامنے، اور زمین تمہارے سامنے مغلوب ہو جائے گی؛ پھر تم انہیں گلعاد کی زمین ملکیت کے طور پر دو گے:\n30۔ لیکن اگر وہ تم سے مسلح ہو کر نہیں گزریں گے، تو ان کے پاس کنعان کی سرزمین میں تمہارے درمیان جائیداد ہوگی۔\n31۔ اور گاد کے بچوں اور روبن کے بچوں نے جواب دیا، کہا، جیسے خداوند نے تیرے بندوں سے فرمایا ہے، ہم بھی کریں گے۔\n32. ہم خداوند کے سامنے مسلح ہو کر کنعان کی سرزمین میں جائیں گے، تاکہ اس طرف اردن کی ہماری میراث {ہو} جائے۔\n33۔ اور موسیٰ نے ان کو، حتیٰ کہ جاد کی اولاد کو، روبن کی اولاد کو، اور منسی کے آدھے قبیلے کو جو یوسف کا بیٹا تھا، اموری کے بادشاہ سیحون کی بادشاہت، اور اوگ بادشاہ باشان کی بادشاہی کو زمین، اس کے ساحلوں پر شہر اور ارد گرد کے شہر بھی دیے۔\n34۔ اور گاد کے بچوں نے دیبون، آتاروت اور آروئر کو تعمیر کیا،\n35. اور آتروتھ، شوفان، اور جازر، اور جوگبیہ، {یعازر: جسے یازر بھی کہا جاتا ہے}\n36۔ اور بیتھنیمرا، اور بیتھران، باڑ والے شہر: اور بھیڑوں کے لیے کھنڈے۔ {بیتھنیمرا: جسے نمراہ بھی کہا جاتا ہے}\n37۔ اور روبن کے بچوں نے ہشبون، ایلیالہ، اور کیرجاتائیم تعمیر کیے،\n38۔ اور نیبو، اور بعلمیون (ان کے نام بدل دیے گئے) اور شبمہ: اور انہوں نے ان شہروں کو دیگر نام دیے جو انہوں نے تعمیر کیے۔ {دیا گیا...: عببرانی۔ انہوں نے شہروں کے نام ناموں سے پکارے}\n39۔ اور مخر، منسی کے بیٹے کے بچے گلعاد گئے، اسے لے لیا، اور اس میں موجود اموری کو بے دخل کر دیا۔\n40۔ اور موسیٰ نے گلعاد مخر، منسی کے بیٹے کو دیا؛ اور وہ اسی میں رہتا تھا۔\n41۔ اور منسی کا بیٹا یائر گیا اور ان کے چھوٹے قصبے لے گئے اور انہیں ہووتجائر کہا۔\n42۔ اور نوباہ جا کر کنات اور اس کے دیہات پر قبضہ کیا اور اسے نوباہ کہا، اپنے نام پر۔","1. یہ وہ سفر ہیں جو بنی اسرائیل کے سفر تھے، جو اپنی فوجوں کے ساتھ موسیٰ اور ہارون کے ہاتھوں مصر کی سرزمین سے نکلے۔\n2۔ اور موسیٰ نے ان کے سفر کے مطابق خداوند کے حکم کے مطابق لکھا: اور یہ ان کے سفر ان کے جانے کے عمل کے مطابق ہیں۔\n3۔ اور وہ پہلے مہینے میں، پہلے مہینے کے پندرہویں دن رامسیس سے روانہ ہوئے؛ فسح کے بعد کل بنی اسرائیل نے تمام مصریوں کی نظر میں بلند ہاتھ کے ساتھ باہر نکل آئے۔\n4۔ کیونکہ مصریوں نے ان کے تمام پہلے بچے کو دفن کیا، جنہیں خداوند نے ان میں مارا تھا: ان کے دیوتاؤں پر بھی خداوند نے فیصلے کیے۔\n5۔ اور بنی اسرائیل نے رامسیس سے نکل کر سکوتھ میں زمین پر ڈالا۔\n6۔ اور وہ سکوتھ سے روانہ ہوئے، اور ایتھم میں رہے، جو جنگل کے کنارے واقع ہے۔\n7۔ اور وہ ایتھم سے ہٹ کر دوبارہ پیہاہیروتھ کی طرف مڑے، جو بعلزیفون سے پہلے ہے: اور وہ میگدول کے سامنے آ گئے۔\n8۔ اور وہ پیہاہیروت کے سامنے سے روانہ ہوئے، سمندر کے بیچ سے گزر کر صحرا میں چلے گئے، اور ایتھم کے ویرانے میں تین دن کا سفر کیا اور ماراہ میں اترے۔\n9۔ اور وہ مارا سے نکل کر ایلیم کے پاس آئے: اور ایلیم میں بارہ پانی کے چشمے اور تیس اور دس کھجور کے درخت تھے؛ اور انہوں نے وہاں پچنگ کی۔\n10۔ اور وہ ایلیم سے ہٹ گئے اور بحیرہ احمر کے کنارے خیمہ زن ہو گئے۔\n11۔ اور وہ بحیرہ احمر سے ہٹ کر گناہ کے بیابان میں خیمہ زن ہو گئے۔\n12۔ اور وہ گناہ کے بیابان سے نکل کر ڈوفکا میں خیمہ زن ہوئے۔\n13۔ اور وہ دوفکا سے روانہ ہوئے اور علوش میں خیمہ زن ہو گئے۔\n14۔ اور وہ علوش سے ہٹ کر ریفیدیم میں خیمہ زن ہو گئے، جہاں لوگوں کے لیے پانی نہیں تھا۔\n15۔ اور وہ ریفیدیم سے روانہ ہوئے، اور سینا کے ویرانے میں پھینک دیے۔\n16۔ اور وہ سینا کے صحرا سے نکل کر کیبروتھتاواہ پر زمین لگا دی۔ {کیبروتھٹاواہ: یعنی، ہوس کی قبریں}\n17۔ اور وہ کیبروتھتاوا سے روانہ ہوئے اور ہازیروت میں خیمہ زن ہو گئے۔\n18۔ اور وہ ہازیروت سے روانہ ہوئے، اور رتھما میں شامل ہوئے۔\n19۔ اور وہ رتھما سے روانہ ہوئے، اور رمونپاریز میں پچنگ کی۔\n20۔ اور وہ ریمونپاریز سے روانہ ہوئے، اور لیبنہ میں شامل ہوئے۔\n21۔ اور انہوں نے لبنہ سے ہٹ کر رساح پر پچنگ کی۔\n22۔ اور وہ رسا سے روانہ ہوئے اور کیہلتھا میں گدائی کی۔\n23۔ اور وہ کیہلاتھا سے گئے، اور ماؤنٹ شیفر کو پچ کیا۔\n24۔ اور وہ کوہ شافر سے اتر کر ہرادہ میں خیمہ زن ہو گئے۔\n25۔ اور وہ ہارادہ سے نکل کر ماکھیلوت میں زمین پر گئے۔\n26۔ اور وہ مخلوت سے ہٹ کر تہات میں خیمہ زن ہو گئے۔\n27۔ اور وہ تہات سے روانہ ہوئے، اور تارہ پر پچ کی۔\n28۔ اور وہ تارہ سے الگ ہو گئے، اور میتھکا کو شامل کیا۔\n29۔ اور وہ میتھکا سے گئے، اور ہشمونا کو شامل کیا۔\n30۔ اور وہ ہشمونہ سے روانہ ہوئے اور موسروتھ میں خیمہ زن ہو گئے۔\n31۔ اور وہ موسیروتھ سے روانہ ہوئے، اور بینیجاکان میں زمین پہنچائی۔\n32۔ اور وہ بینیجاکان سے نکل کر ہورہاگیگڈ میں خیمہ زن ہو گئے۔\n33۔ اور وہ ہورہاگیگڈ سے گئے اور جوتبتھا میں پچ کی۔\n34۔ اور وہ یوتبتھا سے ہٹ کر ایبرونہ میں خیمہ زن ہو گئے۔\n35۔ اور وہ ایبرونہ سے روانہ ہوئے اور ایزیونگابر میں خیمہ زن ہو گئے۔\n36۔ اور وہ ایزیونگابر سے نکل کر زین کے بیابان میں گدھے گئے، جو {قادش} ہے۔\n37۔ اور وہ قادیش سے ہٹ کر ہور پہاڑ میں زمین کے کنارے پر لنگر انداز ہوئے۔\n38۔ اور ہارون پادری خداوند کے حکم پر ہور پہاڑ پر چڑھا، اور وہیں فوت ہوا، جب بنی اسرائیل مصر کی سرزمین سے نکلے تھے، پانچویں مہینے کے پہلے دن میں۔\n39۔ اور ہارون ایک سو بیس تئیس سال کا تھا جب وہ کوہ ہور میں فوت ہوا۔\n40۔ اور بادشاہ عراد کنعانی، جو جنوب میں کنعان کی سرزمین میں رہتا تھا، نے بنی اسرائیل کی آمد کی خبر سنی۔\n41۔ اور وہ کوہ ہور سے روانہ ہوئے، اور زلمونا میں اترے۔\n42۔ اور وہ زلمونا سے روانہ ہوئے، اور پونون میں میدان میں گئے۔\n43۔ اور وہ پونون سے روانہ ہوئے، اور اوبوتھ میں رہے۔\n44۔ اور وہ اوبوت سے روانہ ہوئے اور موآب کی سرحد پر ایجباریم میں لٹکے رہے۔ {ایجاباریم: یا، اباریم کے ڈھیر}\n45۔ اور وہ ایم سے روانہ ہوئے، اور دیبونگڈ میں رہے۔\n46۔ اور وہ دیبونگڈ سے نکل کر المونڈبلثیم میں خیمہ زن ہو گئے۔\n47۔ اور وہ المندیبلثیم سے ہٹ کر اباریم کے پہاڑوں میں نیبو کے سامنے زمین پر چلے گئے۔\n48۔ اور وہ اباریم کے پہاڑوں سے روانہ ہوئے، اور اردن کے قریب یرحاق کے قریب موآب کے میدانوں میں زمین پر چڑھائی کی۔\n49۔ اور انہوں نے اردن کے پاس پھینکے، بیت جیسموت سے ابیلشتیم تک موآب کے میدانوں میں۔ {ایبلشٹم: یا، شتیم کے میدان}\n50۔ اور خداوند نے موسیٰ سے اردن کے قریب یریحو کے میدانوں میں موسیٰ سے کہا،\n51۔ بنی اسرائیل سے بات کرو، اور ان سے کہو، جب تم اردن کے پار کنعان کی سرزمین میں چلے جاؤ؛\n52۔ پھر تم زمین کے تمام باشندوں کو اپنے سامنے سے نکالو گے، ان کے تمام مجسمے تباہ کر دو گے، ان کے تمام پگھلے ہوئے مجسمے تباہ کر دو گے، اور ان کی تمام اونچی جگہوں کو مکمل طور پر گرا دو گے:\n53۔ اور تم زمین کے باشندوں کو بے دخل کرو گے، اور وہاں رہو گے: کیونکہ میں نے تمہیں زمین دی ہے تاکہ تم اس پر قبضہ کرو۔\n54۔ اور تم زمین کو قرعہ اندازی سے تقسیم کرو گے تاکہ اپنے خاندانوں میں وراثت حاصل کی جا سکے: {اور} جتنا زیادہ تم زیادہ وراثت دو گے، اور کم کو کم وراثت دو گے: ہر شخص کی {وراثت} اس جگہ ہوگی جہاں اس کا پلاٹ گرا ہوگا؛ اپنے باپ اجداد کے قبائل کے مطابق تم وارث بنو گے۔ {مزید دیں...: عبوری۔ اس کی وراثت کو ضرب دو} {کم دو...: عبرانی۔ اس کی وراثت کو کم کرنا}\n55۔ لیکن اگر تم زمین کے باشندوں کو اپنے سامنے سے نہیں نکالنا چاہتے؛ پھر یہ ہو جائے گا کہ جو کچھ تم ان سے بچاؤ گے وہ تمہاری آنکھوں میں چبھنے والے، تمہارے پہلوؤں میں کانٹے ہوں گے، اور تمہیں اس زمین میں پریشان کریں گے جہاں تم رہتے ہو۔\n56۔ مزید یہ کہ ایسا ہوگا، {وہ} میں تمہارے ساتھ کروں گا، جیسا میں نے ان کے ساتھ کرنے کا سوچا تھا۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل کو حکم دو، اور ان سے کہو، جب تم کنعان کی سرزمین میں آؤ؛ (یہ وہ زمین ہے جو تمہیں وراثت کے لیے ملے گی، {حتیٰ کہ} کنعان کی زمین اور اس کے ساحلوں کے ساتھ:)\n3۔ پھر تمہارا جنوبی حصہ زین کے صحرا سے ایڈم کے ساحل کے ساتھ ہوگا، اور تمہاری جنوبی سرحد نمکین سمندر کا مشرق کی طرف سب سے دور کا ساحل ہوگا:\n4۔ اور تمہاری سرحد جنوب سے اکرب کی چڑھائی کی طرف مڑے گی، اور زین تک جائے گی: اور اس کا راستہ جنوب سے کدیشبرنیا تک ہوگا، پھر ہزارادر تک جائے گا، اور پھر ازمون تک جائے گا:\n5۔ اور سرحد ازمون سے مصر کے دریا تک ایک کمپاس لے کر آئے گی، اور اس سے نکلنے کا راستہ سمندر کے کنارے ہوگا۔\n6۔ اور {جہاں تک}مغربی سرحد کا تعلق ہے، تمہیں عظیم سمندر بھی سرحد کے طور پر ملے گا: یہ تمہاری مغربی سرحد ہوگی۔\n7۔ اور یہ تمہاری شمالی سرحد ہوگی: عظیم سمندر سے تم اپنے لیے کوہ ہور کی نشاندہی کرو گے:\n8۔ کوہ ہور سے آپ اپنی سرحد ہامات کے داخلی راستے کی طرف دکھائیں گے؛ اور سرحد سے باہر جانے کا راستہ زیداد کے لیے ہوگا:\n9۔ اور سرحد زیفرون تک جائے گی، اور اس سے نکلنا ہزارنان تک ہوگا: یہ تمہاری شمالی سرحد ہوگی۔\n10۔ اور تم اپنی مشرقی سرحد ہزارنان سے شیفام تک دکھاؤ گے:\n11۔ اور ساحل شیفام سے ربلہ تک جائے گا، عین کے مشرقی کنارے پر؛ اور سرحد نیچے آئے گی، اور چنیرتھ کے سمندر کے کنارے مشرق کی طرف جائے گی: {سمندر کے کنارے: عبرانی۔ سمندر کا کندھا}\n12۔ اور سرحد اردن تک جائے گی، اور اس سے نکلنا نمکین سمندر پر ہوگا: یہ تمہاری زمین ہوگی اور اس کے کنارے اس کے گرد ہوں گے۔\n13۔ اور موسیٰ نے بنی اسرائیل کو حکم دیا، کہا، یہ وہ زمین ہے جو تم قرعہ اندازی کے ذریعے وارث بناؤ گے، جسے خداوند نے نو قبائل اور آدھے قبیلے کو دینے کا حکم دیا ہے:\n14۔ کیونکہ روبن کے بچوں کے قبیلے نے اپنے باپ دادا کے گھر کے مطابق اور گاد کے بچوں کے قبیلے کو ان کے باپوں کے گھر کے مطابق {ان کی وراثت} حاصل کی ہے؛ اور مناسی قبیلے کے آدھے لوگوں نے اپنی وراثت حاصل کر لی ہے:\n15۔ دونوں قبائل اور آدھے قبیلے نے اس طرف اردن {قریب} یریحو کی طرف اپنی وراثت حاصل کی ہے، سورج نکلنے کی طرف۔\n16۔ اور خداوند نے موسیٰ سے کہا،\n17۔ یہ وہ لوگ ہیں جو زمین کو تمہارے لیے تقسیم کریں گے: الیعزر کاہن اور یشوع نون کا بیٹا۔\n18۔ اور تم ہر قبیلے کا ایک شہزادہ لے کر زمین کو وراثت سے تقسیم کرو گے۔\n19۔ اور ان لوگوں کے نام یہ ہیں: یہوداہ قبیلے کے، کالب، یپھونہ کا بیٹا۔\n20۔ اور شمعون کے بچوں کے قبیلے سے، شیموئیل، امیہود کا بیٹا۔\n21۔ بنیامین قبیلے سے، ایلیداد جو چسلون کا بیٹا تھا۔\n22۔ اور دان کے بچوں کے قبیلے کے شہزادے، بکی جو جوگلی کا بیٹا تھا۔\n23۔ یوسف کے بچوں کا شہزادہ، منسی کے بچوں کے قبیلے کے لیے، حنیئل ایفود کا بیٹا۔\n24۔ اور افرایم کے بچوں کے قبیلے کا شہزادہ، کیموئیل بیٹا شفتان۔\n25۔ اور زبولون کے بچوں کے قبیلے کا شہزادہ، ایلیزافان، پارناخ کا بیٹا۔\n26۔ اور اساکر کے بچوں کے قبیلے کا شہزادہ، پالتیئل، عزان کا بیٹا۔\n27۔ اور آشر کے بچوں کے قبیلے کے شہزادے، احیہود شلومی کا بیٹا۔\n28۔ اور نفتالی کے بچوں کے قبیلے کا شہزادہ، پداہیل امیہود کا بیٹا۔\n29۔ یہی وہ لوگ ہیں جنہیں خداوند نے حکم دیا کہ وہ کنعان کی سرزمین میں بنی اسرائیل کو وراثت تقسیم کریں۔","1۔ اور خداوند نے موسیٰ سے اردن کے قریب یرحاق کے میدانوں میں موسیٰ سے کہا،\n2۔ بنی اسرائیل کو حکم دو کہ وہ لاویوں کو ان کے ملکیتی شہروں کی میراث دے دیں جہاں وہ بسیں؛ اور تم لاویوں کے مضافات کو ان کے ارد گرد کے شہروں کے لیے بھی دے دو۔\n3۔ اور وہ شہر جہاں انہیں رہنا ہوگا؛ اور ان کے مضافات ان کے مویشیوں، مال اور تمام جانوروں کے لیے ہوں گے۔\n4۔ اور شہروں کے مضافات، جو تم لاویوں کو دو گے، شہر کی دیوار سے باہر ہزار ہاتھ تک پہنچیں گے۔\n5۔ اور تم شہر کے باہر سے مشرق کی طرف دو ہزار کیوبٹ، اور جنوب کی طرف دو ہزار کیوبٹ، اور مغربی طرف دو ہزار کیوبٹ، اور شمالی طرف دو ہزار کیوبٹ ناپو گے؛ اور شہر {بیچ میں} ہوگا: یہ ان کے لیے شہروں کے مضافات ہوں گے۔\n6۔ اور ان شہروں میں سے جو تم لاویوں کو دو گے {وہاں چھ شہر ہوں گے} پناہ کے لیے، جنہیں تم قاتل کے لیے مقرر کرو گے تاکہ وہ وہاں فرار ہو سکے: اور ان میں تم چالیس اور دو شہر شامل کرو گے۔ {ان کے لیے...: عبرانی۔ ان کے اوپر تم دو گے}\n7۔ {اسی طرح} وہ تمام شہر جو تم لاویوں کو دو گے، وہ چالیس اور اٹھاسی شہر ہوں گے: وہ {تم دے دو} ان کے مضافات کے ساتھ۔\n8۔ اور جو شہر تم دو گے وہ بنی اسرائیل کی ملکیت ہوں گے: جن کے پاس بہت سے ہیں ان سے تم بہت کچھ دو گے؛ لیکن جن کے پاس چند ہیں ان میں سے تم کم ہی دو گے: ہر کوئی اپنے شہروں میں سے لاویوں کو دے گا اپنی وراثت کے مطابق جو اسے وراثت میں ملے گی۔ {وہ...: عبرانی۔ وہ وراثت میں پاتے ہیں}\n9۔ اور خداوند نے موسیٰ سے کہا،\n10۔ بنی اسرائیل سے بات کرو، اور ان سے کہو، جب تم اردن کے پار کنعان کی سرزمین میں آؤ؛\n11۔ پھر تم اپنے شہروں کو پناہ کے شہر مقرر کرو گے؛ تاکہ قاتل وہاں بھاگ جائے، جو کسی کو بھی اچانک مار ڈالے۔ {پر...: عبرانی۔ غلطی سے}\n12۔ اور وہ تمہارے لیے انتقام لینے والے سے پناہ کے لیے شہر ہوں گے؛ کہ مانسلیئر نہ مرے جب تک کہ وہ جماعت کے سامنے عدالت میں کھڑا نہ ہو۔\n13۔ اور ان شہروں میں سے جنہیں تم چھ شہر دو گے، تمہیں پناہ ملے گی۔\n14۔ تم اس طرف اردن کے تین شہر دو گے، اور کنعان کی زمین میں تین شہر دو گے، {جو} پناہ کے شہر ہوں گے۔\n15۔ یہ چھ شہر اسرائیل کے لیے پناہ گاہ ہوں گے، نہ صرف اجنبی، اور ان میں سے رہنے والے کے لیے، تاکہ جو بھی کسی کو بے خبری میں قتل کرے وہ وہاں بھاگ جائے۔\n16۔ اور اگر وہ اسے لوہے کے آلے سے مارے تاکہ وہ مر جائے، تو وہ قاتل ہے: قاتل کو ضرور موت دی جائے گی۔\n17۔ اور اگر وہ اسے پتھر پھینکے، جس سے وہ مر جائے، اور وہ مر جائے، تو وہ قاتل ہے: قاتل کو ضرور موت دی جائے گی۔ {ساتھ...: عبوری۔ ہاتھ کے پتھر سے}\n18۔ یا اگر وہ اسے لکڑی کے ہتھیار سے مارے، جس سے وہ مر سکتا ہے، اور وہ مر جائے تو قاتل ہوگا: قاتل کو ضرور موت دی جائے گی۔\n19۔ خون کا انتقام لینے والا خود قاتل کو قتل کرے گا: جب وہ اس سے ملے گا، تو اسے مار ڈالے گا۔\n20۔ لیکن اگر اس نے اسے نفرت سے دھکیل دیا، یا انتظار کر کے اس پر پھینک دیا، تو وہ مر جائے؛\n21۔ یا دشمنی میں اسے ہاتھ سے مارو تاکہ وہ مر جائے: جو اسے مارے گا اسے ضرور مار دیا جائے گا؛ {کیونکہ} وہ {ہے} قاتل: خون کا انتقام لینے والا قاتل کو مار ڈالے گا، جب وہ اس سے ملے گا۔\n22۔ لیکن اگر وہ اچانک بغیر دشمنی کے اسے دھکیل دے، یا اس پر کچھ ڈال دے بغیر انتظار کیے،\n23۔ یا کسی ایسے پتھر سے، جس سے کوئی انسان مر جائے، اور اسے نہ دیکھ کر اس پر پھینک دے، کہ وہ مر جائے، اور نہ ہی اس کا دشمن تھا، نہ ہی اس کا نقصان پہنچانے کی کوشش کی:\n24۔ پھر جماعت قاتل اور خون کے انتقام لینے والے کے درمیان ان فیصلوں کے مطابق فیصلہ کرے گی:\n25۔ اور جماعت قاتل کو خون کے انتقام لینے والے کے ہاتھ سے آزاد کرے گی، اور جماعت اسے اس کے پناہ گاہ کے شہر میں واپس لے جائے گی، جہاں سے وہ بھاگا تھا: اور وہ اس میں اس وقت تک رہے گا جب تک کہ بڑے پادری کی موت نہ ہو، جسے مقدس تیل سے مسح کیا گیا تھا۔\n26۔ لیکن اگر قاتل کسی بھی وقت اپنے پناہ گاہ کے شہر کی سرحد سے باہر آئے، جہاں سے وہ فرار ہوا تھا؛\n27۔ اور خون کا انتقام لینے والا اسے اس کے پناہ گاہ کے شہر کی سرحدوں کے بغیر پائے گا، اور خون کا انتقام لینے والا قاتل کو مار ڈالے؛ وہ خون کا مجرم نہیں ہوگا: {وہ...: عبرانی۔ اس کے لیے کوئی خون نہیں ہوگا}\n28۔ کیونکہ اسے اپنے پناہ گاہ کے شہر میں رہنا چاہیے تھا جب تک کہ اعلیٰ کاہن کی موت نہ ہو جائے: لیکن اعلیٰ کاهن کی موت کے بعد قاتل اپنی ملکیت کی زمین میں واپس آ جائے گا۔\n29۔ تو یہ {چیزیں} تمہارے لیے تمہاری تمام رہائش گاہوں میں نسل در نسل فیصلے کے لیے ہوں گی۔\n30۔ جو شخص کسی کو قتل کرے گا، اسے گواہوں کے منہ سے موت دی جائے گی: لیکن ایک گواہ کسی کے خلاف گواہی نہیں دے گا {جس سے وہ مر جائے}۔\n31۔ مزید برآں، آپ کو قاتل کی جان کے لیے کوئی تسکین نہیں ملے گی، جو موت کا مجرم ہو، لیکن اسے ضرور موت دی جائے گی۔ {قصوروار...: عبرانی۔ مرنے کے لیے خراب ہے}\n32۔ اور آپ اس شخص کے لیے کوئی تسکین نہیں مانگے گے جو اس کے پناہ گاہ کے شہر میں بھاگ گیا ہے، کہ وہ دوبارہ زمین میں آ کر بسے، جب تک کہ پادری کی موت نہ ہو جائے۔\n33۔ تو تم اس زمین کو آلودہ نہیں کرو گے جس میں تم ہو، کیونکہ خون زمین کو آلودہ کرتا ہے؛ اور زمین اس خون سے پاک نہیں ہو سکتی جو وہاں بہایا جاتا ہے، بلکہ اس کے خون سے جو اسے بہاتا ہے۔ {زمین نہیں کر سکتی...: عبرانی۔ زمین کا کوئی کفارہ نہیں ہو سکتا}\n34۔ اس لیے اس زمین کو ناپاک نہ کرو جس میں تم رہو گے، جہاں میں رہتا ہوں، کیونکہ میں خداوند بنی اسرائیل کے درمیان رہتا ہوں۔","1۔ اور گلعاد کے بچوں کے خاندانوں کے سربراہ، جو مخیر کا بیٹا تھا، منسی کا بیٹا، یوسف کے بیٹوں کے خاندانوں میں سے تھے، قریب آئے، اور موسیٰ کے سامنے اور شہزادوں کے سامنے بولے، جو بنی اسرائیل کے سردار تھے:\n2۔ اور انہوں نے کہا، خداوند نے میرے رب کو حکم دیا ہے کہ وہ زمین کو قرعہ اندازی کے ذریعے بنی اسرائیل کو وراثت میں دے دے: اور میرے رب کو خداوند نے حکم دیا کہ وہ ہمارے بھائی زیلوفہد کی وراثت اپنی بیٹیوں کو دے دے۔\n3۔ اور اگر وہ بنی اسرائیل کے {دوسرے} قبیلوں کے کسی بیٹے سے شادی شدہ ہوں، تو ان کی وراثت ہمارے آباؤ اجداد کی وراثت سے لی جائے گی، اور اسے اس قبیلے کی وراثت میں شامل کیا جائے گا جہاں وہ وصول کیے جائیں گے: اسی طرح یہ ہماری وراثت کی قسمت سے لی جائے گی۔ {کہاں...: عبرانی۔ وہ کس کے لیے ہوں گے}\n4۔ اور جب بنی اسرائیل کی یوبیل ہوگی، تو ان کی وراثت اس قبیلے کی وراثت میں ڈال دی جائے گی جس میں انہیں وصول کیا جائے گا: اسی طرح ان کی میراث ہمارے آباؤ اجداد کے قبیلے کی وراثت سے چھین لی جائے گی۔ {کہاں...: عبرانی۔ وہ کس کے لیے ہوں گے}\n5۔ اور موسیٰ نے بنی اسرائیل کو خداوند کے کلام کے مطابق حکم دیا، کہا، یوسف کے بیٹوں کے قبیلے نے اچھی بات کہی ہے۔\n6۔ یہ وہ چیز ہے جو خداوند زیلوفہد کی بیٹیوں کے بارے میں حکم دیتا ہے، کہتا ہے: انہیں جس سے وہ بہتر سمجھتی ہیں اس سے شادی کرے؛ وہ صرف اپنے والد کے قبیلے کے خاندان سے شادی کریں گے۔ {شادی: عبرانی۔ بیویاں بنیں}\n7۔ اسی طرح بنی اسرائیل کی وراثت قبیلے سے قبیلے میں نہیں جائے گی: کیونکہ ہر ایک بنی اسرائیل اپنے باپ و اجداد کے قبیلے کی وراثت کو برقرار رکھے گا۔ {برقرار رکھو...: عبوری۔ اس سے چمٹ جاؤ، وغیرہ}\n8۔ اور ہر بیٹی، جو بنی اسرائیل کے کسی قبیلے میں وراثت رکھتی ہے، وہ اپنے باپ کے قبیلے کے خاندان میں سے کسی ایک کی بیوی بنے گی، تاکہ اسرائیل کے بچے ہر مرد کو اپنے باپ کی وراثت سے فائدہ اٹھا سکیں۔\n9۔ نہ ہی وراثت {ایک} قبیلے سے دوسرے قبیلے کو منتقل نہیں ہوگی؛ لیکن بنی اسرائیل کے ہر قبیلے کو اپنی وراثت پر قائم رہنا چاہیے۔\n10۔ جیسے خداوند نے موسیٰ کو حکم دیا، اسی طرح زیلوفحاد کی بیٹیوں نے بھی حکم دیا:\n11۔ کیونکہ مہلہ، تیرزا، اور ہوگلہ، ملکہ، اور نوح، زیلوفحاد کی بیٹیاں، اپنے والد کے بھائیوں کے بیٹوں سے شادی شدہ تھیں:\n12۔ {اور} ان کی شادی منسی کے بیٹے یوسف کے بیٹے کے خاندانوں میں ہوئی، اور ان کی وراثت ان کے والد کے خاندان کے قبیلے میں رہی۔ {میں...: عبرانی میں۔ کچھ خاندانوں کے لیے}\n13۔ یہ وہ احکامات اور فیصلے ہیں جو خداوند نے موسیٰ کے ہاتھوں موآب کے میدانوں میں اردن کے قریب یرحاق کے قریب بنی اسرائیل کو حکم دیے۔"];
